INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "How to pray: what is said where", "bn": "নামাজের নিয়ম: কোথায় কী পড়ি"}', 'fiqh', 'easy', NULL, 10, 'in_review', 101) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('056b4249-371b-56f3-9b31-26633bacae4f', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "What is said while bowing in ruku‘?", "bn": "রুকুতে কী পড়া হয়?"}', '{"en": "\"Glory be to my Lord, the Most Great\" — the Prophet ﷺ said this in his ruku‘.", "bn": "\"আমার মহান রবের পবিত্রতা ঘোষণা করছি\" — নবী ﷺ রুকুতে এটি পড়তেন।"}', 'Sahih Muslim 772', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('77ba13d5-812b-54d9-8c86-4a6021a94697', '056b4249-371b-56f3-9b31-26633bacae4f', '{"en": "Subhana Rabbiyal-‘Azim", "bn": "সুবহানা রাব্বিয়াল আযিম"}', true, 1), ('816cbc25-bd2a-5357-b97d-4a683530cc6d', '056b4249-371b-56f3-9b31-26633bacae4f', '{"en": "Subhana Rabbiyal-A‘la", "bn": "সুবহানা রাব্বিয়াল আ‘লা"}', false, 2), ('92aec384-aa09-58ec-88be-e7b7b051f1c9', '056b4249-371b-56f3-9b31-26633bacae4f', '{"en": "Sami‘Allahu liman hamidah", "bn": "সামি‘আল্লাহু লিমান হামিদাহ"}', false, 3), ('912b8312-a36e-58dd-aeca-2a1c3d09b3a5', '056b4249-371b-56f3-9b31-26633bacae4f', '{"en": "Rabbighfir li", "bn": "রাব্বিগফিরলি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('292d65b7-dcb6-545d-8553-9b7ede356548', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "What is said in sujud (prostration)?", "bn": "সিজদায় কী পড়া হয়?"}', '{"en": "\"Glory be to my Lord, the Most High\" — said in sujud.", "bn": "\"আমার সর্বোচ্চ রবের পবিত্রতা ঘোষণা করছি\" — সিজদায় পড়া হয়।"}', 'Sahih Muslim 772', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('77bcd951-b46c-53b5-ab63-58bc3ff0ab27', '292d65b7-dcb6-545d-8553-9b7ede356548', '{"en": "Subhana Rabbiyal-‘Azim", "bn": "সুবহানা রাব্বিয়াল আযিম"}', false, 1), ('54c2eb11-b7cd-5a32-902a-40a09889ae31', '292d65b7-dcb6-545d-8553-9b7ede356548', '{"en": "Allahu Akbar kabira", "bn": "আল্লাহু আকবার কাবিরা"}', false, 2), ('599f29f6-d9c3-53fa-a87a-a5985d94c55d', '292d65b7-dcb6-545d-8553-9b7ede356548', '{"en": "Subhana Rabbiyal-A‘la", "bn": "সুবহানা রাব্বিয়াল আ‘লা"}', true, 3), ('1df4ad60-7100-5e2d-9445-4a55e685bd02', '292d65b7-dcb6-545d-8553-9b7ede356548', '{"en": "At-tahiyyatu lillah", "bn": "আত্তাহিয়্যাতু লিল্লাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c2d1c2a6-5107-5998-9cbf-84fbb4e5b8e4', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "Rising from ruku‘, the imam or one praying alone says…?", "bn": "রুকু থেকে ওঠার সময় ইমাম বা একা নামাজি কী বলেন?"}', '{"en": "He ﷺ said \"Sami‘Allahu liman hamidah\" while raising his back from ruku‘, then \"Rabbana wa lakal-hamd\" standing.", "bn": "নবী ﷺ রুকু থেকে পিঠ তোলার সময় \"সামি‘আল্লাহু লিমান হামিদাহ\" এবং দাঁড়িয়ে \"রাব্বানা ওয়া লাকাল হামদ\" বলতেন।"}', 'Sahih al-Bukhari 789', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f2dd55dc-8218-557f-851a-d244f6c6324f', 'c2d1c2a6-5107-5998-9cbf-84fbb4e5b8e4', '{"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}', false, 1), ('e0f28d00-a3bd-5e16-85fc-d859e0e34b84', 'c2d1c2a6-5107-5998-9cbf-84fbb4e5b8e4', '{"en": "Sami‘Allahu liman hamidah", "bn": "সামি‘আল্লাহু লিমান হামিদাহ"}', true, 2), ('e7586875-81ff-51d8-ba2c-acd3b7c4d168', 'c2d1c2a6-5107-5998-9cbf-84fbb4e5b8e4', '{"en": "As-salamu ‘alaykum", "bn": "আসসালামু আলাইকুম"}', false, 3), ('b532ebb5-f7fe-508a-9018-4637a2bcd02a', 'c2d1c2a6-5107-5998-9cbf-84fbb4e5b8e4', '{"en": "Bismillah", "bn": "বিসমিল্লাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('34358ea7-a028-58b0-b5b3-91be6d476412', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "What does \"Sami‘Allahu liman hamidah\" mean?", "bn": "\"সামি‘আল্লাহু লিমান হামিদাহ\" অর্থ কী?"}', '{"en": "Sami‘a = hears, liman = the one who, hamidah = praised Him.", "bn": "সামি‘আ = শোনেন, লিমান = যে, হামিদাহ = তাঁর প্রশংসা করল।"}', 'Sahih al-Bukhari 789', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9da194be-cc5f-5bfa-ba2a-37c09822bbd1', '34358ea7-a028-58b0-b5b3-91be6d476412', '{"en": "Allah is the Greatest", "bn": "আল্লাহ সবচেয়ে বড়"}', false, 1), ('86cf17b2-8601-544a-933c-e9994b016e3e', '34358ea7-a028-58b0-b5b3-91be6d476412', '{"en": "Glory be to Allah", "bn": "আল্লাহ পবিত্র"}', false, 2), ('bec46e22-9210-5bc7-8161-e47d30a11f84', '34358ea7-a028-58b0-b5b3-91be6d476412', '{"en": "Our Lord, to You is all praise", "bn": "হে আমাদের রব, সব প্রশংসা আপনার"}', false, 3), ('332e3fd3-9cb4-57ff-97bb-16504ae31b40', '34358ea7-a028-58b0-b5b3-91be6d476412', '{"en": "Allah hears the one who praises Him", "bn": "যে আল্লাহর প্রশংসা করে, আল্লাহ তার কথা শোনেন"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2a0a6528-067b-5b00-a46a-68d9c55255a5', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "What is recited in the sitting (tashahhud)?", "bn": "বৈঠকে (তাশাহহুদে) কী পড়া হয়?"}', '{"en": "Ibn Mas‘ud (RA) said the Prophet ﷺ taught him the tashahhud as he taught a surah: \"At-tahiyyatu lillah…\".", "bn": "ইবনে মাসউদ (রা.) বলেন, নবী ﷺ তাঁকে সূরা শেখানোর মতো করে তাশাহহুদ শিখিয়েছেন: \"আত্তাহিয়্যাতু লিল্লাহ…\"।"}', 'Sahih al-Bukhari 831; Sahih al-Bukhari 6265', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('42b30f28-a1f4-5d14-827c-c9b3ae0a1b26', '2a0a6528-067b-5b00-a46a-68d9c55255a5', '{"en": "At-tahiyyatu lillahi was-salawatu…", "bn": "আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু…"}', true, 1), ('416c7492-739b-532b-ac83-28254f4cb7ec', '2a0a6528-067b-5b00-a46a-68d9c55255a5', '{"en": "Ayat al-Kursi", "bn": "আয়াতুল কুরসি"}', false, 2), ('1424d8ba-201c-53ab-9863-b06130437cd6', '2a0a6528-067b-5b00-a46a-68d9c55255a5', '{"en": "Surah al-Ikhlas", "bn": "সূরা ইখলাস"}', false, 3), ('44395f72-2d29-5045-9f7f-0d34e28c8733', '2a0a6528-067b-5b00-a46a-68d9c55255a5', '{"en": "The adhan", "bn": "আজান"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('898a9341-7ff5-5335-8001-b1f59469b025', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "Which salawat is recited in the last sitting, after the tashahhud?", "bn": "শেষ বৈঠকে তাশাহহুদের পর কোন দরুদ পড়া হয়?"}', '{"en": "The companions asked how to send salawat; he ﷺ taught \"Allahumma salli ‘ala Muhammad… as You sent blessings on Ibrahim…\".", "bn": "সাহাবিরা দরুদ পড়ার নিয়ম জানতে চাইলে নবী ﷺ শেখালেন: \"আল্লাহুম্মা সাল্লি আলা মুহাম্মাদ… যেমন আপনি ইবরাহিমের ওপর রহমত পাঠিয়েছেন…\"।"}', 'Sahih al-Bukhari 3370', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('56e9022b-6f6f-5cd8-9760-dd99afbf44c2', '898a9341-7ff5-5335-8001-b1f59469b025', '{"en": "Salawat with \"Subhanakallahumma\"", "bn": "\"সুবহানাকাল্লাহুম্মা\" দিয়ে দরুদ"}', false, 1), ('a7bd2c45-74dc-5682-934a-33b2cd538fab', '898a9341-7ff5-5335-8001-b1f59469b025', '{"en": "Durud Ibrahim: \"…kama sallayta ‘ala Ibrahim…\"", "bn": "দরুদে ইবরাহিম: \"…কামা সাল্লাইতা আলা ইবরাহিম…\""}', true, 2), ('a0b6e4fa-2878-5ba8-bf41-af1c1fc52253', '898a9341-7ff5-5335-8001-b1f59469b025', '{"en": "Surah al-Kawthar", "bn": "সূরা কাওসার"}', false, 3), ('f8636b47-1307-5c5d-8a24-13ff233e695e', '898a9341-7ff5-5335-8001-b1f59469b025', '{"en": "The talbiyah", "bn": "তালবিয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d1cc24f3-e4b0-515e-a410-2f6e142274c5', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "Which short dua did the Prophet ﷺ say between the two prostrations?", "bn": "দুই সিজদার মাঝে নবী ﷺ কোন ছোট দোয়া পড়তেন?"}', '{"en": "Hudhayfah (RA) heard him say between the two sujud: \"Rabbighfir li, Rabbighfir li\".", "bn": "হুযাইফা (রা.) শুনেছেন, নবী ﷺ দুই সিজদার মাঝে বলতেন: \"রাব্বিগফিরলি, রাব্বিগফিরলি\"।"}', 'Sunan Abi Dawud 874; Sunan Ibn Majah 897', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('23cf43a8-86db-5f10-b6b7-a40ba85dfad9', 'd1cc24f3-e4b0-515e-a410-2f6e142274c5', '{"en": "Rabbana atina", "bn": "রাব্বানা আতিনা"}', false, 1), ('e4ac98f5-2743-52d7-8ea0-247343635374', 'd1cc24f3-e4b0-515e-a410-2f6e142274c5', '{"en": "Subhanallah", "bn": "সুবহানাল্লাহ"}', false, 2), ('47b6568b-c531-5df8-b3f8-bc8aa762145f', 'd1cc24f3-e4b0-515e-a410-2f6e142274c5', '{"en": "Rabbighfir li (My Lord, forgive me)", "bn": "রাব্বিগফিরলি (হে আমার রব, আমাকে ক্ষমা করুন)"}', true, 3), ('bf47e3a9-2a18-57fe-9448-03a73b768304', 'd1cc24f3-e4b0-515e-a410-2f6e142274c5', '{"en": "Bismillah", "bn": "বিসমিল্লাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('154917c5-e1e5-5d64-807c-4fe80619f329', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "How many sujud (prostrations) are in each rak‘ah?", "bn": "প্রতি রাকাতে কয়টি সিজদা?"}', '{"en": "The Prophet ﷺ taught: prostrate, then sit up, then prostrate again.", "bn": "নবী ﷺ শিখিয়েছেন: সিজদা করো, তারপর উঠে বসো, তারপর আবার সিজদা করো।"}', 'Sahih al-Bukhari 757', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('15db062e-ea13-5d62-9ce4-3d355a4d52e6', '154917c5-e1e5-5d64-807c-4fe80619f329', '{"en": "1", "bn": "১"}', false, 1), ('db692fa1-2a39-58d2-9323-bd4dfd64ac6f', '154917c5-e1e5-5d64-807c-4fe80619f329', '{"en": "3", "bn": "৩"}', false, 2), ('011919f1-4137-588c-a18f-96209eed4a7b', '154917c5-e1e5-5d64-807c-4fe80619f329', '{"en": "4", "bn": "৪"}', false, 3), ('32fc4730-1ea7-5e32-90d3-ece1ac98c01c', '154917c5-e1e5-5d64-807c-4fe80619f329', '{"en": "2", "bn": "২"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1522be42-2db0-528e-8c4c-9937dfacd7dc', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "What does \"Subhana Rabbiyal-A‘la\" mean?", "bn": "\"সুবহানা রাব্বিয়াল আ‘লা\" অর্থ কী?"}', '{"en": "Subhana = glory be to, Rabbiya = my Lord, al-A‘la = the Most High.", "bn": "সুবহানা = পবিত্রতা ঘোষণা, রাব্বিয়া = আমার রব, আল-আ‘লা = সর্বোচ্চ।"}', 'Sahih Muslim 772', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9c4e42c1-c21e-5db3-9a55-90577e76411c', '1522be42-2db0-528e-8c4c-9937dfacd7dc', '{"en": "Glory be to my Lord, the Most High", "bn": "আমার সর্বোচ্চ রবের পবিত্রতা ঘোষণা করছি"}', true, 1), ('032703b0-f3a9-58aa-b97c-fdae319db68c', '1522be42-2db0-528e-8c4c-9937dfacd7dc', '{"en": "My Lord, forgive me", "bn": "হে আমার রব, আমাকে ক্ষমা করুন"}', false, 2), ('11493080-4f68-5c2d-99ce-fd8009299239', '1522be42-2db0-528e-8c4c-9937dfacd7dc', '{"en": "Allah is the Greatest", "bn": "আল্লাহ সবচেয়ে বড়"}', false, 3), ('3028fccf-e8b4-5360-b387-88162d6b698d', '1522be42-2db0-528e-8c4c-9937dfacd7dc', '{"en": "All praise is for Allah", "bn": "সব প্রশংসা আল্লাহর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5f6af4fd-f598-53f2-aaa4-6e424988c165', 'c973842a-6876-5eb0-8483-e1106dd6d9ab', '{"en": "The opening praise \"Subhanakallahumma wa bihamdika…\" (sana) is recited…?", "bn": "সানা \"সুবহানাকাল্লাহুম্মা ওয়া বিহামদিকা…\" কখন পড়া হয়?"}', '{"en": "‘A’ishah (RA): when he ﷺ began the prayer he said \"Subhanakallahumma wa bihamdika…\". (There are other opening duas too.)", "bn": "আয়েশা (রা.): নবী ﷺ নামাজ শুরু করে বলতেন \"সুবহানাকাল্লাহুম্মা ওয়া বিহামদিকা…\"। (শুরুর আরও দোয়া বর্ণিত আছে।)"}', 'Sunan Abi Dawud 776; Jami‘ at-Tirmidhi 243', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c80957ec-6b13-5750-be51-d8b4947a6334', '5f6af4fd-f598-53f2-aaa4-6e424988c165', '{"en": "After the salam", "bn": "সালামের পর"}', false, 1), ('4af3a151-6e01-51a9-94b5-d84a37f45e51', '5f6af4fd-f598-53f2-aaa4-6e424988c165', '{"en": "In ruku‘", "bn": "রুকুতে"}', false, 2), ('af5a7524-6006-5c16-983b-e3675ff0a891', '5f6af4fd-f598-53f2-aaa4-6e424988c165', '{"en": "After the opening takbir, before al-Fatiha", "bn": "শুরুর তাকবিরের পর, সূরা ফাতিহার আগে"}', true, 3), ('307a865b-b18c-520e-b95c-f801f0b5322d', '5f6af4fd-f598-53f2-aaa4-6e424988c165', '{"en": "Between the two sujud", "bn": "দুই সিজদার মাঝে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "Salah: times and rules", "bn": "নামাজ: ওয়াক্ত ও নিয়ম"}', 'fiqh', 'medium', NULL, 10, 'in_review', 102) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ff88f99c-7724-59d4-a2f6-aa07b392fd11', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "When does the time of Maghrib begin?", "bn": "মাগরিবের ওয়াক্ত কখন শুরু হয়?"}', '{"en": "\"The time of Maghrib is when the sun has set, as long as the twilight has not gone.\"", "bn": "\"সূর্য ডোবার পর থেকে লালিমা মিলিয়ে যাওয়া পর্যন্ত মাগরিবের সময়।\""}', 'Sahih Muslim 612', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('4e5ce09a-ebf3-5c24-ad48-cd9ebf65fbb6', 'ff88f99c-7724-59d4-a2f6-aa07b392fd11', '{"en": "At sunset", "bn": "সূর্যাস্তের সঙ্গে সঙ্গে"}', true, 1), ('7f1f7e44-6eda-5483-8657-cc1ff88487ae', 'ff88f99c-7724-59d4-a2f6-aa07b392fd11', '{"en": "At midday", "bn": "দুপুরে"}', false, 2), ('f0c52eb6-08b2-5733-bac2-04cd4f3254f5', 'ff88f99c-7724-59d4-a2f6-aa07b392fd11', '{"en": "At dawn", "bn": "ভোরে"}', false, 3), ('683a87b5-ec7b-5cd8-a949-4caded8eca60', 'ff88f99c-7724-59d4-a2f6-aa07b392fd11', '{"en": "At midnight", "bn": "মধ্যরাতে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('24e9411a-67ca-5026-b9b1-9f679a91cc8f', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "How many fard rak‘ahs does Asr have (when not travelling)?", "bn": "আসরে কয় রাকাত ফরজ (মুসাফির না হলে)?"}', '{"en": "Dhuhr, Asr and Isha each have four fard rak‘ahs for one who is not travelling.", "bn": "মুসাফির না হলে যোহর, আসর ও এশায় চার রাকাত করে ফরজ।"}', 'Sahih al-Bukhari 350', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('788f2ffc-94a1-5de2-b74f-09ee70fb1ac0', '24e9411a-67ca-5026-b9b1-9f679a91cc8f', '{"en": "2", "bn": "২"}', false, 1), ('19ff435b-e3e2-5dee-b358-b7f68fb68886', '24e9411a-67ca-5026-b9b1-9f679a91cc8f', '{"en": "3", "bn": "৩"}', false, 2), ('fccd465d-14f0-5dc5-9ec8-ed9a3453611d', '24e9411a-67ca-5026-b9b1-9f679a91cc8f', '{"en": "4", "bn": "৪"}', true, 3), ('483c84a2-6d18-5e2a-b028-a19339125b09', '24e9411a-67ca-5026-b9b1-9f679a91cc8f', '{"en": "6", "bn": "৬"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e6b2748f-34db-5e36-99f5-8d23a7461125', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "How many fard rak‘ahs does the Jumu‘ah prayer have?", "bn": "জুমার নামাজে কয় রাকাত ফরজ?"}', '{"en": "‘Umar (RA): \"The Friday prayer is two rak‘ahs… on the tongue of your Prophet ﷺ.\"", "bn": "উমর (রা.): \"জুমার নামাজ দুই রাকাত… তোমাদের নবী ﷺ-এর ভাষায়।\""}', 'Sunan an-Nasa’i 1420', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('60656a42-26ee-5440-a92a-5408c66a0aa6', 'e6b2748f-34db-5e36-99f5-8d23a7461125', '{"en": "4", "bn": "৪"}', false, 1), ('e853eab0-6af4-5195-9e4d-e41b489dffee', 'e6b2748f-34db-5e36-99f5-8d23a7461125', '{"en": "2", "bn": "২"}', true, 2), ('c8a5703d-bb41-59a2-a547-02aa72a02f1f', 'e6b2748f-34db-5e36-99f5-8d23a7461125', '{"en": "3", "bn": "৩"}', false, 3), ('9dc0f0e8-0a42-503e-a421-9df3006e03ee', 'e6b2748f-34db-5e36-99f5-8d23a7461125', '{"en": "1", "bn": "১"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0dc32ced-9186-5760-bae8-98426d59541f', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "Prayer in congregation is better than praying alone by how many degrees, in Ibn ‘Umar’s narration?", "bn": "ইবনে উমর (রা.)-এর বর্ণনায় জামাতে নামাজ একা নামাজের চেয়ে কত গুণ উত্তম?"}', '{"en": "\"Prayer in congregation is better than prayer alone by twenty-seven degrees.\" (Another narration says twenty-five.)", "bn": "\"জামাতের নামাজ একাকী নামাজের চেয়ে সাতাশ গুণ উত্তম।\" (আরেক বর্ণনায় পঁচিশ গুণ।)"}', 'Sahih al-Bukhari 645', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('228b3220-99e0-5225-9568-ad0d7740f978', '0dc32ced-9186-5760-bae8-98426d59541f', '{"en": "10", "bn": "১০"}', false, 1), ('7e0c492a-f725-5b92-8b74-8ee967876dbd', '0dc32ced-9186-5760-bae8-98426d59541f', '{"en": "70", "bn": "৭০"}', false, 2), ('a8f1c556-5dad-5545-ba9c-823f88c055f8', '0dc32ced-9186-5760-bae8-98426d59541f', '{"en": "27", "bn": "২৭"}', true, 3), ('ec5b4a9e-926f-574d-83b8-25baa6057e01', '0dc32ced-9186-5760-bae8-98426d59541f', '{"en": "100", "bn": "১০০"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6bdccd62-e254-5d57-b149-5f448e9069f1', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "A traveller shortens which prayers from four rak‘ahs to two?", "bn": "মুসাফির কোন নামাজগুলো চার রাকাত থেকে দুই রাকাত পড়েন?"}', '{"en": "Only the four-rak‘ah prayers are shortened; Fajr stays two and Maghrib three.", "bn": "শুধু চার রাকাতের নামাজ কসর হয়; ফজর দুই আর মাগরিব তিন রাকাতই থাকে।"}', 'Quran 4:101; Sahih al-Bukhari 1090', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d7ec197b-e653-537a-a580-baf3ddf40352', '6bdccd62-e254-5d57-b149-5f448e9069f1', '{"en": "Fajr and Maghrib", "bn": "ফজর ও মাগরিব"}', false, 1), ('dda87b8b-cb14-5ac7-856b-4e9ce33fd9af', '6bdccd62-e254-5d57-b149-5f448e9069f1', '{"en": "All five", "bn": "পাঁচ ওয়াক্তই"}', false, 2), ('982ffee9-ccd1-5b41-b746-8048e5cee6e2', '6bdccd62-e254-5d57-b149-5f448e9069f1', '{"en": "Maghrib only", "bn": "শুধু মাগরিব"}', false, 3), ('fb936532-6e89-5075-9de3-b9500a4b6208', '6bdccd62-e254-5d57-b149-5f448e9069f1', '{"en": "Dhuhr, Asr and Isha", "bn": "যোহর, আসর ও এশা"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6f9f26bc-121e-5243-98b7-a5c857ffab4b', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "Which two prayers did the Prophet ﷺ call the heaviest for the hypocrites?", "bn": "নবী ﷺ কোন দুই নামাজকে মুনাফিকদের জন্য সবচেয়ে ভারী বলেছেন?"}', '{"en": "\"No prayer is heavier for the hypocrites than Fajr and Isha; if they knew what is in them they would come even crawling.\"", "bn": "\"মুনাফিকদের জন্য ফজর ও এশার চেয়ে ভারী কোনো নামাজ নেই; এতে কী আছে জানলে হামাগুড়ি দিয়ে হলেও আসত।\""}', 'Sahih al-Bukhari 657', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('046ec628-365d-5904-afcc-780eaddcace4', '6f9f26bc-121e-5243-98b7-a5c857ffab4b', '{"en": "Isha and Fajr", "bn": "এশা ও ফজর"}', true, 1), ('14048d01-eff7-55b9-8a3c-4676d32c035c', '6f9f26bc-121e-5243-98b7-a5c857ffab4b', '{"en": "Dhuhr and Asr", "bn": "যোহর ও আসর"}', false, 2), ('abab9033-ae61-5b83-8e81-03b7791f2a35', '6f9f26bc-121e-5243-98b7-a5c857ffab4b', '{"en": "Maghrib and Isha", "bn": "মাগরিব ও এশা"}', false, 3), ('91ccc6c3-2a16-55c9-b9ca-f257fa7915f8', '6f9f26bc-121e-5243-98b7-a5c857ffab4b', '{"en": "Jumu‘ah and Eid", "bn": "জুমা ও ঈদ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6470490a-cd34-5444-8aad-938452351f21', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "\"Whoever prays the two cool prayers will enter Paradise.\" Which two?", "bn": "\"যে দুই শীতল সময়ের নামাজ পড়ে সে জান্নাতে যাবে।\" কোন দুটি?"}', '{"en": "The \"two cool prayers\" are Fajr and Asr, at the cool ends of the day.", "bn": "\"দুই শীতল নামাজ\" হলো দিনের দুই শীতল প্রান্তের ফজর ও আসর।"}', 'Sahih al-Bukhari 574', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8fdb2543-394b-550e-994f-5be92de5c87f', '6470490a-cd34-5444-8aad-938452351f21', '{"en": "Dhuhr and Maghrib", "bn": "যোহর ও মাগরিব"}', false, 1), ('0c557660-dc57-58c8-b121-131300370cc6', '6470490a-cd34-5444-8aad-938452351f21', '{"en": "Fajr and Asr", "bn": "ফজর ও আসর"}', true, 2), ('3a3e6e22-d07a-5745-9bc8-fc05f80e236a', '6470490a-cd34-5444-8aad-938452351f21', '{"en": "Maghrib and Isha", "bn": "মাগরিব ও এশা"}', false, 3), ('9a95def8-d6b7-5e53-87a1-64baf526817a', '6470490a-cd34-5444-8aad-938452351f21', '{"en": "Tahajjud and Witr", "bn": "তাহাজ্জুদ ও বিতর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f4f4e29b-4c3e-5d77-ad14-6631a471d4df', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "What will a servant be asked about first on the Day of Judgement, of his deeds?", "bn": "কিয়ামতের দিন বান্দার আমলের মধ্যে প্রথমে কোনটির হিসাব নেওয়া হবে?"}', '{"en": "\"The first of his deeds a servant will be reckoned for on the Day of Resurrection is his salah.\"", "bn": "\"কিয়ামতের দিন বান্দার আমলের মধ্যে সর্বপ্রথম নামাজের হিসাব নেওয়া হবে।\""}', 'Jami‘ at-Tirmidhi 413; Sunan an-Nasa’i 465', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('56138b39-814a-59ff-9d08-41f714a212b1', 'f4f4e29b-4c3e-5d77-ad14-6631a471d4df', '{"en": "Zakat", "bn": "যাকাত"}', false, 1), ('47adcec2-0737-55ca-b359-773bad38a9aa', 'f4f4e29b-4c3e-5d77-ad14-6631a471d4df', '{"en": "Fasting", "bn": "রোজা"}', false, 2), ('baf07dd3-dfaa-53b8-9768-34c6f8eff3a0', 'f4f4e29b-4c3e-5d77-ad14-6631a471d4df', '{"en": "Salah", "bn": "নামাজ"}', true, 3), ('230ca3e2-01a2-5cf7-a34e-346b6b477f7f', 'f4f4e29b-4c3e-5d77-ad14-6631a471d4df', '{"en": "Hajj", "bn": "হজ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('02b52e41-b2c3-5cbb-8e66-290a31e87d42', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "If someone sleeps through or forgets a prayer, what should he do?", "bn": "কেউ ঘুমিয়ে বা ভুলে নামাজ ছেড়ে দিলে কী করবে?"}', '{"en": "\"Whoever forgets a prayer, let him pray it when he remembers it; there is no expiation for it but that.\"", "bn": "\"কেউ নামাজ ভুলে গেলে মনে পড়লেই পড়ে নেবে; এ ছাড়া এর কোনো কাফফারা নেই।\""}', 'Sahih al-Bukhari 597; Sahih Muslim 684', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9da4ef75-3757-50c3-a6dd-1c75c68d4105', '02b52e41-b2c3-5cbb-8e66-290a31e87d42', '{"en": "Nothing; it is gone", "bn": "কিছুই না; তা চলে গেছে"}', false, 1), ('391b1b81-5e28-5e9f-b36c-68418d4fe2fb', '02b52e41-b2c3-5cbb-8e66-290a31e87d42', '{"en": "Wait for the same time next day", "bn": "পরের দিন একই সময়ের অপেক্ষা করবে"}', false, 2), ('b4729501-e89a-5e66-811c-97bc2afd90e6', '02b52e41-b2c3-5cbb-8e66-290a31e87d42', '{"en": "Give charity instead", "bn": "তার বদলে দান করবে"}', false, 3), ('573744d3-067b-5cc7-9293-35685763d08f', '02b52e41-b2c3-5cbb-8e66-290a31e87d42', '{"en": "Pray it as soon as he remembers", "bn": "মনে পড়ামাত্র পড়ে নেবে"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5e575b5a-1fe8-5a20-a4fc-c0f05daf343c', 'f62931d3-ed48-520f-9d8b-62b0d7fd7247', '{"en": "Which surah commands: when the call is made for the Friday prayer, hasten to the remembrance of Allah and leave trade?", "bn": "কোন সূরায় আদেশ আছে: জুমার আজান হলে আল্লাহর স্মরণে ছুটে যাও এবং বেচাকেনা ছেড়ে দাও?"}', '{"en": "\"O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah and leave trade.\"", "bn": "\"হে মুমিনগণ, জুমার দিন যখন নামাজের জন্য আহ্বান করা হয়, তখন আল্লাহর স্মরণের দিকে ধাবিত হও এবং বেচাকেনা ত্যাগ করো।\""}', 'Quran 62:9', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('811a2d3c-f683-51a1-8ed9-765610864873', '5e575b5a-1fe8-5a20-a4fc-c0f05daf343c', '{"en": "Al-Jumu‘ah", "bn": "আল-জুমুআ"}', true, 1), ('a9343ef7-8a4d-5b83-be50-e154442affaf', '5e575b5a-1fe8-5a20-a4fc-c0f05daf343c', '{"en": "Al-Baqarah", "bn": "আল-বাকারা"}', false, 2), ('36886f6b-52ce-5a19-a208-4e6e66165c73', '5e575b5a-1fe8-5a20-a4fc-c0f05daf343c', '{"en": "Al-Ma’idah", "bn": "আল-মায়িদা"}', false, 3), ('f51d7bf8-f8c1-567b-a39e-65a85602ceb9', '5e575b5a-1fe8-5a20-a4fc-c0f05daf343c', '{"en": "Al-Hajj", "bn": "আল-হজ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "Wudu, ghusl & tayammum", "bn": "অজু, গোসল ও তায়াম্মুম"}', 'fiqh', 'easy', NULL, 10, 'in_review', 103) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3f3195ab-1d52-56e1-b155-bfbbd2a7a5c7', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "Which ayah of the Quran describes wudu?", "bn": "কুরআনের কোন আয়াতে অজুর বিবরণ আছে?"}', '{"en": "\"When you rise for prayer, wash your faces and your arms to the elbows, wipe your heads and wash your feet to the ankles.\"", "bn": "\"যখন নামাজে দাঁড়াতে চাও, তখন মুখমণ্ডল ও কনুই পর্যন্ত হাত ধোও, মাথা মাসেহ করো এবং টাখনু পর্যন্ত পা ধোও।\""}', 'Quran 5:6', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('46596d9c-d17b-596a-99fd-e9b484e7b455', '3f3195ab-1d52-56e1-b155-bfbbd2a7a5c7', '{"en": "Al-Baqarah 2:255", "bn": "আল-বাকারা ২:২৫৫"}', false, 1), ('81cddb64-af55-5691-b743-77439583127c', '3f3195ab-1d52-56e1-b155-bfbbd2a7a5c7', '{"en": "Al-Ma’idah 5:6", "bn": "আল-মায়িদা ৫:৬"}', true, 2), ('38766531-8d3c-58de-853a-90091cd6992c', '3f3195ab-1d52-56e1-b155-bfbbd2a7a5c7', '{"en": "Al-Ikhlas 112:1", "bn": "আল-ইখলাস ১১২:১"}', false, 3), ('813609d8-5c5d-5b23-915e-e2dfc8594960', '3f3195ab-1d52-56e1-b155-bfbbd2a7a5c7', '{"en": "Yasin 36:1", "bn": "ইয়াসিন ৩৬:১"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('56ac3a66-cf4a-5532-9986-9d828ac26b02', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "Which of these does NOT break wudu?", "bn": "নিচের কোনটি অজু ভাঙে না?"}', '{"en": "Ordinary food does not break wudu; the Prophet ﷺ ate and then prayed without a new wudu.", "bn": "সাধারণ খাবার খেলে অজু ভাঙে না; নবী ﷺ খেয়ে নতুন অজু ছাড়াই নামাজ পড়েছেন।"}', 'Sahih al-Bukhari 207', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('07c5f418-3dfe-5df6-8f37-7e5cafc92786', '56ac3a66-cf4a-5532-9986-9d828ac26b02', '{"en": "Using the toilet", "bn": "পেশাব-পায়খানা করা"}', false, 1), ('ac7552ff-4b79-5eee-95a3-a4dc56d96b0c', '56ac3a66-cf4a-5532-9986-9d828ac26b02', '{"en": "Passing wind", "bn": "বায়ু বের হওয়া"}', false, 2), ('46b0f8fe-dc47-5b71-8b20-09fbced006c7', '56ac3a66-cf4a-5532-9986-9d828ac26b02', '{"en": "Eating bread", "bn": "রুটি খাওয়া"}', true, 3), ('81133b43-bd86-57c3-83ea-ec3bb607bacd', '56ac3a66-cf4a-5532-9986-9d828ac26b02', '{"en": "Deep sleep lying down", "bn": "শুয়ে গভীর ঘুম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2b37ca10-9c26-57cd-b34d-6b43536c9dba', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "In wudu, the arms are washed up to…?", "bn": "অজুতে হাত কতটুকু ধুতে হয়?"}', '{"en": "\"…and your arms to the elbows.\"", "bn": "\"…এবং কনুই পর্যন্ত তোমাদের হাত।\""}', 'Quran 5:6', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('189ca70c-6776-5b38-a7b2-0f77dbc36820', '2b37ca10-9c26-57cd-b34d-6b43536c9dba', '{"en": "The wrists", "bn": "কব্জি পর্যন্ত"}', false, 1), ('dde853d2-a30f-5767-8ef3-d98a00ab4a7c', '2b37ca10-9c26-57cd-b34d-6b43536c9dba', '{"en": "The shoulders", "bn": "কাঁধ পর্যন্ত"}', false, 2), ('51711e43-c132-56e1-a818-ed9d43ff5266', '2b37ca10-9c26-57cd-b34d-6b43536c9dba', '{"en": "The fingertips only", "bn": "শুধু আঙুলের ডগা"}', false, 3), ('9b034ae1-a7ba-5c3e-ad23-ea470449bf4c', '2b37ca10-9c26-57cd-b34d-6b43536c9dba', '{"en": "The elbows, with them", "bn": "কনুইসহ"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('33c0b07a-7a1a-504d-8216-d5b44eb1a223', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "Whoever does wudu well and then says the shahadah, which gates are opened for him?", "bn": "যে সুন্দরভাবে অজু করে শাহাদাত পড়ে, তার জন্য কোন দরজাগুলো খুলে দেওয়া হয়?"}', '{"en": "\"…the eight gates of Paradise are opened for him; he may enter by whichever he wishes.\"", "bn": "\"…তার জন্য জান্নাতের আটটি দরজা খুলে দেওয়া হয়; যেটি দিয়ে ইচ্ছা প্রবেশ করবে।\""}', 'Sahih Muslim 234', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7d40ecae-6949-5204-85d6-3f1859f55f0f', '33c0b07a-7a1a-504d-8216-d5b44eb1a223', '{"en": "The eight gates of Paradise", "bn": "জান্নাতের আটটি দরজা"}', true, 1), ('40106919-0b74-5d99-834e-35f1201f37cd', '33c0b07a-7a1a-504d-8216-d5b44eb1a223', '{"en": "The gates of the masjid", "bn": "মসজিদের দরজা"}', false, 2), ('78083d43-db9a-52d8-985d-4a702441f688', '33c0b07a-7a1a-504d-8216-d5b44eb1a223', '{"en": "The seven heavens", "bn": "সাত আসমান"}', false, 3), ('3384a39c-6b4e-5365-8070-c8bc6df568a9', '33c0b07a-7a1a-504d-8216-d5b44eb1a223', '{"en": "The gates of knowledge", "bn": "জ্ঞানের দরজা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4f052ae0-7d55-555c-96eb-2bfcaa5b23d1', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "Which of these makes ghusl (a full bath) obligatory?", "bn": "নিচের কোনটির কারণে গোসল ফরজ হয়?"}', '{"en": "\"If you are in a state of janabah, then purify yourselves.\"", "bn": "\"যদি তোমরা জানাবাত অবস্থায় থাকো, তবে ভালোভাবে পবিত্র হও।\""}', 'Quran 5:6', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('5f062ebc-a931-5672-be93-96ea52ac41da', '4f052ae0-7d55-555c-96eb-2bfcaa5b23d1', '{"en": "Eating meat", "bn": "গোশত খাওয়া"}', false, 1), ('76453d84-4258-53ee-a3c7-fbf4c7720ab1', '4f052ae0-7d55-555c-96eb-2bfcaa5b23d1', '{"en": "Janabah (major impurity)", "bn": "জানাবাত (বড় নাপাকি)"}', true, 2), ('e47d7849-8b12-5958-8233-7407650c6723', '4f052ae0-7d55-555c-96eb-2bfcaa5b23d1', '{"en": "Cutting nails", "bn": "নখ কাটা"}', false, 3), ('11bd2a73-4ae7-5fb5-b9c9-ca6973107ea8', '4f052ae0-7d55-555c-96eb-2bfcaa5b23d1', '{"en": "A short nap sitting", "bn": "বসে একটু তন্দ্রা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6e4ad224-a7b0-5e16-b293-1855b3456ee3', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "In tayammum, after striking clean earth, what is wiped?", "bn": "তায়াম্মুমে পবিত্র মাটিতে হাত মেরে কী মাসেহ করা হয়?"}', '{"en": "\"…then seek clean earth and wipe your faces and hands with it.\"", "bn": "\"…তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো এবং তা দিয়ে মুখমণ্ডল ও হাত মাসেহ করো।\""}', 'Quran 5:6; Quran 4:43', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('681f0a9f-97dc-5507-a0fd-9bad0c86b228', '6e4ad224-a7b0-5e16-b293-1855b3456ee3', '{"en": "The head and feet", "bn": "মাথা ও পা"}', false, 1), ('df6a40aa-16d7-50a6-a1c5-8b1a05a4ee9b', '6e4ad224-a7b0-5e16-b293-1855b3456ee3', '{"en": "The whole body", "bn": "সারা শরীর"}', false, 2), ('002737ef-98f3-5838-8e07-1f79ee531640', '6e4ad224-a7b0-5e16-b293-1855b3456ee3', '{"en": "The face and hands", "bn": "মুখমণ্ডল ও হাত"}', true, 3), ('6a93978b-5997-543a-bf6f-7e60fc4c58cf', '6e4ad224-a7b0-5e16-b293-1855b3456ee3', '{"en": "The feet only", "bn": "শুধু পা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('44394293-7748-5bd8-b49a-87a09ee08864', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "In ‘Ali’s hadith in Sahih Muslim, for how long may a resident wipe over leather socks (khuff)?", "bn": "সহিহ মুসলিমে আলী (রা.)-এর হাদিস অনুযায়ী মুকিম ব্যক্তি চামড়ার মোজায় কতদিন মাসেহ করতে পারেন?"}', '{"en": "He ﷺ set three days and nights for the traveller and a day and a night for the resident.", "bn": "নবী ﷺ মুসাফিরের জন্য তিন দিন তিন রাত এবং মুকিমের জন্য এক দিন এক রাত নির্ধারণ করেছেন।"}', 'Sahih Muslim 276', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('86c97b21-de53-54d7-b15e-d6a4afe1430b', '44394293-7748-5bd8-b49a-87a09ee08864', '{"en": "One day and one night", "bn": "এক দিন এক রাত"}', true, 1), ('70a1a5d1-1534-5339-9987-37ac26bd5a07', '44394293-7748-5bd8-b49a-87a09ee08864', '{"en": "Three days and nights", "bn": "তিন দিন তিন রাত"}', false, 2), ('3516423a-44a9-5feb-bd26-32df0e2fe7bc', '44394293-7748-5bd8-b49a-87a09ee08864', '{"en": "One week", "bn": "এক সপ্তাহ"}', false, 3), ('cb4921e6-3657-53ca-988b-82da9abeb434', '44394293-7748-5bd8-b49a-87a09ee08864', '{"en": "Only one prayer", "bn": "শুধু এক ওয়াক্ত"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('28d3ba0d-1882-5e01-9ad9-d647eedb43a4', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "The Prophet ﷺ washed each limb in wudu at most how many times?", "bn": "নবী ﷺ অজুতে প্রতিটি অঙ্গ সর্বোচ্চ কতবার ধুতেন?"}', '{"en": "‘Uthman (RA) showed his wudu washing each limb three times; going beyond three is discouraged.", "bn": "উসমান (রা.) নবীজির অজু দেখাতে প্রতিটি অঙ্গ তিনবার ধুয়েছেন; তিনবারের বেশি ধোয়া অপছন্দনীয়।"}', 'Sahih al-Bukhari 159; Sunan Abi Dawud 135', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f684bffc-7d57-5ab3-b55b-a2d03556adbb', '28d3ba0d-1882-5e01-9ad9-d647eedb43a4', '{"en": "Seven", "bn": "সাতবার"}', false, 1), ('936a36ec-0e8f-54fe-8cb2-4f7ae6afb85a', '28d3ba0d-1882-5e01-9ad9-d647eedb43a4', '{"en": "Five", "bn": "পাঁচবার"}', false, 2), ('67536882-433b-56c5-b22f-6cae9f4496e6', '28d3ba0d-1882-5e01-9ad9-d647eedb43a4', '{"en": "Ten", "bn": "দশবার"}', false, 3), ('644ff5bb-63b2-50e2-a134-a69390fb1194', '28d3ba0d-1882-5e01-9ad9-d647eedb43a4', '{"en": "Three", "bn": "তিনবার"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8fd0d9bd-46eb-5435-8685-4e831c41f1e3', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "About how much water did the Prophet ﷺ use for wudu?", "bn": "নবী ﷺ অজুতে আনুমানিক কতটুকু পানি ব্যবহার করতেন?"}', '{"en": "Anas (RA): he did wudu with a mudd and ghusl with a sa‘ up to five mudds — a lesson not to waste water.", "bn": "আনাস (রা.): নবী ﷺ এক মুদ পানিতে অজু এবং এক সা থেকে পাঁচ মুদ পানিতে গোসল করতেন — পানি অপচয় না করার শিক্ষা।"}', 'Sahih al-Bukhari 201', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('5921d5c7-a60b-5112-9cf8-1ad095755c6f', '8fd0d9bd-46eb-5435-8685-4e831c41f1e3', '{"en": "A full bucket", "bn": "এক বালতি"}', false, 1), ('2cbf8ca1-c604-50d6-b866-8a4f45883539', '8fd0d9bd-46eb-5435-8685-4e831c41f1e3', '{"en": "One mudd (about two handfuls)", "bn": "এক মুদ (প্রায় দুই অঞ্জলি)"}', true, 2), ('c5a9a600-c280-5d15-831d-6039f24ee13f', '8fd0d9bd-46eb-5435-8685-4e831c41f1e3', '{"en": "Ten litres", "bn": "দশ লিটার"}', false, 3), ('c8c06618-572b-5b5d-b848-00ade7154486', '8fd0d9bd-46eb-5435-8685-4e831c41f1e3', '{"en": "As much as he liked", "bn": "যত খুশি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0c78dabb-9da2-5bf8-b8b4-64f772ddaeb5', 'b582c017-2637-5082-bee4-cd65f9ae4d38', '{"en": "\"Purity is half of…\"?", "bn": "\"পবিত্রতা … অর্ধেক।\" শূন্যস্থানে কী?"}', '{"en": "\"Purity is half of faith (at-tuhuru shatrul-iman).\"", "bn": "\"পবিত্রতা ঈমানের অর্ধেক।\""}', 'Sahih Muslim 223', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('71c94c9b-d08a-5789-bab9-61d95c79456c', '0c78dabb-9da2-5bf8-b8b4-64f772ddaeb5', '{"en": "Faith (iman)", "bn": "ঈমানের"}', true, 1), ('d304aa96-ea88-51b0-a6ab-64acdf24e6fe', '0c78dabb-9da2-5bf8-b8b4-64f772ddaeb5', '{"en": "Wealth", "bn": "সম্পদের"}', false, 2), ('0a97d7a9-2112-5175-9db8-9633c40eba35', '0c78dabb-9da2-5bf8-b8b4-64f772ddaeb5', '{"en": "Health", "bn": "স্বাস্থ্যের"}', false, 3), ('0a6a0bf6-5386-5935-8873-d04b72e7aa49', '0c78dabb-9da2-5bf8-b8b4-64f772ddaeb5', '{"en": "The day", "bn": "দিনের"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "Fasting: rules & rewards", "bn": "রোজা: নিয়ম ও ফজিলত"}', 'ramadan', 'medium', NULL, 10, 'in_review', 104) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b2c0c182-4070-5984-9dd7-fe511e8500e0', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "What did the Prophet ﷺ say about suhur (sehri)?", "bn": "সেহরি সম্পর্কে নবী ﷺ কী বলেছেন?"}', '{"en": "\"Eat suhur, for in suhur there is blessing.\"", "bn": "\"তোমরা সেহরি খাও, কারণ সেহরিতে বরকত আছে।\""}', 'Sahih al-Bukhari 1923', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('501aadbc-9de0-569c-85fe-c0a52eb6f48a', 'b2c0c182-4070-5984-9dd7-fe511e8500e0', '{"en": "There is blessing (barakah) in it", "bn": "এতে বরকত আছে"}', true, 1), ('9788d55e-1dc0-5404-bf7e-8d2b27f8da94', 'b2c0c182-4070-5984-9dd7-fe511e8500e0', '{"en": "It is not needed", "bn": "এর প্রয়োজন নেই"}', false, 2), ('ed81e6b8-43aa-5dbb-b9a1-cccd131436ec', 'b2c0c182-4070-5984-9dd7-fe511e8500e0', '{"en": "It should be eaten at midnight", "bn": "মধ্যরাতে খেতে হবে"}', false, 3), ('fff95279-29d7-54dd-b01a-548c910cc494', 'b2c0c182-4070-5984-9dd7-fe511e8500e0', '{"en": "Only the sick eat it", "bn": "শুধু অসুস্থরা খাবে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5a710418-a342-5bbc-a665-83d6b5622acb', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "What does a woman do about fasting during her menses in Ramadan?", "bn": "রমজানে ঋতুস্রাবের সময় নারী রোজার ব্যাপারে কী করবেন?"}', '{"en": "‘A’ishah (RA): \"We were ordered to make up the fasts, but not the prayers.\"", "bn": "আয়েশা (রা.): \"আমাদের রোজা কাজা করার নির্দেশ দেওয়া হতো, নামাজ নয়।\""}', 'Sahih Muslim 335', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ce2cc448-d27d-559c-947d-4eff4f26c517', '5a710418-a342-5bbc-a665-83d6b5622acb', '{"en": "Fasts anyway", "bn": "তবুও রোজা রাখবেন"}', false, 1), ('6e80e5fb-d38a-5216-bf56-d2a7527e0648', '5a710418-a342-5bbc-a665-83d6b5622acb', '{"en": "Pays money and never makes it up", "bn": "টাকা দেবেন, কাজা লাগবে না"}', false, 2), ('4e1be6b0-54a6-5977-a09c-6a4f606810b0', '5a710418-a342-5bbc-a665-83d6b5622acb', '{"en": "Does not fast, and makes up the days later", "bn": "রোজা রাখবেন না, পরে কাজা করবেন"}', true, 3), ('409fd61e-6290-5113-93c9-a58f5b360862', '5a710418-a342-5bbc-a665-83d6b5622acb', '{"en": "Fasts half days", "bn": "অর্ধেক দিন রোজা রাখবেন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ddc2007a-456a-56a8-ad7b-8b527da136f3', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "\"Eat and drink until the white thread of dawn becomes distinct from the black thread\" is in which ayah?", "bn": "\"…যতক্ষণ না ভোরের সাদা রেখা কালো রেখা থেকে স্পষ্ট হয়, ততক্ষণ খাও ও পান করো\" — কোন আয়াতে?"}', '{"en": "Al-Baqarah 2:187 sets the fasting day: from true dawn until night.", "bn": "আল-বাকারা ২:১৮৭ রোজার সময় নির্ধারণ করে: সুবহে সাদিক থেকে রাত পর্যন্ত।"}', 'Quran 2:187', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('18a5cdce-d4f8-5b62-b9a9-44cb0b2d994d', 'ddc2007a-456a-56a8-ad7b-8b527da136f3', '{"en": "2:183", "bn": "২:১৮৩"}', false, 1), ('e62a8feb-d725-5f24-a63c-4048109af0fb', 'ddc2007a-456a-56a8-ad7b-8b527da136f3', '{"en": "2:187", "bn": "২:১৮৭"}', true, 2), ('0faa148c-50d9-554c-b470-0dd3e6235ccc', 'ddc2007a-456a-56a8-ad7b-8b527da136f3', '{"en": "97:1", "bn": "৯৭:১"}', false, 3), ('e9ae889f-fd1c-5fc3-b56b-c61bcaaba0dd', 'ddc2007a-456a-56a8-ad7b-8b527da136f3', '{"en": "3:97", "bn": "৩:৯৭"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a41e67df-e086-5e33-b5c9-db08307f00be', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "If someone insults or fights a fasting person, the fasting person should say…?", "bn": "কেউ রোজাদারকে গালি দিলে বা ঝগড়া করতে এলে রোজাদার কী বলবে?"}', '{"en": "\"…if someone fights or insults him, let him say: I am fasting, I am fasting.\"", "bn": "\"…কেউ তার সঙ্গে ঝগড়া বা গালাগালি করলে সে যেন বলে: আমি রোজাদার, আমি রোজাদার।\""}', 'Sahih al-Bukhari 1904', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1a4fd0eb-1f51-52bf-b219-16787184c600', 'a41e67df-e086-5e33-b5c9-db08307f00be', '{"en": "Nothing ever", "bn": "কখনো কিছু বলবে না"}', false, 1), ('38dda9e2-cf82-5440-8f5a-befb255d13a4', 'a41e67df-e086-5e33-b5c9-db08307f00be', '{"en": "Insult him back", "bn": "পাল্টা গালি দেবে"}', false, 2), ('746fe6b9-56fa-5f1e-8761-2f4579e30dc5', 'a41e67df-e086-5e33-b5c9-db08307f00be', '{"en": "\"I break my fast\"", "bn": "\"আমি রোজা ভেঙে দিলাম\""}', false, 3), ('497a62c1-2a27-5c97-9590-d0cff6de83e4', 'a41e67df-e086-5e33-b5c9-db08307f00be', '{"en": "\"I am fasting\"", "bn": "\"আমি রোজাদার\""}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('880ca172-ea5d-51e4-b48d-ca88f8304781', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "To Allah, the smell of a fasting person’s mouth is better than…?", "bn": "আল্লাহর কাছে রোজাদারের মুখের গন্ধ কিসের চেয়েও উত্তম?"}', '{"en": "\"The smell of the fasting person’s mouth is better to Allah than the scent of musk.\"", "bn": "\"রোজাদারের মুখের গন্ধ আল্লাহর কাছে মেশকের সুগন্ধির চেয়েও উত্তম।\""}', 'Sahih al-Bukhari 1894', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e5e9d440-3efe-53f2-8c26-dbc0ced0855c', '880ca172-ea5d-51e4-b48d-ca88f8304781', '{"en": "Rose water", "bn": "গোলাপজল"}', false, 1), ('d6e77b61-dd37-5dfc-80cc-885e655f7775', '880ca172-ea5d-51e4-b48d-ca88f8304781', '{"en": "Fresh bread", "bn": "তাজা রুটি"}', false, 2), ('cc2064d7-b037-5df9-b877-b03c4d62eeb6', '880ca172-ea5d-51e4-b48d-ca88f8304781', '{"en": "The scent of musk", "bn": "মেশকের সুগন্ধি"}', true, 3), ('a6da8394-9128-5d8b-a6fd-9ff00e1179e0', '880ca172-ea5d-51e4-b48d-ca88f8304781', '{"en": "Rain", "bn": "বৃষ্টির ঘ্রাণ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('92eb2848-eb5d-5401-b2df-514c708793f8', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "Whoever gives iftar to a fasting person receives…?", "bn": "যে রোজাদারকে ইফতার করায় সে কী পায়?"}', '{"en": "\"Whoever gives iftar to a fasting person has a reward like his, without anything being reduced from the fasting person’s reward.\"", "bn": "\"যে কোনো রোজাদারকে ইফতার করায়, সে রোজাদারের সমান সওয়াব পায়, অথচ রোজাদারের সওয়াব একটুও কমে না।\""}', 'Jami‘ at-Tirmidhi 807', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b06d81c8-03e8-5c6b-a557-6a925267ec97', '92eb2848-eb5d-5401-b2df-514c708793f8', '{"en": "A reward like his, without his being reduced", "bn": "রোজাদারের সমান সওয়াব, রোজাদারের সওয়াব কমে না"}', true, 1), ('83ae9860-c936-5e4b-8210-24bfcdadbaf2', '92eb2848-eb5d-5401-b2df-514c708793f8', '{"en": "Nothing extra", "bn": "অতিরিক্ত কিছু না"}', false, 2), ('6b1f87fe-c4cc-5ba7-a430-8e2793eb71c5', '92eb2848-eb5d-5401-b2df-514c708793f8', '{"en": "Half of the fasting person’s reward", "bn": "রোজাদারের অর্ধেক সওয়াব"}', false, 3), ('d7fa0188-1ba5-59f8-bcbe-0f8a46505e36', '92eb2848-eb5d-5401-b2df-514c708793f8', '{"en": "Only thanks", "bn": "শুধু ধন্যবাদ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('885572d5-5d9e-5601-8dd5-c3fe61e75fe0', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "When Ramadan comes, the gates of … are opened.", "bn": "রমজান এলে … দরজাগুলো খুলে দেওয়া হয়।"}', '{"en": "\"When Ramadan begins, the gates of Paradise are opened, the gates of Hell are closed and the devils are chained.\"", "bn": "\"রমজান এলে জান্নাতের দরজা খুলে দেওয়া হয়, জাহান্নামের দরজা বন্ধ করা হয় এবং শয়তানদের শিকলবন্দি করা হয়।\""}', 'Sahih al-Bukhari 1899', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f2ab1a84-9d5e-5345-b493-04901e3d3757', '885572d5-5d9e-5601-8dd5-c3fe61e75fe0', '{"en": "The cities", "bn": "শহরের"}', false, 1), ('eecf28fa-1bd8-587c-b03d-c372d674ae6d', '885572d5-5d9e-5601-8dd5-c3fe61e75fe0', '{"en": "Paradise", "bn": "জান্নাতের"}', true, 2), ('94443d24-7c5d-5793-b339-4d94006cf83c', '885572d5-5d9e-5601-8dd5-c3fe61e75fe0', '{"en": "The markets", "bn": "বাজারের"}', false, 3), ('6dc956c9-0f54-5a65-b710-c5d2e8ed69be', '885572d5-5d9e-5601-8dd5-c3fe61e75fe0', '{"en": "The seas", "bn": "সমুদ্রের"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3ed02f17-a4d2-5e9b-8428-62e1156abc5c', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "Which of these breaks the fast?", "bn": "নিচের কোনটি রোজা ভেঙে দেয়?"}', '{"en": "Fasting is holding back from food, drink and intimacy from dawn to sunset; eating forgetfully does not break it.", "bn": "রোজা মানে ভোর থেকে সূর্যাস্ত পর্যন্ত পানাহার ও স্ত্রী-সহবাস থেকে বিরত থাকা; ভুলে খেলে রোজা ভাঙে না।"}', 'Quran 2:187; Sahih al-Bukhari 1933', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f3173ebb-468c-5574-924c-7267d0478ad4', '3ed02f17-a4d2-5e9b-8428-62e1156abc5c', '{"en": "Eating by mistake, forgetting", "bn": "ভুলে খেয়ে ফেলা"}', false, 1), ('55e3ddea-f142-5638-b76f-d773488dc25d', '3ed02f17-a4d2-5e9b-8428-62e1156abc5c', '{"en": "Swallowing one’s own saliva", "bn": "নিজের থুথু গিলে ফেলা"}', false, 2), ('aa4944a9-9945-5326-9425-8e45e9165177', '3ed02f17-a4d2-5e9b-8428-62e1156abc5c', '{"en": "Smelling a flower", "bn": "ফুলের ঘ্রাণ নেওয়া"}', false, 3), ('44ce4928-9a36-5c38-8bc2-75dd4c72a73a', '3ed02f17-a4d2-5e9b-8428-62e1156abc5c', '{"en": "Eating or drinking on purpose", "bn": "ইচ্ছাকৃতভাবে খাওয়া বা পান করা"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b272a67e-cfb5-5de8-8f74-7bb970a33793', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "The expiation for intercourse during a Ramadan day, for one who cannot free a slave, is to fast…?", "bn": "রমজানের দিনে স্ত্রী-সহবাসের কাফফারা, দাস মুক্ত করতে না পারলে, কত দিন রোজা?"}', '{"en": "He ﷺ said: free a slave; if not, fast two consecutive months; if not, feed sixty poor people.", "bn": "নবী ﷺ বললেন: দাস মুক্ত করো; না পারলে একটানা দুই মাস রোজা; তাও না পারলে ষাটজন মিসকিনকে খাওয়াও।"}', 'Sahih al-Bukhari 1936', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('648d1516-e2cd-54a1-9808-1787c423a8d3', 'b272a67e-cfb5-5de8-8f74-7bb970a33793', '{"en": "Ten days", "bn": "দশ দিন"}', false, 1), ('3ac25a42-5969-56a6-ac3f-48ca1b22af48', 'b272a67e-cfb5-5de8-8f74-7bb970a33793', '{"en": "Thirty days", "bn": "ত্রিশ দিন"}', false, 2), ('af4890ec-8c60-5db8-8e91-19b0eba1b7c8', 'b272a67e-cfb5-5de8-8f74-7bb970a33793', '{"en": "Two consecutive months", "bn": "একটানা দুই মাস"}', true, 3), ('e7e2e246-90ff-559d-8236-8d2b4ee60e84', 'b272a67e-cfb5-5de8-8f74-7bb970a33793', '{"en": "One year", "bn": "এক বছর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7293b705-b170-5e4b-859c-63f9e5711632', 'ce5a2a1e-91d5-531d-8800-31966e564ac8', '{"en": "In which month was the Prophet ﷺ the most generous?", "bn": "নবী ﷺ কোন মাসে সবচেয়ে বেশি দানশীল হতেন?"}', '{"en": "\"He was most generous in Ramadan, when Jibril met him… more generous than the blowing wind.\"", "bn": "\"তিনি রমজানে সবচেয়ে বেশি দানশীল হতেন, যখন জিবরাইল তাঁর সঙ্গে সাক্ষাৎ করতেন… প্রবাহিত বাতাসের চেয়েও বেশি।\""}', 'Sahih al-Bukhari 6', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a2730d07-9458-5fbb-a255-f32e2da680b3', '7293b705-b170-5e4b-859c-63f9e5711632', '{"en": "Ramadan", "bn": "রমজান"}', true, 1), ('2af18b32-03c8-5c9f-9166-eda58085dd7b', '7293b705-b170-5e4b-859c-63f9e5711632', '{"en": "Muharram", "bn": "মহররম"}', false, 2), ('d6e14bb8-963a-5b09-8ac4-61cdc7bb0332', '7293b705-b170-5e4b-859c-63f9e5711632', '{"en": "Rajab", "bn": "রজব"}', false, 3), ('4f8bcfa4-2d45-5621-a9b6-3bfacc05e21d', '7293b705-b170-5e4b-859c-63f9e5711632', '{"en": "Shawwal", "bn": "শাওয়াল"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('13967fdc-b601-5365-a732-15c905875136', '{"en": "Sunnah & voluntary fasts", "bn": "সুন্নাত ও নফল রোজা"}', 'ramadan', 'medium', NULL, 10, 'in_review', 105) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('15aa9d2a-b283-5476-9f9b-ca48b708a817', '13967fdc-b601-5365-a732-15c905875136', '{"en": "Fasting the Day of Arafah (for those not on Hajj) expiates the sins of…?", "bn": "আরাফার দিনের রোজা (হাজি নন এমন ব্যক্তির জন্য) কোন সময়ের গুনাহ মাফের আশা দেয়?"}', '{"en": "\"I hope from Allah that it expiates the year before it and the year after it.\"", "bn": "\"আমি আল্লাহর কাছে আশা করি, এটি আগের এক বছর ও পরের এক বছরের গুনাহের কাফফারা হবে।\""}', 'Sahih Muslim 1162', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1bcb8979-984d-5fba-aa5a-c9c2befa6b05', '15aa9d2a-b283-5476-9f9b-ca48b708a817', '{"en": "Only that day", "bn": "শুধু সেই দিনের"}', false, 1), ('a2bc12b6-6e79-5d76-acc7-40a734ca9fa7', '15aa9d2a-b283-5476-9f9b-ca48b708a817', '{"en": "The previous year and the coming year", "bn": "আগের এক বছর ও পরের এক বছরের"}', true, 2), ('17285b17-5a68-5c58-8c6e-4a42fe15f6c5', '15aa9d2a-b283-5476-9f9b-ca48b708a817', '{"en": "Ten years", "bn": "দশ বছরের"}', false, 3), ('e098b78b-2e9b-5479-b272-dd36a9557065', '15aa9d2a-b283-5476-9f9b-ca48b708a817', '{"en": "The past month", "bn": "গত মাসের"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fdcd8421-a401-5532-84c2-5ba85fc47226', '13967fdc-b601-5365-a732-15c905875136', '{"en": "Fasting the day of Ashura expiates the sins of…?", "bn": "আশুরার রোজা কোন সময়ের গুনাহ মাফের আশা দেয়?"}', '{"en": "\"…I hope from Allah that it expiates the year before it.\"", "bn": "\"…আমি আল্লাহর কাছে আশা করি, এটি আগের এক বছরের গুনাহের কাফফারা হবে।\""}', 'Sahih Muslim 1162', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8d90683b-6f2d-5929-8c8b-993d4ec33dfe', 'fdcd8421-a401-5532-84c2-5ba85fc47226', '{"en": "The previous year", "bn": "আগের এক বছরের"}', true, 1), ('2cf1fce5-d685-538a-ba9b-0a16495c4bd7', 'fdcd8421-a401-5532-84c2-5ba85fc47226', '{"en": "The coming year", "bn": "পরের এক বছরের"}', false, 2), ('43575da2-a427-5f93-bf23-e2de10d5caec', 'fdcd8421-a401-5532-84c2-5ba85fc47226', '{"en": "A whole lifetime", "bn": "সারা জীবনের"}', false, 3), ('54be4e66-4a47-5bdb-b946-7c0ccae62811', 'fdcd8421-a401-5532-84c2-5ba85fc47226', '{"en": "One week", "bn": "এক সপ্তাহের"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1ed35718-dae1-50b7-a31e-275012480805', '13967fdc-b601-5365-a732-15c905875136', '{"en": "The \"white days\" (Ayyam al-Bid) for fasting are which dates of each Hijri month?", "bn": "\"আইয়ামে বীজ\"-এর রোজা প্রতি হিজরি মাসের কোন তারিখে?"}', '{"en": "He ﷺ told Abu Dharr (RA): if you fast three days of a month, fast the 13th, 14th and 15th.", "bn": "নবী ﷺ আবু যর (রা.)-কে বললেন: মাসে তিন দিন রোজা রাখলে ১৩, ১৪ ও ১৫ তারিখে রাখো।"}', 'Jami‘ at-Tirmidhi 761; Sunan an-Nasa’i 2424', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('2bab7811-4ee6-55c5-b1d7-fe4d98802426', '1ed35718-dae1-50b7-a31e-275012480805', '{"en": "1st, 2nd and 3rd", "bn": "১, ২ ও ৩"}', false, 1), ('f138aa8a-7309-558a-b2ab-5d57485f2f2d', '1ed35718-dae1-50b7-a31e-275012480805', '{"en": "10th, 20th and 30th", "bn": "১০, ২০ ও ৩০"}', false, 2), ('412ae5f8-900a-5d89-8168-3a3953cdce33', '1ed35718-dae1-50b7-a31e-275012480805', '{"en": "13th, 14th and 15th", "bn": "১৩, ১৪ ও ১৫"}', true, 3), ('ddbeaba4-bbda-5dd1-967a-a97087bf8a02', '1ed35718-dae1-50b7-a31e-275012480805', '{"en": "27th, 28th and 29th", "bn": "২৭, ২৮ ও ২৯"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('accea7a0-1666-5e72-be8f-39ca6771f0ca', '13967fdc-b601-5365-a732-15c905875136', '{"en": "The Prophet ﷺ called the fast of which prophet the most beloved fast to Allah?", "bn": "নবী ﷺ কোন নবীর রোজাকে আল্লাহর কাছে সবচেয়ে প্রিয় বলেছেন?"}', '{"en": "\"The most beloved fast to Allah is the fast of Dawud: he fasted one day and ate the next.\"", "bn": "\"আল্লাহর কাছে সবচেয়ে প্রিয় রোজা দাউদ (আ.)-এর রোজা: তিনি একদিন রোজা রাখতেন, একদিন রাখতেন না।\""}', 'Sahih al-Bukhari 3420', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('6f912d1b-b1e6-5d42-9db0-5276e463d031', 'accea7a0-1666-5e72-be8f-39ca6771f0ca', '{"en": "Musa", "bn": "মুসা (আ.)"}', false, 1), ('2cdee35b-0d66-540a-bead-b31d3b1c7b12', 'accea7a0-1666-5e72-be8f-39ca6771f0ca', '{"en": "Ibrahim", "bn": "ইবরাহিম (আ.)"}', false, 2), ('776c6d76-6061-560b-a472-a9b390e0973c', 'accea7a0-1666-5e72-be8f-39ca6771f0ca', '{"en": "Isa", "bn": "ঈসা (আ.)"}', false, 3), ('95fc3cc4-9f98-5b94-bbd7-f8f515c7de30', 'accea7a0-1666-5e72-be8f-39ca6771f0ca', '{"en": "Dawud", "bn": "দাউদ (আ.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('44c5e897-f843-512f-aae2-1979f218d99f', '13967fdc-b601-5365-a732-15c905875136', '{"en": "Apart from Ramadan, in which month did the Prophet ﷺ fast the most?", "bn": "রমজান ছাড়া নবী ﷺ কোন মাসে সবচেয়ে বেশি রোজা রাখতেন?"}', '{"en": "‘A’ishah (RA): \"I never saw him fast more in any month than in Sha‘ban.\"", "bn": "আয়েশা (রা.): \"শাবানের চেয়ে বেশি রোজা আমি তাঁকে অন্য কোনো মাসে রাখতে দেখিনি।\""}', 'Sahih al-Bukhari 1969', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('803db354-4ce4-50b3-85af-00595eadb5e1', '44c5e897-f843-512f-aae2-1979f218d99f', '{"en": "Sha‘ban", "bn": "শাবান"}', true, 1), ('720c8922-ed8f-5a1d-8c24-085b0b6959df', '44c5e897-f843-512f-aae2-1979f218d99f', '{"en": "Rajab", "bn": "রজব"}', false, 2), ('5bb0f015-c2c4-561a-b841-29e96a04c3bb', '44c5e897-f843-512f-aae2-1979f218d99f', '{"en": "Shawwal", "bn": "শাওয়াল"}', false, 3), ('50eb4b5b-8a60-502c-8a1a-58c5d3a9473c', '44c5e897-f843-512f-aae2-1979f218d99f', '{"en": "Safar", "bn": "সফর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0365b672-55f8-5f8b-8eb2-d8f2dcb30118', '13967fdc-b601-5365-a732-15c905875136', '{"en": "\"The best fasting after Ramadan is in Allah’s month…\" — which month?", "bn": "\"রমজানের পর সর্বোত্তম রোজা আল্লাহর মাস…-এর রোজা।\" কোন মাস?"}', '{"en": "\"The best fasting after Ramadan is in Allah’s month, al-Muharram.\"", "bn": "\"রমজানের পর সর্বোত্তম রোজা আল্লাহর মাস মহররমের রোজা।\""}', 'Sahih Muslim 1163', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('126ba6cf-8182-5478-8534-d25a05ef7b41', '0365b672-55f8-5f8b-8eb2-d8f2dcb30118', '{"en": "Dhul Hijjah", "bn": "জিলহজ"}', false, 1), ('c7c72dad-1a88-59df-972c-52db228a1d16', '0365b672-55f8-5f8b-8eb2-d8f2dcb30118', '{"en": "Muharram", "bn": "মহররম"}', true, 2), ('b09eaadc-68aa-5ee3-940d-545a4e116960', '0365b672-55f8-5f8b-8eb2-d8f2dcb30118', '{"en": "Sha‘ban", "bn": "শাবান"}', false, 3), ('26b49377-dee9-510f-a7ef-967401f79631', '0365b672-55f8-5f8b-8eb2-d8f2dcb30118', '{"en": "Rabi‘ al-Awwal", "bn": "রবিউল আউয়াল"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4889962b-a7b8-507c-9f31-816cf28c35dc', '13967fdc-b601-5365-a732-15c905875136', '{"en": "Along with Ashura, the Prophet ﷺ intended to fast which day as well?", "bn": "আশুরার সঙ্গে নবী ﷺ আর কোন দিন রোজা রাখার ইচ্ছা করেছিলেন?"}', '{"en": "\"If I live until next year, I will surely fast the ninth (as well).\"", "bn": "\"আগামী বছর বেঁচে থাকলে অবশ্যই নবম তারিখেও রোজা রাখব।\""}', 'Sahih Muslim 1134', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3f4ff8b1-5387-5181-a386-49f5c1506e14', '4889962b-a7b8-507c-9f31-816cf28c35dc', '{"en": "The 1st of Muharram", "bn": "মহররমের ১ তারিখ"}', false, 1), ('19f319b4-7f17-508a-96f4-813db7cfc9be', '4889962b-a7b8-507c-9f31-816cf28c35dc', '{"en": "The 11th of Safar", "bn": "সফরের ১১ তারিখ"}', false, 2), ('a3129cf0-ea35-5a68-9be2-8455f558aa4d', '4889962b-a7b8-507c-9f31-816cf28c35dc', '{"en": "The 9th of Muharram", "bn": "মহররমের ৯ তারিখ"}', true, 3), ('8f317cf7-b9b2-56d9-9413-332f02bc8246', '4889962b-a7b8-507c-9f31-816cf28c35dc', '{"en": "The 15th of Sha‘ban", "bn": "শাবানের ১৫ তারিখ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6bbfe6d8-d060-5e3f-81a0-ea103e48b4d4', '13967fdc-b601-5365-a732-15c905875136', '{"en": "Fasting Ramadan and then six days of Shawwal is like fasting…?", "bn": "রমজানের রোজার পর শাওয়ালের ছয় রোজা রাখা কিসের মতো?"}', '{"en": "\"Whoever fasts Ramadan and follows it with six of Shawwal, it is like fasting perpetually\" — each good deed counts ten, so it is like the whole year.", "bn": "\"যে রমজানের রোজা রাখে এবং এরপর শাওয়ালের ছয়টি রোজা রাখে, সে যেন সারা বছর রোজা রাখল\" — প্রতিটি নেকি দশ গুণ, তাই পুরো বছরের সমান।"}', 'Sahih Muslim 1164; Sunan Ibn Majah 1715', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1b69dbd0-69fd-56b8-b1ee-c390ead492c3', '6bbfe6d8-d060-5e3f-81a0-ea103e48b4d4', '{"en": "One month", "bn": "এক মাস"}', false, 1), ('34256f2b-c97e-5cee-9b95-90d681b29dcc', '6bbfe6d8-d060-5e3f-81a0-ea103e48b4d4', '{"en": "Ten days", "bn": "দশ দিন"}', false, 2), ('f5ded5ed-1cb4-53fb-90e9-5b391d40532c', '6bbfe6d8-d060-5e3f-81a0-ea103e48b4d4', '{"en": "Half a year", "bn": "অর্ধেক বছর"}', false, 3), ('3d358733-1e47-5079-ac39-9297f2f8a855', '6bbfe6d8-d060-5e3f-81a0-ea103e48b4d4', '{"en": "The whole year", "bn": "সারা বছর"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f200aed3-2dcf-5f64-8d25-8987ff86ed21', '13967fdc-b601-5365-a732-15c905875136', '{"en": "A wife should not keep a voluntary fast while her husband is present except…?", "bn": "স্বামী উপস্থিত থাকলে স্ত্রী কীভাবে নফল রোজা রাখবেন?"}', '{"en": "\"A woman should not fast (voluntarily) when her husband is present except with his permission.\"", "bn": "\"স্বামী উপস্থিত থাকলে তার অনুমতি ছাড়া স্ত্রী (নফল) রোজা রাখবে না।\""}', 'Sahih al-Bukhari 5192', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('90b23dbd-1c91-5225-9268-a15fcb8b3944', 'f200aed3-2dcf-5f64-8d25-8987ff86ed21', '{"en": "With his permission", "bn": "তাঁর অনুমতি নিয়ে"}', true, 1), ('9eb39f87-579c-5be0-a842-cc6a5ff24f82', 'f200aed3-2dcf-5f64-8d25-8987ff86ed21', '{"en": "Never", "bn": "কখনোই না"}', false, 2), ('81d2a70f-a9e0-5d7b-b983-e861c739cf80', 'f200aed3-2dcf-5f64-8d25-8987ff86ed21', '{"en": "Only on Fridays", "bn": "শুধু শুক্রবারে"}', false, 3), ('f7e0f547-d96a-5a8b-b5c3-389ddc95d461', 'f200aed3-2dcf-5f64-8d25-8987ff86ed21', '{"en": "Only in winter", "bn": "শুধু শীতকালে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('dae58e1e-77f2-52ce-920c-0802ec0c8664', '13967fdc-b601-5365-a732-15c905875136', '{"en": "Whoever fasts one day in Allah’s path, Allah keeps his face from the Fire by…?", "bn": "যে আল্লাহর পথে একদিন রোজা রাখে, আল্লাহ তার চেহারাকে জাহান্নাম থেকে কত দূরে রাখেন?"}', '{"en": "\"…Allah will keep his face away from the Fire by (a distance of) seventy years.\"", "bn": "\"…আল্লাহ তার চেহারাকে জাহান্নাম থেকে সত্তর বছরের দূরত্বে রাখবেন।\""}', 'Sahih al-Bukhari 2840', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0890203b-f9c6-55b6-ac3d-681d221fdd31', 'dae58e1e-77f2-52ce-920c-0802ec0c8664', '{"en": "One day’s distance", "bn": "এক দিনের পথ"}', false, 1), ('9628fb68-7eeb-5415-94a6-c725747144cb', 'dae58e1e-77f2-52ce-920c-0802ec0c8664', '{"en": "Seventy years’ distance", "bn": "সত্তর বছরের পথ"}', true, 2), ('46f78492-957f-5ae9-89af-16ef0d4b96f8', 'dae58e1e-77f2-52ce-920c-0802ec0c8664', '{"en": "One mile", "bn": "এক মাইল"}', false, 3), ('c1df434f-7c29-5e7f-935d-ca81038877fc', 'dae58e1e-77f2-52ce-920c-0802ec0c8664', '{"en": "Ten steps", "bn": "দশ কদম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('d99125a9-5113-506b-8454-165142a8a739', '{"en": "Zakat: on what, and how much", "bn": "যাকাত: কিসে ও কতটুকু"}', 'fiqh', 'medium', NULL, 10, 'in_review', 106) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8339a70a-a3b2-5031-9c1f-51cf398edffa', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "The zakat on crops watered by rain or springs is…?", "bn": "বৃষ্টি বা ঝরনার পানিতে উৎপন্ন ফসলের যাকাত কত?"}', '{"en": "\"On what is watered by the sky and springs, one tenth; on what is irrigated, half of a tenth.\"", "bn": "\"আকাশ ও ঝরনার পানিতে যা উৎপন্ন হয় তাতে এক-দশমাংশ; সেচ দিয়ে উৎপন্ন হলে এক-দশমাংশের অর্ধেক।\""}', 'Sahih al-Bukhari 1483', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e654dfec-2ae6-56ce-91f8-ff83337629a6', '8339a70a-a3b2-5031-9c1f-51cf398edffa', '{"en": "One tenth (10%)", "bn": "এক-দশমাংশ (১০%)"}', true, 1), ('1177806f-294e-5c4a-b95a-0099bb247773', '8339a70a-a3b2-5031-9c1f-51cf398edffa', '{"en": "2.5%", "bn": "২.৫%"}', false, 2), ('60573d76-a1ad-54e1-9124-584e401139b8', '8339a70a-a3b2-5031-9c1f-51cf398edffa', '{"en": "One fifth (20%)", "bn": "এক-পঞ্চমাংশ (২০%)"}', false, 3), ('0a2edfd6-4d9f-5cb6-bc0a-9725433a4620', '8339a70a-a3b2-5031-9c1f-51cf398edffa', '{"en": "Nothing", "bn": "কিছুই না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d87c7881-1284-5bc3-ac69-af058fe98cef', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "The zakat on crops watered by irrigation (with labour and cost) is…?", "bn": "সেচ দিয়ে (শ্রম ও খরচে) উৎপন্ন ফসলের যাকাত কত?"}', '{"en": "Irrigated crops pay half of a tenth, because of the effort of watering them.", "bn": "সেচের শ্রম ও খরচের কারণে সেচের ফসলে এক-দশমাংশের অর্ধেক।"}', 'Sahih al-Bukhari 1483', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3bc11777-c866-577e-9bd4-1f8f8072c26e', 'd87c7881-1284-5bc3-ac69-af058fe98cef', '{"en": "10%", "bn": "১০%"}', false, 1), ('cdc6a24b-511a-5f2f-8d0c-69db8291f805', 'd87c7881-1284-5bc3-ac69-af058fe98cef', '{"en": "2.5%", "bn": "২.৫%"}', false, 2), ('d11147af-cbb1-5a8c-a43a-6f80a3d3d362', 'd87c7881-1284-5bc3-ac69-af058fe98cef', '{"en": "5% (half of a tenth)", "bn": "৫% (এক-দশমাংশের অর্ধেক)"}', true, 3), ('cf3c956c-01dc-5234-9c13-f3558d301a2f', 'd87c7881-1284-5bc3-ac69-af058fe98cef', '{"en": "25%", "bn": "২৫%"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('53680070-df03-59b5-ab0c-8aea955fe61e', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "In ‘Ali’s hadith, the nisab of gold is…?", "bn": "আলী (রা.)-এর হাদিসে স্বর্ণের নিসাব কত?"}', '{"en": "\"Nothing is due on gold until you have twenty dinars…; on twenty dinars, half a dinar.\" (About 85–87.5 g today.)", "bn": "\"বিশ দিনার না হওয়া পর্যন্ত স্বর্ণে কিছু নেই…; বিশ দিনারে অর্ধ দিনার।\" (বর্তমানে প্রায় ৮৫–৮৭.৫ গ্রাম।)"}', 'Sunan Abi Dawud 1573', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e085028f-9920-57b0-84eb-3890de426695', '53680070-df03-59b5-ab0c-8aea955fe61e', '{"en": "5 dinars", "bn": "৫ দিনার"}', false, 1), ('68f8d551-307d-54f7-8fc9-c185b411ec38', '53680070-df03-59b5-ab0c-8aea955fe61e', '{"en": "100 dinars", "bn": "১০০ দিনার"}', false, 2), ('b0dba5f6-6bb7-5d0a-a7e5-c2dc0feb634e', '53680070-df03-59b5-ab0c-8aea955fe61e', '{"en": "200 dinars", "bn": "২০০ দিনার"}', false, 3), ('15f4ae09-562e-5775-9cea-f7f7e82ab140', '53680070-df03-59b5-ab0c-8aea955fe61e', '{"en": "20 dinars", "bn": "২০ দিনার"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('bf64edcb-88d8-5385-b39d-b637dc2b878f', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "The nisab of silver in the hadith is…?", "bn": "হাদিসে রুপার নিসাব কত?"}', '{"en": "\"There is no zakat on less than five awaq (200 dirhams) of silver.\" (About 595–612 g today.)", "bn": "\"পাঁচ উকিয়ার (২০০ দিরহাম) কম রুপায় যাকাত নেই।\" (বর্তমানে প্রায় ৫৯৫–৬১২ গ্রাম।)"}', 'Sahih al-Bukhari 1447; Sunan Abi Dawud 1573', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('750c1736-3640-51a2-8d63-388566418988', 'bf64edcb-88d8-5385-b39d-b637dc2b878f', '{"en": "200 dirhams (five awaq)", "bn": "২০০ দিরহাম (পাঁচ উকিয়া)"}', true, 1), ('09257635-a772-52af-8119-a0bbc0a8292d', 'bf64edcb-88d8-5385-b39d-b637dc2b878f', '{"en": "20 dirhams", "bn": "২০ দিরহাম"}', false, 2), ('91100f75-10b5-5aa4-badb-1366be48551e', 'bf64edcb-88d8-5385-b39d-b637dc2b878f', '{"en": "1,000 dirhams", "bn": "১,০০০ দিরহাম"}', false, 3), ('2942d734-e1df-55db-b587-4c2eef801449', 'bf64edcb-88d8-5385-b39d-b637dc2b878f', '{"en": "50 dirhams", "bn": "৫০ দিরহাম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6a746293-afe7-56b1-ada4-389087708caa', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "Among those who may receive zakat, \"ibn as-sabil\" means…?", "bn": "যাকাতের খাতের মধ্যে \"ইবনুস সাবিল\" অর্থ কী?"}', '{"en": "Ibn as-sabil, \"son of the road\", is a traveller cut off from his money.", "bn": "ইবনুস সাবিল বা \"পথের সন্তান\" হলেন এমন মুসাফির যিনি নিজের সম্পদ থেকে বিচ্ছিন্ন।"}', 'Quran 9:60', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('41804323-e884-5a75-ab2b-34b7fd4179ec', '6a746293-afe7-56b1-ada4-389087708caa', '{"en": "A new Muslim", "bn": "নতুন মুসলিম"}', false, 1), ('64f2be83-15a1-5a3f-87ae-f3fa5bbc7c32', '6a746293-afe7-56b1-ada4-389087708caa', '{"en": "A stranded traveller", "bn": "বিপদগ্রস্ত মুসাফির"}', true, 2), ('8c0323a3-f7c7-518c-a771-2b5fe4666795', '6a746293-afe7-56b1-ada4-389087708caa', '{"en": "A student", "bn": "ছাত্র"}', false, 3), ('d83ceb23-983f-50f7-9a15-066155fd5643', '6a746293-afe7-56b1-ada4-389087708caa', '{"en": "A zakat collector", "bn": "যাকাত আদায়কারী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('19244de3-23bb-5bea-b919-6feacfd65d69', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "\"Al-gharimin\" in the zakat ayah are…?", "bn": "যাকাতের আয়াতে \"আল-গারিমিন\" কারা?"}', '{"en": "Zakat may help those weighed down by debts they cannot pay.", "bn": "যে ঋণ শোধ করতে পারে না, এমন ঋণগ্রস্তকে যাকাত দেওয়া যায়।"}', 'Quran 9:60', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('74c45941-c6a2-5613-bf7e-65f29645f133', '19244de3-23bb-5bea-b919-6feacfd65d69', '{"en": "Orphans", "bn": "এতিমরা"}', false, 1), ('321a4df8-c32c-5fa8-9dc5-832265b80f00', '19244de3-23bb-5bea-b919-6feacfd65d69', '{"en": "Travellers", "bn": "মুসাফিররা"}', false, 2), ('fd94bdf7-eb15-56e7-9287-d60ea5143814', '19244de3-23bb-5bea-b919-6feacfd65d69', '{"en": "Those in debt", "bn": "ঋণগ্রস্তরা"}', true, 3), ('eff8021b-30fa-5031-ab11-6c81254cf155', '19244de3-23bb-5bea-b919-6feacfd65d69', '{"en": "Neighbours", "bn": "প্রতিবেশীরা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('995adcf6-2b1c-5131-b2af-bfdeae83f96e', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "In Ibn ‘Umar’s hadith, Zakat al-Fitr was set as one sa‘ of…?", "bn": "ইবনে উমর (রা.)-এর হাদিসে সদকাতুল ফিতর নির্ধারণ করা হয় এক সা…"}', '{"en": "\"The Messenger of Allah ﷺ made Zakat al-Fitr obligatory: one sa‘ of dates or one sa‘ of barley…\"", "bn": "\"রাসুলুল্লাহ ﷺ সদকাতুল ফিতর ফরজ করেছেন: এক সা খেজুর বা এক সা যব…\""}', 'Sahih al-Bukhari 1503', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d08a3ff5-8951-58ea-98cd-7960821c5865', '995adcf6-2b1c-5131-b2af-bfdeae83f96e', '{"en": "Meat", "bn": "গোশত"}', false, 1), ('f4a2d4dd-21f0-5771-9a67-faf8f9634ec5', '995adcf6-2b1c-5131-b2af-bfdeae83f96e', '{"en": "Milk", "bn": "দুধ"}', false, 2), ('21a34521-67c3-5a8e-8b29-eb2f19b84bf6', '995adcf6-2b1c-5131-b2af-bfdeae83f96e', '{"en": "Salt", "bn": "লবণ"}', false, 3), ('4fb9ff6d-0f48-59a7-9c3d-9709590ca3f3', '995adcf6-2b1c-5131-b2af-bfdeae83f96e', '{"en": "Dates or barley", "bn": "খেজুর বা যব"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ba2ba815-37af-598b-beea-1aafaaaaa15a', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "In the Quran, zakat is most often mentioned together with…?", "bn": "কুরআনে যাকাতের কথা সবচেয়ে বেশি কিসের সঙ্গে এসেছে?"}', '{"en": "\"Establish the prayer and give the zakat\" comes again and again.", "bn": "\"নামাজ কায়েম করো এবং যাকাত দাও\" — বারবার এসেছে।"}', 'Quran 2:43; Quran 2:110', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('80eca8fe-7bca-5e65-aaaf-1ef8cef3cf48', 'ba2ba815-37af-598b-beea-1aafaaaaa15a', '{"en": "Salah", "bn": "নামাজ"}', true, 1), ('e2ca7082-c0a1-5637-9a6b-fe37bcb880c5', 'ba2ba815-37af-598b-beea-1aafaaaaa15a', '{"en": "Hajj", "bn": "হজ"}', false, 2), ('4f970448-4439-5993-99b1-d1c50dd511bc', 'ba2ba815-37af-598b-beea-1aafaaaaa15a', '{"en": "Fasting", "bn": "রোজা"}', false, 3), ('d3c4278a-b514-55ab-9d4c-d00dfc2d1c5b', 'ba2ba815-37af-598b-beea-1aafaaaaa15a', '{"en": "Trade", "bn": "ব্যবসা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('34773d8d-251f-54d3-99ac-d847ac24eea8', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "Is zakat due on the house a person lives in?", "bn": "যে বাড়িতে মানুষ বসবাস করে, তাতে কি যাকাত আছে?"}', '{"en": "\"There is no zakat on a Muslim’s slave or his horse\": things kept for one’s own use are not zakatable.", "bn": "\"মুসলিমের দাস ও ঘোড়ায় যাকাত নেই\": নিজের ব্যবহারের জিনিসে যাকাত নেই।"}', 'Sahih al-Bukhari 1464', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7ef41db1-b605-5bfa-87c1-872403bb73a8', '34773d8d-251f-54d3-99ac-d847ac24eea8', '{"en": "Yes, 2.5% of its value", "bn": "হ্যাঁ, মূল্যের ২.৫%"}', false, 1), ('244ac086-bd38-5b35-955b-2779151945d4', '34773d8d-251f-54d3-99ac-d847ac24eea8', '{"en": "No — things kept for personal use are exempt", "bn": "না — ব্যক্তিগত ব্যবহারের জিনিসে যাকাত নেই"}', true, 2), ('3b6aa40d-d4bc-574f-b414-42eea205dc3e', '34773d8d-251f-54d3-99ac-d847ac24eea8', '{"en": "Yes, 10% of its value", "bn": "হ্যাঁ, মূল্যের ১০%"}', false, 3), ('2eb99d87-e772-5f24-bbb8-3cd2b2061fbe', '34773d8d-251f-54d3-99ac-d847ac24eea8', '{"en": "Only if it has a garden", "bn": "বাগান থাকলে আছে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b856c56b-b7a8-50b7-9004-c7de8b81eaac', 'd99125a9-5113-506b-8454-165142a8a739', '{"en": "The share due on buried treasure (rikaz) is…?", "bn": "মাটির নিচে পাওয়া গুপ্তধনে (রিকায) কত অংশ দিতে হয়?"}', '{"en": "\"…and on rikaz is one fifth.\"", "bn": "\"…আর রিকাযে এক-পঞ্চমাংশ।\""}', 'Sahih al-Bukhari 1499', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('616300ba-606e-5c2e-b05b-ee413d45b92d', 'b856c56b-b7a8-50b7-9004-c7de8b81eaac', '{"en": "One tenth", "bn": "এক-দশমাংশ"}', false, 1), ('9f7d0dc8-8318-5917-81b3-1c2642d58295', 'b856c56b-b7a8-50b7-9004-c7de8b81eaac', '{"en": "2.5%", "bn": "২.৫%"}', false, 2), ('d6e6e197-fd80-5da2-a568-ce245041bebe', 'b856c56b-b7a8-50b7-9004-c7de8b81eaac', '{"en": "One fifth", "bn": "এক-পঞ্চমাংশ"}', true, 3), ('5e67ae44-eefc-5a1b-b822-d46dae5c4c00', 'b856c56b-b7a8-50b7-9004-c7de8b81eaac', '{"en": "Half", "bn": "অর্ধেক"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "Hajj & Umrah: the rites", "bn": "হজ ও উমরাহ: আমলসমূহ"}', 'pillars', 'medium', NULL, 10, 'in_review', 107) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('009f8003-df98-58d0-9a59-a96b5cd13832', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "How does the talbiyah begin?", "bn": "তালবিয়া কীভাবে শুরু হয়?"}', '{"en": "\"Labbayk Allahumma labbayk… — Here I am, O Allah, here I am…\"", "bn": "\"লাব্বাইক আল্লাহুম্মা লাব্বাইক… — আমি হাজির, হে আল্লাহ, আমি হাজির…\""}', 'Sahih al-Bukhari 1549', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8ea9d4cd-0003-549f-813e-404e987a7e67', '009f8003-df98-58d0-9a59-a96b5cd13832', '{"en": "Allahu Akbar, Allahu Akbar", "bn": "আল্লাহু আকবার, আল্লাহু আকবার"}', false, 1), ('d380c7fc-a54a-5703-8696-bea3320aa4ac', '009f8003-df98-58d0-9a59-a96b5cd13832', '{"en": "Bismillahir-Rahmanir-Rahim", "bn": "বিসমিল্লাহির রাহমানির রাহিম"}', false, 2), ('c1a53ab7-3a8d-5a55-a408-520f06ca6964', '009f8003-df98-58d0-9a59-a96b5cd13832', '{"en": "Labbayk Allahumma labbayk", "bn": "লাব্বাইক আল্লাহুম্মা লাব্বাইক"}', true, 3), ('2dfc7c1b-ebcb-59a1-b3e2-212bedbcdf74', '009f8003-df98-58d0-9a59-a96b5cd13832', '{"en": "Subhanallah wal-hamdulillah", "bn": "সুবহানাল্লাহ ওয়াল হামদুলিল্লাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e57038c7-d5a4-585b-9ea3-637236b5c34a', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "At which hill does sa‘i begin?", "bn": "সাঈ কোন পাহাড় থেকে শুরু হয়?"}', '{"en": "\"I begin with what Allah began with\": \"Indeed, as-Safa and al-Marwah are among the symbols of Allah.\"", "bn": "\"আল্লাহ যা দিয়ে শুরু করেছেন আমিও তা দিয়ে শুরু করছি\": \"নিশ্চয় সাফা ও মারওয়া আল্লাহর নিদর্শন।\""}', 'Quran 2:158; Sahih Muslim 1218', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('efc617b8-f9c8-5cae-b282-1051c507d8eb', 'e57038c7-d5a4-585b-9ea3-637236b5c34a', '{"en": "As-Safa", "bn": "সাফা"}', true, 1), ('af57f663-83f7-56c9-b6dd-310976c0471e', 'e57038c7-d5a4-585b-9ea3-637236b5c34a', '{"en": "Al-Marwah", "bn": "মারওয়া"}', false, 2), ('ccb0e542-1d3c-509c-84a4-e4c70638eddc', 'e57038c7-d5a4-585b-9ea3-637236b5c34a', '{"en": "Arafat", "bn": "আরাফাত"}', false, 3), ('6a7f8b8e-62e3-5fea-84c8-6d1c282fa5ec', 'e57038c7-d5a4-585b-9ea3-637236b5c34a', '{"en": "Uhud", "bn": "উহুদ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8133eeb7-1738-5c1c-a938-dabf61d49681', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "Seven trips of sa‘i end at…?", "bn": "সাঈর সাত চক্কর কোথায় শেষ হয়?"}', '{"en": "Safa to Marwah is one trip and back is another, so the seventh ends at Marwah.", "bn": "সাফা থেকে মারওয়া এক চক্কর, ফেরা আরেক চক্কর; তাই সপ্তম চক্কর মারওয়ায় শেষ হয়।"}', 'Sahih Muslim 1218', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('96bfedf6-8fe3-5336-aacf-49e067c09789', '8133eeb7-1738-5c1c-a938-dabf61d49681', '{"en": "As-Safa", "bn": "সাফা"}', false, 1), ('be804e22-ac54-598a-9742-8999cccacf50', '8133eeb7-1738-5c1c-a938-dabf61d49681', '{"en": "Mina", "bn": "মিনা"}', false, 2), ('70100b6a-18a5-5cbe-b8d0-ceb7a619fa18', '8133eeb7-1738-5c1c-a938-dabf61d49681', '{"en": "Al-Marwah", "bn": "মারওয়া"}', true, 3), ('8cd1f468-4bcb-5ea6-b881-50ac5150d9c9', '8133eeb7-1738-5c1c-a938-dabf61d49681', '{"en": "The Ka‘bah", "bn": "কাবা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f622eb3d-e53e-5df1-8c60-0cb7960bb1cc', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "From which corner of the Ka‘bah does each tawaf begin?", "bn": "কাবার কোন কোণ থেকে তাওয়াফ শুরু হয়?"}', '{"en": "Jabir (RA): when he ﷺ came to the House he touched the (Black Stone) corner and then walked around.", "bn": "জাবির (রা.): নবী ﷺ বায়তুল্লাহয় এসে (হাজরে আসওয়াদের) কোণ স্পর্শ করলেন, তারপর তাওয়াফ করলেন।"}', 'Sahih Muslim 1218', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('074e5ee5-a79b-5b0b-8158-dc3904cd3883', 'f622eb3d-e53e-5df1-8c60-0cb7960bb1cc', '{"en": "The Yemeni corner", "bn": "রুকনে ইয়ামানি"}', false, 1), ('be7ae306-0c03-508b-bf1c-47d32017dce5', 'f622eb3d-e53e-5df1-8c60-0cb7960bb1cc', '{"en": "The corner of the Black Stone", "bn": "হাজরে আসওয়াদের কোণ"}', true, 2), ('a56905e8-e15d-53f5-9ed3-7ee550beec6f', 'f622eb3d-e53e-5df1-8c60-0cb7960bb1cc', '{"en": "The door of the Ka‘bah", "bn": "কাবার দরজা"}', false, 3), ('78adb152-08eb-5f7a-aebd-c0602be164c8', 'f622eb3d-e53e-5df1-8c60-0cb7960bb1cc', '{"en": "Maqam Ibrahim", "bn": "মাকামে ইবরাহিম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ea6d7892-369e-553e-af8b-9d0f8b7f623f', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "The three ways of performing Hajj are Ifrad, Qiran and…?", "bn": "হজের তিন প্রকার: ইফরাদ, কিরান ও…?"}', '{"en": "‘A’ishah (RA): some of us entered ihram for Umrah (then Hajj), some for Hajj and Umrah together, and some for Hajj alone.", "bn": "আয়েশা (রা.): আমাদের কেউ উমরাহর (পরে হজের), কেউ হজ ও উমরাহ একসঙ্গে, আর কেউ শুধু হজের ইহরাম বেঁধেছিলেন।"}', 'Sahih al-Bukhari 1562', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8cb97164-ea03-597e-83e9-313dc735c297', 'ea6d7892-369e-553e-af8b-9d0f8b7f623f', '{"en": "Tawaf", "bn": "তাওয়াফ"}', false, 1), ('d1e2ffbb-5160-511a-aab3-df607ca899d9', 'ea6d7892-369e-553e-af8b-9d0f8b7f623f', '{"en": "Tarwiyah", "bn": "তারবিয়া"}', false, 2), ('962ff61f-70ac-5a95-94ff-4aa395dca21f', 'ea6d7892-369e-553e-af8b-9d0f8b7f623f', '{"en": "I‘tikaf", "bn": "ইতিকাফ"}', false, 3), ('8dad5e0d-d881-50d7-a8ab-e88099df1689', 'ea6d7892-369e-553e-af8b-9d0f8b7f623f', '{"en": "Tamattu‘", "bn": "তামাত্তু"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4110a7b7-7da8-53b3-ac3b-96cc0c5a8c99', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "The fixed places where pilgrims must enter ihram are called…?", "bn": "হাজিদের যে নির্দিষ্ট স্থানে ইহরাম বাঁধতে হয়, তাকে কী বলে?"}', '{"en": "The Prophet ﷺ fixed the miqats for the people of each region.", "bn": "নবী ﷺ প্রত্যেক অঞ্চলের মানুষের জন্য মিকাত নির্ধারণ করেছেন।"}', 'Sahih al-Bukhari 1524', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cd49a6b2-8991-55bf-92c6-e41d82dd21aa', '4110a7b7-7da8-53b3-ac3b-96cc0c5a8c99', '{"en": "Miqat", "bn": "মিকাত"}', true, 1), ('65992ba8-480b-5ab6-811c-413700f05dd5', '4110a7b7-7da8-53b3-ac3b-96cc0c5a8c99', '{"en": "Mash‘ar", "bn": "মাশআর"}', false, 2), ('71c6c85e-46ed-5ca2-bffd-40746e0434ac', '4110a7b7-7da8-53b3-ac3b-96cc0c5a8c99', '{"en": "Jamarat", "bn": "জামারাত"}', false, 3), ('b4a2bc49-eb90-5bc7-9296-d31a81f0f52e', '4110a7b7-7da8-53b3-ac3b-96cc0c5a8c99', '{"en": "Multazam", "bn": "মুলতাজাম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('97c2f4cf-2043-5695-a96b-f0c813f69954', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "What is the miqat of the people of Madinah?", "bn": "মদিনাবাসীর মিকাত কোনটি?"}', '{"en": "Dhul-Hulayfah for Madinah, al-Juhfah for Sham, Qarn al-Manazil for Najd and Yalamlam for Yemen.", "bn": "মদিনার জন্য যুলহুলাইফা, শামের জন্য জুহফা, নজদের জন্য কারনুল মানাযিল, ইয়েমেনের জন্য ইয়ালামলাম।"}', 'Sahih al-Bukhari 1524', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c75629bb-efb4-5b42-bdd2-92039b30b2a4', '97c2f4cf-2043-5695-a96b-f0c813f69954', '{"en": "Yalamlam", "bn": "ইয়ালামলাম"}', false, 1), ('35037f41-74d1-56ec-b7d9-99db361d0b1b', '97c2f4cf-2043-5695-a96b-f0c813f69954', '{"en": "Al-Juhfah", "bn": "জুহফা"}', false, 2), ('1c9a8403-faec-5015-b55d-0e680efbb33d', '97c2f4cf-2043-5695-a96b-f0c813f69954', '{"en": "Dhul-Hulayfah", "bn": "যুলহুলাইফা"}', true, 3), ('16f5b7e0-36ac-54f0-b15f-a22de5448403', '97c2f4cf-2043-5695-a96b-f0c813f69954', '{"en": "Qarn al-Manazil", "bn": "কারনুল মানাযিল"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8b2d4873-885c-5556-923b-92f959384b01', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "The Prophet ﷺ prayed three times for mercy for men who … their heads at the end of Hajj or Umrah.", "bn": "হজ-উমরাহ শেষে যারা মাথা … , নবী ﷺ তাদের জন্য তিনবার রহমতের দোয়া করেছেন।"}', '{"en": "\"O Allah, have mercy on those who shave\" — three times — then \"and those who shorten\".", "bn": "\"হে আল্লাহ, মাথা মুণ্ডনকারীদের প্রতি রহম করুন\" — তিনবার — তারপর \"এবং চুল ছোটকারীদের প্রতিও\"।"}', 'Sahih al-Bukhari 1727', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a57a3a54-f9cf-53a4-9167-2e66e2a0e3b7', '8b2d4873-885c-5556-923b-92f959384b01', '{"en": "Cover", "bn": "ঢেকে রাখে"}', false, 1), ('5d424ad3-69b1-5c5f-a1d3-e7f4d2eb360e', '8b2d4873-885c-5556-923b-92f959384b01', '{"en": "Shave", "bn": "মুণ্ডন করে"}', true, 2), ('83751926-8b5b-51f6-8469-9ef81e8596cf', '8b2d4873-885c-5556-923b-92f959384b01', '{"en": "Oil", "bn": "তেল দেয়"}', false, 3), ('d51d82e6-9b18-5c77-bc74-a14a1973637f', '8b2d4873-885c-5556-923b-92f959384b01', '{"en": "Wash", "bn": "ধোয়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7c6cd0bf-0942-530d-bdbb-438b0e61ba36', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "Which of these is forbidden in ihram?", "bn": "ইহরাম অবস্থায় নিচের কোনটি নিষিদ্ধ?"}', '{"en": "\"O you who believe, do not kill game while you are in ihram.\"", "bn": "\"হে মুমিনগণ, ইহরাম অবস্থায় তোমরা শিকার বধ কোরো না।\""}', 'Quran 5:95', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('5993b8bd-becd-5f97-a60a-61450261afe7', '7c6cd0bf-0942-530d-bdbb-438b0e61ba36', '{"en": "Saying the talbiyah", "bn": "তালবিয়া পড়া"}', false, 1), ('9f9e07c8-5b4b-5b20-97e9-4548181ac1cd', '7c6cd0bf-0942-530d-bdbb-438b0e61ba36', '{"en": "Drinking Zamzam", "bn": "জমজম পান করা"}', false, 2), ('38c603c0-4e6b-59cf-a590-74f02fcfb59d', '7c6cd0bf-0942-530d-bdbb-438b0e61ba36', '{"en": "Making dua", "bn": "দোয়া করা"}', false, 3), ('fc664f38-d489-5395-b738-2292b6514027', '7c6cd0bf-0942-530d-bdbb-438b0e61ba36', '{"en": "Hunting land animals", "bn": "স্থলের প্রাণী শিকার করা"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5e825f90-3954-5df4-afe8-5e3931063893', 'f1dce449-4673-53c2-96ca-d34b10942ddc', '{"en": "The reward for an accepted Hajj (Hajj mabrur) is…?", "bn": "কবুল হজের (হজ্জে মাবরুর) প্রতিদান কী?"}', '{"en": "\"An accepted Hajj has no reward except Paradise.\"", "bn": "\"কবুল হজের প্রতিদান জান্নাত ছাড়া আর কিছু নয়।\""}', 'Sahih al-Bukhari 1773', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('55747fa9-8534-51ae-bc08-8f25428099a3', '5e825f90-3954-5df4-afe8-5e3931063893', '{"en": "Nothing less than Paradise", "bn": "জান্নাত ছাড়া আর কিছু নয়"}', true, 1), ('0a349542-5fdc-53f5-8ab7-1d82ea2acbce', '5e825f90-3954-5df4-afe8-5e3931063893', '{"en": "Wealth", "bn": "সম্পদ"}', false, 2), ('1467b3cb-c981-5ce3-8987-ed63ae1393b7', '5e825f90-3954-5df4-afe8-5e3931063893', '{"en": "A title", "bn": "উপাধি"}', false, 3), ('04d7cb4f-f50f-56dd-b701-f6d89aa54480', '5e825f90-3954-5df4-afe8-5e3931063893', '{"en": "Long life", "bn": "দীর্ঘ জীবন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "The days of Hajj", "bn": "হজের দিনগুলো"}', 'pillars', 'hard', 600, 10, 'in_review', 108) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3854f5d4-60d1-5cbb-a3ce-b491b7c1fcaa', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "What is the 8th of Dhul Hijjah called?", "bn": "জিলহজের ৮ তারিখকে কী বলা হয়?"}', '{"en": "On the Day of Tarwiyah the pilgrims set out for Mina.", "bn": "তারবিয়ার দিন হাজিরা মিনার দিকে রওনা হন।"}', 'Sahih Muslim 1218', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a632594b-ad3c-5373-a95f-79e13ad528de', '3854f5d4-60d1-5cbb-a3ce-b491b7c1fcaa', '{"en": "Yawm an-Nahr", "bn": "ইয়াওমুন নাহর"}', false, 1), ('023ed28c-5a94-560c-abb5-d498c21dafd8', '3854f5d4-60d1-5cbb-a3ce-b491b7c1fcaa', '{"en": "Yawm at-Tarwiyah", "bn": "ইয়াওমুত তারবিয়া"}', true, 2), ('36f7d28b-374e-55d7-9df4-87382578fa1d', '3854f5d4-60d1-5cbb-a3ce-b491b7c1fcaa', '{"en": "Yawm ‘Arafah", "bn": "ইয়াওমু আরাফা"}', false, 3), ('6e3456e8-8054-5ba7-b077-7076be5a8ad6', '3854f5d4-60d1-5cbb-a3ce-b491b7c1fcaa', '{"en": "Yawm al-Qarr", "bn": "ইয়াওমুল কার"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8b2332ec-ecb1-5ee5-97c3-549d08af0461', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "On the 8th of Dhul Hijjah the pilgrims go to…?", "bn": "জিলহজের ৮ তারিখে হাজিরা কোথায় যান?"}', '{"en": "They go to Mina and pray Dhuhr, Asr, Maghrib, Isha and Fajr there.", "bn": "তাঁরা মিনায় যান এবং সেখানে যোহর, আসর, মাগরিব, এশা ও ফজর পড়েন।"}', 'Sahih Muslim 1218', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c57f0725-3975-5cda-9c18-4e3f31eb0316', '8b2332ec-ecb1-5ee5-97c3-549d08af0461', '{"en": "Madinah", "bn": "মদিনা"}', false, 1), ('76121827-9495-5a3f-88ec-f7af2def8393', '8b2332ec-ecb1-5ee5-97c3-549d08af0461', '{"en": "Muzdalifah", "bn": "মুজদালিফা"}', false, 2), ('eff6fc26-2509-5365-b7c3-b7f83e84b647', '8b2332ec-ecb1-5ee5-97c3-549d08af0461', '{"en": "Mina", "bn": "মিনা"}', true, 3), ('332b6285-765a-5b56-aade-194eb182bf6c', '8b2332ec-ecb1-5ee5-97c3-549d08af0461', '{"en": "Ta’if", "bn": "তায়েফ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fbbb2658-5db3-521b-a324-d3094443c75e', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "Where was the Prophet’s ﷺ tent pitched on the Day of Arafah?", "bn": "আরাফার দিন নবী ﷺ-এর তাঁবু কোথায় খাটানো হয়েছিল?"}', '{"en": "Jabir (RA): he ﷺ found the tent pitched for him at Namirah and stayed there until the sun passed its height.", "bn": "জাবির (রা.): নবী ﷺ নামিরায় তাঁর জন্য খাটানো তাঁবু পেলেন এবং সূর্য হেলে পড়া পর্যন্ত সেখানে ছিলেন।"}', 'Sahih Muslim 1218', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('14f10dfe-b96b-5555-b90b-aaced1e9aee0', 'fbbb2658-5db3-521b-a324-d3094443c75e', '{"en": "Namirah", "bn": "নামিরা"}', true, 1), ('feab8f3a-a706-54b6-b2f8-9f339376cf98', 'fbbb2658-5db3-521b-a324-d3094443c75e', '{"en": "Quba", "bn": "কুবা"}', false, 2), ('680aee81-4715-56c8-b468-7208ea499b91', 'fbbb2658-5db3-521b-a324-d3094443c75e', '{"en": "Hira", "bn": "হেরা"}', false, 3), ('cb6d01e1-0753-5aea-8ba2-7d418a4008d2', 'fbbb2658-5db3-521b-a324-d3094443c75e', '{"en": "Badr", "bn": "বদর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('dce5481c-095d-5583-bd03-7ebb581d5255', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "At Muzdalifah, which two prayers are joined together?", "bn": "মুজদালিফায় কোন দুই নামাজ একসঙ্গে পড়া হয়?"}', '{"en": "After leaving Arafat at sunset, he ﷺ came to Muzdalifah and prayed Maghrib and Isha there together.", "bn": "সূর্যাস্তের পর আরাফা থেকে রওনা দিয়ে নবী ﷺ মুজদালিফায় এসে মাগরিব ও এশা একসঙ্গে পড়েছেন।"}', 'Sahih Muslim 1218', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('5eddddc3-9cff-5706-aa9b-c0f0ff303d2d', 'dce5481c-095d-5583-bd03-7ebb581d5255', '{"en": "Fajr and Dhuhr", "bn": "ফজর ও যোহর"}', false, 1), ('98876677-8d16-5ad5-8d3d-5a01cd1c18a8', 'dce5481c-095d-5583-bd03-7ebb581d5255', '{"en": "Dhuhr and Asr", "bn": "যোহর ও আসর"}', false, 2), ('c4feb684-387c-5ccc-a300-ad5ba35e6c9d', 'dce5481c-095d-5583-bd03-7ebb581d5255', '{"en": "Asr and Maghrib", "bn": "আসর ও মাগরিব"}', false, 3), ('b4c98f44-c3b7-55a7-8138-c0a84eb9aadd', 'dce5481c-095d-5583-bd03-7ebb581d5255', '{"en": "Maghrib and Isha", "bn": "মাগরিব ও এশা"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0dc82a1d-17df-5069-a858-e7f351da8edc', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "After Fajr at Muzdalifah, the Prophet ﷺ stood in remembrance and dua at…?", "bn": "মুজদালিফায় ফজরের পর নবী ﷺ কোথায় দাঁড়িয়ে জিকির ও দোয়া করেছেন?"}', '{"en": "\"…remember Allah at al-Mash‘ar al-Haram.\" He ﷺ stayed there till it was very bright, then left before sunrise.", "bn": "\"…মাশআরুল হারামের কাছে আল্লাহকে স্মরণ করো।\" নবী ﷺ ভালোভাবে আলো ছড়ানো পর্যন্ত সেখানে ছিলেন, সূর্যোদয়ের আগে রওনা দেন।"}', 'Quran 2:198; Sahih Muslim 1218', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1672dbad-5b02-56e4-8b83-a508249983a5', '0dc82a1d-17df-5069-a858-e7f351da8edc', '{"en": "Al-Mash‘ar al-Haram", "bn": "আল-মাশআরুল হারাম"}', true, 1), ('cf7f99a7-8a29-5aae-9bca-7d6e81b43404', '0dc82a1d-17df-5069-a858-e7f351da8edc', '{"en": "Jabal an-Nur", "bn": "জাবালে নূর"}', false, 2), ('02e01ce9-f5e1-5c7f-8d7c-7e69f7e5cf06', '0dc82a1d-17df-5069-a858-e7f351da8edc', '{"en": "Al-Baqi‘", "bn": "জান্নাতুল বাকি"}', false, 3), ('ebbeef36-d28e-580a-8358-46f73705a8bc', '0dc82a1d-17df-5069-a858-e7f351da8edc', '{"en": "Al-Hijr", "bn": "হিজর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('03932731-1627-5d0a-8951-1aa1ea67033c', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "On the 10th of Dhul Hijjah, which jamrah is stoned?", "bn": "জিলহজের ১০ তারিখে কোন জামরায় কংকর মারা হয়?"}', '{"en": "On the Day of Sacrifice he ﷺ stoned only Jamrat al-‘Aqabah; all three are stoned on the days after.", "bn": "কুরবানির দিন নবী ﷺ শুধু জামরাতুল আকাবায় কংকর মেরেছেন; পরের দিনগুলোতে তিনটিতেই মারা হয়।"}', 'Sahih Muslim 1218', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('460e31de-efa2-5814-a9f0-adf42970a0eb', '03932731-1627-5d0a-8951-1aa1ea67033c', '{"en": "All three", "bn": "তিনটিতেই"}', false, 1), ('b4a84ef0-1b39-53a3-a394-49c5f3d327a5', '03932731-1627-5d0a-8951-1aa1ea67033c', '{"en": "Only the small one", "bn": "শুধু ছোটটিতে"}', false, 2), ('c6541b23-15fd-5337-83a5-47ed656ecb39', '03932731-1627-5d0a-8951-1aa1ea67033c', '{"en": "Only Jamrat al-‘Aqabah (the big one)", "bn": "শুধু জামরাতুল আকাবা (বড়টি)"}', true, 3), ('21f63a49-ac96-5f87-b8fb-07d0eba302dc', '03932731-1627-5d0a-8951-1aa1ea67033c', '{"en": "None", "bn": "কোনোটিতেই না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ee2fd768-7a56-5080-baae-ef28434d4d4b', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "How many pebbles are thrown at each jamrah each time?", "bn": "প্রতিবার প্রতিটি জামরায় কয়টি কংকর মারা হয়?"}', '{"en": "He ﷺ threw seven pebbles, saying \"Allahu Akbar\" with each one.", "bn": "নবী ﷺ প্রতিটির সঙ্গে \"আল্লাহু আকবার\" বলে সাতটি কংকর মেরেছেন।"}', 'Sahih Muslim 1218; Sahih al-Bukhari 1751', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('60530608-b495-59f0-aeb5-246ba2013a21', 'ee2fd768-7a56-5080-baae-ef28434d4d4b', '{"en": "3", "bn": "৩"}', false, 1), ('3d873eed-d54c-5946-9697-8f196359ee29', 'ee2fd768-7a56-5080-baae-ef28434d4d4b', '{"en": "5", "bn": "৫"}', false, 2), ('1f6f64c7-7eb1-50d6-b2b6-f99aeda409b5', 'ee2fd768-7a56-5080-baae-ef28434d4d4b', '{"en": "10", "bn": "১০"}', false, 3), ('c9065226-ffa6-5d27-8f17-2da31158cdb1', 'ee2fd768-7a56-5080-baae-ef28434d4d4b', '{"en": "7", "bn": "৭"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b392ccef-a5cd-5d7e-ab30-25999a39bdfe', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "Which tawaf is a pillar (rukn) of Hajj, done on or after the 10th?", "bn": "কোন তাওয়াফ হজের রুকন, যা ১০ তারিখ বা পরে করা হয়?"}', '{"en": "\"…and let them perform tawaf around the Ancient House.\" All agree Hajj is not complete without it.", "bn": "\"…এবং তারা যেন প্রাচীন ঘরের তাওয়াফ করে।\" এটি ছাড়া হজ পূর্ণ হয় না — এ বিষয়ে সবাই একমত।"}', 'Quran 22:29', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0ebc08b7-8eea-55ba-a4a5-0b4bc0f8023e', 'b392ccef-a5cd-5d7e-ab30-25999a39bdfe', '{"en": "Tawaf al-Ifadah (az-Ziyarah)", "bn": "তাওয়াফে ইফাদা (যিয়ারত)"}', true, 1), ('f198932f-0aba-5fb9-b99f-697be45692ff', 'b392ccef-a5cd-5d7e-ab30-25999a39bdfe', '{"en": "Tawaf al-Wada‘", "bn": "তাওয়াফে বিদা"}', false, 2), ('c00c368e-0b23-5053-bf54-79cf254ec40f', 'b392ccef-a5cd-5d7e-ab30-25999a39bdfe', '{"en": "Tawaf al-Qudum", "bn": "তাওয়াফে কুদুম"}', false, 3), ('3ed52f8c-59d2-5116-a507-900916a431ec', 'b392ccef-a5cd-5d7e-ab30-25999a39bdfe', '{"en": "A voluntary tawaf", "bn": "নফল তাওয়াফ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6521b590-7c86-58cc-bf13-9afb7c2ff1ff', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "The last thing a pilgrim does before leaving Makkah is…?", "bn": "মক্কা ছাড়ার আগে হাজির শেষ কাজ কী?"}', '{"en": "\"The people were ordered that their last moment should be at the House\" — excused for women in menses.", "bn": "\"মানুষকে আদেশ দেওয়া হয়েছে, তাদের শেষ সময় যেন বায়তুল্লাহর সঙ্গে হয়\" — ঋতুমতী নারীর জন্য ছাড় আছে।"}', 'Sahih al-Bukhari 1755', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('182f8793-50e3-54ff-b09a-b103a92df144', '6521b590-7c86-58cc-bf13-9afb7c2ff1ff', '{"en": "Sa‘i", "bn": "সাঈ"}', false, 1), ('aa15f288-fe05-551f-93a2-9c64b28c3805', '6521b590-7c86-58cc-bf13-9afb7c2ff1ff', '{"en": "The farewell tawaf (Tawaf al-Wada‘)", "bn": "বিদায়ী তাওয়াফ (তাওয়াফে বিদা)"}', true, 2), ('50db2db5-b4d6-59d7-a241-c3ab42d98ff8', '6521b590-7c86-58cc-bf13-9afb7c2ff1ff', '{"en": "Stoning", "bn": "কংকর মারা"}', false, 3), ('f795af15-791b-57fc-9ed7-7363ed40c28f', '6521b590-7c86-58cc-bf13-9afb7c2ff1ff', '{"en": "Shaving", "bn": "মাথা মুণ্ডন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('14941e52-fed3-5124-b08e-c1e6ee5dd5fb', '8a13d7b1-433f-5da1-adc3-dca924c25562', '{"en": "The days of Tashriq are which dates of Dhul Hijjah?", "bn": "আইয়ামে তাশরিক জিলহজের কোন তারিখগুলো?"}', '{"en": "The three days after the Day of Sacrifice: \"days of eating, drinking and remembering Allah\".", "bn": "কুরবানির দিনের পরের তিন দিন: \"খাওয়া, পান করা ও আল্লাহর জিকিরের দিন\"।"}', 'Quran 2:203; Sahih Muslim 1141', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('668dcad1-9ccd-54bd-aee5-6f7837505cbf', '14941e52-fed3-5124-b08e-c1e6ee5dd5fb', '{"en": "1st–3rd", "bn": "১–৩"}', false, 1), ('b2c430b7-1f12-54ac-830c-3c3bd5bed003', '14941e52-fed3-5124-b08e-c1e6ee5dd5fb', '{"en": "7th–9th", "bn": "৭–৯"}', false, 2), ('382c6dfa-7017-5d0d-a957-e143d3e072b7', '14941e52-fed3-5124-b08e-c1e6ee5dd5fb', '{"en": "11th–13th", "bn": "১১–১৩"}', true, 3), ('35068fa6-f5d0-58d7-9818-1562c54a9729', '14941e52-fed3-5124-b08e-c1e6ee5dd5fb', '{"en": "20th–22nd", "bn": "২০–২২"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "Qurbani (udhiyah)", "bn": "কুরবানি"}', 'fiqh', 'easy', NULL, 10, 'in_review', 109) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4fa181c6-55ca-5ab3-9b92-f7d27f1f0a2d', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "From which animals is qurbani given?", "bn": "কোন পশু দিয়ে কুরবানি দেওয়া হয়?"}', '{"en": "\"…that they may mention the name of Allah over the livestock (bahimat al-an‘am) He has provided them.\"", "bn": "\"…যাতে তারা আল্লাহর দেওয়া চতুষ্পদ গৃহপালিত পশুর (বাহিমাতুল আনআম) ওপর তাঁর নাম নেয়।\""}', 'Quran 22:34', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('edb2256a-ebc2-59a1-a64e-d538f5d1622a', '4fa181c6-55ca-5ab3-9b92-f7d27f1f0a2d', '{"en": "Camels, cattle, sheep and goats", "bn": "উট, গরু-মহিষ, ভেড়া ও ছাগল"}', true, 1), ('99781dcd-ef30-503e-9567-eb39e79ba6a2', '4fa181c6-55ca-5ab3-9b92-f7d27f1f0a2d', '{"en": "Chickens and ducks", "bn": "মুরগি ও হাঁস"}', false, 2), ('1528fe48-5927-5ac3-bdf1-48988e87f6ae', '4fa181c6-55ca-5ab3-9b92-f7d27f1f0a2d', '{"en": "Fish", "bn": "মাছ"}', false, 3), ('630cf0e5-eafe-5d99-a845-cf7e9d971588', '4fa181c6-55ca-5ab3-9b92-f7d27f1f0a2d', '{"en": "Deer and rabbits", "bn": "হরিণ ও খরগোশ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b117e66f-75c8-51be-a1df-105da5276ad5', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "In Jabir’s hadith, a camel or a cow was shared in sacrifice by how many people?", "bn": "জাবির (রা.)-এর হাদিসে একটি উট বা গরুতে কতজন শরিক হয়েছিলেন?"}', '{"en": "\"We sacrificed with the Messenger of Allah ﷺ … a camel for seven and a cow for seven.\"", "bn": "\"আমরা রাসুলুল্লাহ ﷺ-এর সঙ্গে কুরবানি করেছি… একটি উট সাতজনের পক্ষ থেকে, একটি গরু সাতজনের পক্ষ থেকে।\""}', 'Sahih Muslim 1318', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('650c1dcf-7c8f-591e-ada8-b7416158ccef', 'b117e66f-75c8-51be-a1df-105da5276ad5', '{"en": "3", "bn": "৩"}', false, 1), ('de97525c-5868-58a4-a2b1-73ddb9fedec2', 'b117e66f-75c8-51be-a1df-105da5276ad5', '{"en": "5", "bn": "৫"}', false, 2), ('eea3966d-857a-5865-8c48-2166a7993e75', 'b117e66f-75c8-51be-a1df-105da5276ad5', '{"en": "7", "bn": "৭"}', true, 3), ('6eae7d1c-7cb7-52c0-87cf-6af42c265844', 'b117e66f-75c8-51be-a1df-105da5276ad5', '{"en": "10", "bn": "১০"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3bd8d5b9-8890-5bcb-a8d1-091d8bcebe93', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "Which surah says: \"Neither their meat nor their blood reaches Allah, but your piety reaches Him\"?", "bn": "কোন সূরায় আছে: \"এগুলোর গোশত বা রক্ত আল্লাহর কাছে পৌঁছায় না, বরং তোমাদের তাকওয়া পৌঁছায়\"?"}', '{"en": "Surah al-Hajj 22:37: what matters is taqwa, not the meat.", "bn": "সূরা আল-হজ ২২:৩৭: আসল বিষয় তাকওয়া, গোশত নয়।"}', 'Quran 22:37', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9e2242a5-590a-524f-981f-8cbfc184630d', '3bd8d5b9-8890-5bcb-a8d1-091d8bcebe93', '{"en": "Al-Baqarah", "bn": "আল-বাকারা"}', false, 1), ('fe39f1cd-3dc6-523a-94e7-a4322978789e', '3bd8d5b9-8890-5bcb-a8d1-091d8bcebe93', '{"en": "Al-Hajj", "bn": "আল-হজ"}', true, 2), ('3a2cea1d-0c99-51b5-b5cf-7c48cd356dce', '3bd8d5b9-8890-5bcb-a8d1-091d8bcebe93', '{"en": "Al-Kawthar", "bn": "আল-কাওসার"}', false, 3), ('9319c2b5-1bfe-5d0c-9de9-fc6381553eec', '3bd8d5b9-8890-5bcb-a8d1-091d8bcebe93', '{"en": "Al-An‘am", "bn": "আল-আনআম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3596fb34-fd83-5404-bfb7-5b59aefe1590', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "Surah al-Kawthar: \"So pray to your Lord and…\"", "bn": "সূরা কাওসার: \"অতএব আপনার রবের জন্য নামাজ পড়ুন এবং…\""}', '{"en": "\"Fa salli li Rabbika wanhar\" — so pray to your Lord and sacrifice.", "bn": "\"ফাসাল্লি লিরাব্বিকা ওয়ানহার\" — অতএব আপনার রবের জন্য নামাজ পড়ুন ও কুরবানি করুন।"}', 'Quran 108:2', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e4676305-aa39-5f6e-9bc7-142f33320d27', '3596fb34-fd83-5404-bfb7-5b59aefe1590', '{"en": "…fast", "bn": "…রোজা রাখুন"}', false, 1), ('040266fd-b79c-53b5-b420-9eae737fcfc1', '3596fb34-fd83-5404-bfb7-5b59aefe1590', '{"en": "…travel", "bn": "…সফর করুন"}', false, 2), ('3690f1a0-49d8-544a-ac35-cdc1d9b049cc', '3596fb34-fd83-5404-bfb7-5b59aefe1590', '{"en": "…give thanks", "bn": "…শুকরিয়া আদায় করুন"}', false, 3), ('f6adc8d5-e2d0-54f2-b8bd-c4f5a656fc06', '3596fb34-fd83-5404-bfb7-5b59aefe1590', '{"en": "…sacrifice", "bn": "…কুরবানি করুন"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('05d825e2-33d7-5720-9ac2-849492b997bf', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "What did the Prophet ﷺ say when slaughtering his sacrifice?", "bn": "কুরবানির পশু জবাইয়ের সময় নবী ﷺ কী বলতেন?"}', '{"en": "Anas (RA): he ﷺ sacrificed two rams, saying \"Bismillah\" and \"Allahu Akbar\".", "bn": "আনাস (রা.): নবী ﷺ দুটি দুম্বা কুরবানি করেছেন, \"বিসমিল্লাহ\" ও \"আল্লাহু আকবার\" বলে।"}', 'Sahih Muslim 1966', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('18856d28-741a-54ab-9c36-891a734114f8', '05d825e2-33d7-5720-9ac2-849492b997bf', '{"en": "Bismillah, Allahu Akbar", "bn": "বিসমিল্লাহ, আল্লাহু আকবার"}', true, 1), ('35a64a08-d46e-5b35-ae44-0a29c31344bc', '05d825e2-33d7-5720-9ac2-849492b997bf', '{"en": "SubhanAllah", "bn": "সুবহানাল্লাহ"}', false, 2), ('f9da13f2-7067-56d3-9641-d2cbcf202d6a', '05d825e2-33d7-5720-9ac2-849492b997bf', '{"en": "Astaghfirullah", "bn": "আসতাগফিরুল্লাহ"}', false, 3), ('885581ae-32d8-5e12-84c5-2386f82c2ba0', '05d825e2-33d7-5720-9ac2-849492b997bf', '{"en": "Nothing", "bn": "কিছুই না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('858de651-536e-5546-92a9-a154726085f4', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "May the one who gives qurbani eat from its meat?", "bn": "কুরবানিদাতা কি কুরবানির গোশত খেতে পারেন?"}', '{"en": "\"…So eat from them and feed the needy and the poor.\"", "bn": "\"…অতঃপর তোমরা তা থেকে খাও এবং দুস্থ ও অভাবীকে খাওয়াও।\""}', 'Quran 22:28; Quran 22:36', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8017c7ca-9ee8-51b3-9238-beb2d30a74a3', '858de651-536e-5546-92a9-a154726085f4', '{"en": "No, never", "bn": "না, কখনোই না"}', false, 1), ('c052659d-b991-518f-8e50-6d2326405c2e', '858de651-536e-5546-92a9-a154726085f4', '{"en": "Only the skin", "bn": "শুধু চামড়া"}', false, 2), ('d78ae293-966e-52e8-a70a-86fbc84a6a5f', '858de651-536e-5546-92a9-a154726085f4', '{"en": "Yes, and he feeds others too", "bn": "হ্যাঁ, এবং অন্যদেরও খাওয়াবেন"}', true, 3), ('0165e125-17b2-5a77-9619-695fe40a7667', '858de651-536e-5546-92a9-a154726085f4', '{"en": "Only after a year", "bn": "শুধু এক বছর পর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1d1f0e88-46af-5718-a712-888e68444692', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "An animal with which defect is not accepted for qurbani?", "bn": "কোন ত্রুটিযুক্ত পশু কুরবানির জন্য গ্রহণযোগ্য নয়?"}', '{"en": "Four are not accepted: clearly one-eyed, clearly sick, clearly lame, and so thin it has no marrow.", "bn": "চারটি চলবে না: স্পষ্ট কানা, স্পষ্ট অসুস্থ, স্পষ্ট খোঁড়া, এবং এত দুর্বল যে হাড়ে মজ্জা নেই।"}', 'Sunan Abi Dawud 2802; Jami‘ at-Tirmidhi 1497', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('dda3207a-da50-5ebd-8ae7-010dd8ce1941', '1d1f0e88-46af-5718-a712-888e68444692', '{"en": "Black in colour", "bn": "কালো রঙের"}', false, 1), ('de767210-c7a8-521a-b270-4a338c2931f6', '1d1f0e88-46af-5718-a712-888e68444692', '{"en": "Fat and healthy", "bn": "মোটাতাজা ও সুস্থ"}', false, 2), ('104713d4-070b-5673-998c-db9c1bc4ad29', '1d1f0e88-46af-5718-a712-888e68444692', '{"en": "Male", "bn": "পুরুষ পশু"}', false, 3), ('c9c01246-2f67-51b8-9d5c-607183300f88', '1d1f0e88-46af-5718-a712-888e68444692', '{"en": "Clearly blind in one eye", "bn": "স্পষ্টভাবে এক চোখ কানা"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('86b70f89-8f3c-520d-a670-a7c7a719ee2f', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "What did the Prophet ﷺ sacrifice on Eid al-Adha, in Anas’s narration?", "bn": "আনাস (রা.)-এর বর্ণনায় নবী ﷺ ঈদুল আজহায় কী কুরবানি করেছেন?"}', '{"en": "\"The Prophet ﷺ sacrificed two horned, black-and-white rams.\"", "bn": "\"নবী ﷺ শিংওয়ালা সাদা-কালো দুটি দুম্বা কুরবানি করেছেন।\""}', 'Sahih al-Bukhari 5565', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f2b7c419-2250-56a2-a428-46e4902d3979', '86b70f89-8f3c-520d-a670-a7c7a719ee2f', '{"en": "A camel", "bn": "একটি উট"}', false, 1), ('b6f3dbb9-460d-50b2-b53b-b7b935de29a4', '86b70f89-8f3c-520d-a670-a7c7a719ee2f', '{"en": "Two horned black-and-white rams", "bn": "শিংওয়ালা সাদা-কালো দুটি দুম্বা"}', true, 2), ('540672c6-7702-535d-a165-be0bfd879105', '86b70f89-8f3c-520d-a670-a7c7a719ee2f', '{"en": "A cow", "bn": "একটি গরু"}', false, 3), ('c144a11a-08f9-504b-bb72-c45d4c8a1b1d', '86b70f89-8f3c-520d-a670-a7c7a719ee2f', '{"en": "Seven goats", "bn": "সাতটি ছাগল"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9821c863-c671-5e7b-993d-32df8dd39753', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "In Umm Salamah’s hadith, one who intends to sacrifice is told, from the start of Dhul Hijjah, not to cut his…?", "bn": "উম্মে সালামা (রা.)-এর হাদিসে কুরবানির ইচ্ছাকারীকে জিলহজের শুরু থেকে কী না কাটতে বলা হয়েছে?"}', '{"en": "\"When the ten (days) begin and one of you wants to sacrifice, let him not take anything from his hair or skin (nails).\"", "bn": "\"যখন (জিলহজের) দশক শুরু হয় এবং তোমাদের কেউ কুরবানি করতে চায়, সে যেন তার চুল ও নখ থেকে কিছু না কাটে।\""}', 'Sahih Muslim 1977', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1af3334e-d7a3-5b31-b971-c2b6de9779e9', '9821c863-c671-5e7b-993d-32df8dd39753', '{"en": "Hair and nails", "bn": "চুল ও নখ"}', true, 1), ('a7a4c75d-fb87-5ae7-a9ac-57a33b7dea83', '9821c863-c671-5e7b-993d-32df8dd39753', '{"en": "Bread", "bn": "রুটি"}', false, 2), ('a7aceaa0-a23b-5d5b-9a0c-ad9e0e90cd66', '9821c863-c671-5e7b-993d-32df8dd39753', '{"en": "Trees", "bn": "গাছ"}', false, 3), ('4cbada43-9393-5098-9cef-ae4204175b4e', '9821c863-c671-5e7b-993d-32df8dd39753', '{"en": "Clothes", "bn": "কাপড়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('86f0c931-8ca3-5ab5-9f90-507b1cd67e7a', '56b7da1d-e7b5-5749-adba-95c335c2aac0', '{"en": "How did the Prophet ﷺ teach us to slaughter?", "bn": "নবী ﷺ কীভাবে জবাই করতে শিখিয়েছেন?"}', '{"en": "\"Allah has prescribed excellence in everything… let one of you sharpen his blade and spare his animal suffering.\"", "bn": "\"আল্লাহ সবকিছুতে উত্তমতা ফরজ করেছেন… তোমরা ছুরি ধারালো করো এবং পশুকে আরাম দাও।\""}', 'Sahih Muslim 1955', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('2194704b-1b95-5b00-9349-9eb028fee2e4', '86f0c931-8ca3-5ab5-9f90-507b1cd67e7a', '{"en": "Quickly, with any stone", "bn": "যেকোনো পাথর দিয়ে দ্রুত"}', false, 1), ('eccab0ee-0d10-5868-9dd8-b72f0b504a35', '86f0c931-8ca3-5ab5-9f90-507b1cd67e7a', '{"en": "In front of the other animals", "bn": "অন্য পশুর সামনে"}', false, 2), ('907ca8ad-84e2-578e-84ee-42a782632fd5', '86f0c931-8ca3-5ab5-9f90-507b1cd67e7a', '{"en": "With a sharp blade, sparing the animal pain", "bn": "ধারালো ছুরি দিয়ে, পশুকে কষ্ট না দিয়ে"}', true, 3), ('305c7cde-c756-5c40-80d0-2d382146922e', '86f0c931-8ca3-5ab5-9f90-507b1cd67e7a', '{"en": "After making it run", "bn": "দৌড় করানোর পর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('307014df-af8b-5990-9380-47d5590153b7', '{"en": "Janazah & death", "bn": "জানাযা ও মৃত্যু"}', 'fiqh', 'medium', NULL, 10, 'in_review', 110) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('15fed128-8b48-5d6b-8cd6-9a252b0bd6f8', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "How many takbirs are in the janazah prayer?", "bn": "জানাযার নামাজে কয়টি তাকবির?"}', '{"en": "He ﷺ prayed over the Negus (an-Najashi) and said four takbirs.", "bn": "নবী ﷺ নাজাশির জানাযা পড়েছেন এবং চারটি তাকবির দিয়েছেন।"}', 'Sahih al-Bukhari 1333', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c781c046-f56d-5601-96b1-1bfd17c0e23b', '15fed128-8b48-5d6b-8cd6-9a252b0bd6f8', '{"en": "2", "bn": "২"}', false, 1), ('1af17587-3b83-58a5-ac2b-579bd3b9f3b4', '15fed128-8b48-5d6b-8cd6-9a252b0bd6f8', '{"en": "4", "bn": "৪"}', true, 2), ('f1b01316-ace0-5f43-91cb-5b4a6c49bc7b', '15fed128-8b48-5d6b-8cd6-9a252b0bd6f8', '{"en": "6", "bn": "৬"}', false, 3), ('d378fcf3-65f0-5fd8-8839-562c085b5156', '15fed128-8b48-5d6b-8cd6-9a252b0bd6f8', '{"en": "7", "bn": "৭"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ea5f3aec-c950-511b-be15-c7840a24a938', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "What is the heart of the janazah prayer’s duas?", "bn": "জানাযার নামাজের দোয়ার মূল বিষয় কী?"}', '{"en": "\"When you pray over the deceased, make your dua for him sincere.\"", "bn": "\"যখন তোমরা মৃতের জানাযা পড়বে, তখন তার জন্য আন্তরিকভাবে দোয়া করবে।\""}', 'Sunan Abi Dawud 3199', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('75e96e40-5bff-5b63-813c-d236f33bda63', 'ea5f3aec-c950-511b-be15-c7840a24a938', '{"en": "Asking for rain", "bn": "বৃষ্টি চাওয়া"}', false, 1), ('9270eaeb-290c-5cb9-9516-d1d201f1b344', 'ea5f3aec-c950-511b-be15-c7840a24a938', '{"en": "Praising the dead person’s wealth", "bn": "মৃতের সম্পদের প্রশংসা"}', false, 2), ('74dd2aa6-b3c2-5774-83ba-c8b38c72a3d9', 'ea5f3aec-c950-511b-be15-c7840a24a938', '{"en": "Asking Allah to forgive the deceased", "bn": "মৃতের জন্য আল্লাহর কাছে ক্ষমা চাওয়া"}', true, 3), ('7cde8ef0-193f-55ed-859c-267386a24b73', 'ea5f3aec-c950-511b-be15-c7840a24a938', '{"en": "Reciting poetry", "bn": "কবিতা পাঠ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b661e42b-fc59-593b-8465-0ab007bb6dbd', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "The janazah prayer is…?", "bn": "জানাযার নামাজ কোন ধরনের বিধান?"}', '{"en": "If some of the community perform it, the duty is lifted from the rest; if none do, all are sinful.", "bn": "সমাজের কিছু মানুষ আদায় করলে বাকিরা দায়মুক্ত হয়; কেউ না করলে সবাই গুনাহগার।"}', 'Sahih al-Bukhari 2298', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ca395f3d-9675-53d0-ac35-77879752ecfd', 'b661e42b-fc59-593b-8465-0ab007bb6dbd', '{"en": "Fard kifayah: a duty on the community", "bn": "ফরজে কিফায়া: সমাজের ওপর দায়িত্ব"}', true, 1), ('38981a79-a098-5f3b-9f21-107eef54968d', 'b661e42b-fc59-593b-8465-0ab007bb6dbd', '{"en": "Not allowed", "bn": "জায়েজ নয়"}', false, 2), ('3cacedeb-a55f-5ec6-8199-01f4a3f5193c', 'b661e42b-fc59-593b-8465-0ab007bb6dbd', '{"en": "Only for scholars", "bn": "শুধু আলেমদের জন্য"}', false, 3), ('8ef0b1db-68bc-58e5-8b79-218d42435728', 'b661e42b-fc59-593b-8465-0ab007bb6dbd', '{"en": "Only for family", "bn": "শুধু পরিবারের জন্য"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('40c254e1-bbde-5e83-ba00-d0d01398274a', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "Whoever attends a funeral until the prayer gets one qirat; and whoever stays until the burial gets…?", "bn": "যে জানাযার নামাজ পর্যন্ত থাকে সে এক কিরাত পায়; আর যে দাফন পর্যন্ত থাকে সে পায়…?"}', '{"en": "\"…two qirats.\" He was asked what two qirats are: \"Like two great mountains.\"", "bn": "\"…দুই কিরাত।\" জিজ্ঞেস করা হলো দুই কিরাত কী? বললেন: \"দুটি বিশাল পাহাড়ের মতো।\""}', 'Sahih al-Bukhari 1325', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('23702945-5bdf-50c9-80bb-0dd348775f18', '40c254e1-bbde-5e83-ba00-d0d01398274a', '{"en": "Nothing more", "bn": "আর কিছু না"}', false, 1), ('7fb88fd5-b7b9-508c-bbf3-dba53267e654', '40c254e1-bbde-5e83-ba00-d0d01398274a', '{"en": "Ten qirats", "bn": "দশ কিরাত"}', false, 2), ('c81ff5d8-ab1a-528d-a780-cb810f8023ed', '40c254e1-bbde-5e83-ba00-d0d01398274a', '{"en": "Half a qirat", "bn": "অর্ধেক কিরাত"}', false, 3), ('cdd907e1-b11e-54e5-b68f-e122130bbe12', '40c254e1-bbde-5e83-ba00-d0d01398274a', '{"en": "Two qirats", "bn": "দুই কিরাত"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('95aa18d3-4a12-502e-921b-bc246f3ed18c', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "What did the Prophet ﷺ tell us to do with the funeral?", "bn": "জানাযা নিয়ে নবী ﷺ কী করতে বলেছেন?"}', '{"en": "\"Hurry with the funeral: if it was righteous, you bring it to good; if not, you put an evil off your necks.\"", "bn": "\"জানাযা দ্রুত করো: নেককার হলে তাকে কল্যাণের দিকে এগিয়ে দিচ্ছ; অন্যথায় নিজেদের কাঁধ থেকে একটি মন্দ নামিয়ে দিচ্ছ।\""}', 'Sahih al-Bukhari 1315', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fb0b6766-fc92-5406-b9c4-c34e2374b92b', '95aa18d3-4a12-502e-921b-bc246f3ed18c', '{"en": "Hurry with it", "bn": "দ্রুত সম্পন্ন করতে"}', true, 1), ('d8ecc335-60cb-5816-9bbc-825cd5b50cdc', '95aa18d3-4a12-502e-921b-bc246f3ed18c', '{"en": "Delay it for days", "bn": "কয়েক দিন দেরি করতে"}', false, 2), ('24c60240-277c-522e-8124-aaee8cdec4d3', '95aa18d3-4a12-502e-921b-bc246f3ed18c', '{"en": "Hold it at night only", "bn": "শুধু রাতে করতে"}', false, 3), ('ea3acbcb-5de3-527b-a8bf-741a53aa5334', '95aa18d3-4a12-502e-921b-bc246f3ed18c', '{"en": "Hold a feast first", "bn": "আগে ভোজের আয়োজন করতে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9dc35745-af39-5756-8dfd-110ad4bae1a3', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "In how many white cloths was the Prophet ﷺ shrouded?", "bn": "নবী ﷺ-কে কয়টি সাদা কাপড়ে কাফন দেওয়া হয়েছিল?"}', '{"en": "‘A’ishah (RA): \"He was shrouded in three white Yemeni cloths, with no shirt or turban among them.\"", "bn": "আয়েশা (রা.): \"তাঁকে তিনটি সাদা ইয়েমেনি কাপড়ে কাফন দেওয়া হয়, তাতে জামা বা পাগড়ি ছিল না।\""}', 'Sahih al-Bukhari 1264', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9a4fe8ac-d071-5e5f-8062-430f08d32ffb', '9dc35745-af39-5756-8dfd-110ad4bae1a3', '{"en": "1", "bn": "১"}', false, 1), ('cb9d0aa7-3813-5ad2-9e69-1dd8ebd8b868', '9dc35745-af39-5756-8dfd-110ad4bae1a3', '{"en": "2", "bn": "২"}', false, 2), ('ebef67d1-78ff-557a-93bf-f2c410e2a6ad', '9dc35745-af39-5756-8dfd-110ad4bae1a3', '{"en": "3", "bn": "৩"}', true, 3), ('5c89c420-1d59-56a8-a8ca-dd329f984306', '9dc35745-af39-5756-8dfd-110ad4bae1a3', '{"en": "5", "bn": "৫"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0f5915e9-8cce-58e8-9162-a38caabffeb6', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "In the grave, the deceased is laid facing…?", "bn": "কবরে মৃতকে কোন দিকে মুখ করে শোয়ানো হয়?"}', '{"en": "Laying the deceased on the right side facing the qiblah is the unbroken practice of the Muslims.", "bn": "মৃতকে ডান কাতে কিবলামুখী করে শোয়ানো মুসলিমদের অবিচ্ছিন্ন আমল।"}', 'Ijma‘ (agreed practice); Sunan Abi Dawud 2875', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('83fb0998-7b77-581d-95ea-519df2f95ee1', '0f5915e9-8cce-58e8-9162-a38caabffeb6', '{"en": "The east", "bn": "পূর্ব দিকে"}', false, 1), ('a51e9b96-47ac-5aaf-953b-782eab45833a', '0f5915e9-8cce-58e8-9162-a38caabffeb6', '{"en": "The qiblah", "bn": "কিবলার দিকে"}', true, 2), ('6e706f05-b068-5ca6-ba09-0ad941c1984c', '0f5915e9-8cce-58e8-9162-a38caabffeb6', '{"en": "The sky", "bn": "আকাশের দিকে"}', false, 3), ('a81a3a8b-5275-5159-a0b8-dc5d20206737', '0f5915e9-8cce-58e8-9162-a38caabffeb6', '{"en": "Any direction", "bn": "যেকোনো দিকে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7fd26754-4ead-52a0-b55d-53b09b236c0e', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "A widow who is not pregnant waits (‘iddah) after her husband’s death for…?", "bn": "গর্ভবতী নন এমন বিধবার স্বামীর মৃত্যুর পর ইদ্দত কত দিন?"}', '{"en": "\"…they shall wait by themselves for four months and ten (days).\"", "bn": "\"…তারা নিজেদের চার মাস দশ দিন অপেক্ষায় রাখবে।\""}', 'Quran 2:234', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('2a0602e1-8885-5ab5-bff8-7116e9feb47d', '7fd26754-4ead-52a0-b55d-53b09b236c0e', '{"en": "Three days", "bn": "তিন দিন"}', false, 1), ('e9998b9c-8e13-5022-90ef-ffe78e4be4d3', '7fd26754-4ead-52a0-b55d-53b09b236c0e', '{"en": "One month", "bn": "এক মাস"}', false, 2), ('89b9d78f-8bb6-5602-a179-51da4dfd2e25', '7fd26754-4ead-52a0-b55d-53b09b236c0e', '{"en": "One year", "bn": "এক বছর"}', false, 3), ('5da2057e-907d-5215-94bc-7d91c9189351', '7fd26754-4ead-52a0-b55d-53b09b236c0e', '{"en": "Four months and ten days", "bn": "চার মাস দশ দিন"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e1410168-f16c-52c5-af90-daadeb574cd0', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "For anyone other than a husband, mourning is allowed for up to…?", "bn": "স্বামী ছাড়া অন্য কারো জন্য শোক পালন সর্বোচ্চ কত দিন?"}', '{"en": "\"It is not lawful for a woman who believes in Allah and the Last Day to mourn more than three days, except for a husband.\"", "bn": "\"আল্লাহ ও শেষ দিবসে বিশ্বাসী নারীর জন্য স্বামী ছাড়া অন্য কারো জন্য তিন দিনের বেশি শোক পালন বৈধ নয়।\""}', 'Sahih al-Bukhari 1280', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('593a55b3-19ec-5fc0-ba99-6f1521ab4382', 'e1410168-f16c-52c5-af90-daadeb574cd0', '{"en": "Three days", "bn": "তিন দিন"}', true, 1), ('e56b2987-2e68-5488-8005-fbbec87d6cc9', 'e1410168-f16c-52c5-af90-daadeb574cd0', '{"en": "Forty days", "bn": "চল্লিশ দিন"}', false, 2), ('e0c710f5-6ab9-58e5-9905-7a0633496b4e', 'e1410168-f16c-52c5-af90-daadeb574cd0', '{"en": "One year", "bn": "এক বছর"}', false, 3), ('9079c908-dd92-5e96-a123-4b0db9ab821b', 'e1410168-f16c-52c5-af90-daadeb574cd0', '{"en": "Seven days", "bn": "সাত দিন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('03152e58-b939-52b5-baee-d2f8657f5abb', '307014df-af8b-5990-9380-47d5590153b7', '{"en": "Why did the Prophet ﷺ encourage visiting graves?", "bn": "নবী ﷺ কবর জিয়ারতে উৎসাহ দিয়েছেন কেন?"}', '{"en": "\"Visit the graves, for they remind you of death.\"", "bn": "\"তোমরা কবর জিয়ারত করো, কারণ তা মৃত্যুর কথা মনে করিয়ে দেয়।\""}', 'Sahih Muslim 976', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0bc8327d-717f-5882-8591-aa2809cf5636', '03152e58-b939-52b5-baee-d2f8657f5abb', '{"en": "To ask the dead for help", "bn": "মৃতদের কাছে সাহায্য চাইতে"}', false, 1), ('4703b581-60f8-5944-a7cd-d955ec787cc4', '03152e58-b939-52b5-baee-d2f8657f5abb', '{"en": "To hold festivals", "bn": "উৎসব করতে"}', false, 2), ('43b0d187-e2c6-53fc-aae6-928347bae01c', '03152e58-b939-52b5-baee-d2f8657f5abb', '{"en": "Because they remind us of death", "bn": "কারণ এটি মৃত্যুর কথা মনে করিয়ে দেয়"}', true, 3), ('9de62400-b9f3-5952-87e6-e3ef7762939e', '03152e58-b939-52b5-baee-d2f8657f5abb', '{"en": "To build on them", "bn": "কবরের ওপর স্থাপনা বানাতে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "More names of Allah", "bn": "আল্লাহর আরও সুন্দর নাম"}', 'general', 'medium', NULL, 10, 'in_review', 111) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('39ac3dce-b368-5cc3-a328-619b0c608a7f', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "What does \"Al-Quddus\" mean?", "bn": "\"আল-কুদ্দুস\" অর্থ কী?"}', '{"en": "\"He is Allah… the King, the Most Holy (al-Quddus)…\"", "bn": "\"তিনিই আল্লাহ… অধিপতি, মহাপবিত্র (আল-কুদ্দুস)…\""}', 'Quran 59:23', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('05264125-21b6-5304-8886-4e317645542c', '39ac3dce-b368-5cc3-a328-619b0c608a7f', '{"en": "The Most Holy, free of every fault", "bn": "মহাপবিত্র, সব ত্রুটিমুক্ত"}', true, 1), ('45147f07-21e8-50aa-b4e7-8e3514945588', '39ac3dce-b368-5cc3-a328-619b0c608a7f', '{"en": "The Provider", "bn": "রিজিকদাতা"}', false, 2), ('d51c3a64-b3cd-5f06-97d4-d787bbb0d7b5', '39ac3dce-b368-5cc3-a328-619b0c608a7f', '{"en": "The Creator", "bn": "সৃষ্টিকর্তা"}', false, 3), ('9e515e33-7caf-5e7d-b96a-f49895fa792e', '39ac3dce-b368-5cc3-a328-619b0c608a7f', '{"en": "The Patient", "bn": "ধৈর্যশীল"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('df0d9222-fed9-50ff-8309-43b44f5c17f7', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "What does \"As-Sami‘\" mean?", "bn": "\"আস-সামি\" অর্থ কী?"}', '{"en": "\"There is nothing like Him, and He is the All-Hearing, the All-Seeing.\"", "bn": "\"কোনো কিছুই তাঁর সদৃশ নয়, তিনি সর্বশ্রোতা, সর্বদ্রষ্টা।\""}', 'Quran 42:11', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a551d699-41c7-5e1e-9e12-9c743349510d', 'df0d9222-fed9-50ff-8309-43b44f5c17f7', '{"en": "The All-Seeing", "bn": "সর্বদ্রষ্টা"}', false, 1), ('4b4a8f5d-6205-5adc-b902-5c077ebba7b2', 'df0d9222-fed9-50ff-8309-43b44f5c17f7', '{"en": "The All-Hearing", "bn": "সর্বশ্রোতা"}', true, 2), ('fdbe2843-ce77-5dfe-b494-d666598d2716', 'df0d9222-fed9-50ff-8309-43b44f5c17f7', '{"en": "The Wise", "bn": "প্রজ্ঞাময়"}', false, 3), ('c29b3867-91f1-5692-bf15-bc6306d13754', 'df0d9222-fed9-50ff-8309-43b44f5c17f7', '{"en": "The First", "bn": "আদি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8394dc89-81a2-5c73-aba3-ae07731dc33f', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "Which name means \"The All-Seeing\"?", "bn": "কোন নামের অর্থ \"সর্বদ্রষ্টা\"?"}', '{"en": "Al-Basir sees everything, the open and the hidden.", "bn": "আল-বাসির প্রকাশ্য-গোপন সবকিছু দেখেন।"}', 'Quran 42:11', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('97a3c87a-f473-5624-8512-a988288ecfdf', '8394dc89-81a2-5c73-aba3-ae07731dc33f', '{"en": "Al-Hayy", "bn": "আল-হাইয়ু"}', false, 1), ('5023e853-3bff-5104-9718-4eb69b1c881c', '8394dc89-81a2-5c73-aba3-ae07731dc33f', '{"en": "Al-Wahhab", "bn": "আল-ওয়াহহাব"}', false, 2), ('e91804a5-d7c8-5631-a4bd-360cd710821f', '8394dc89-81a2-5c73-aba3-ae07731dc33f', '{"en": "Al-Basir", "bn": "আল-বাসির"}', true, 3), ('fb3dbe45-9df1-5fa5-9771-bb2ab2c67b4e', '8394dc89-81a2-5c73-aba3-ae07731dc33f', '{"en": "Al-Latif", "bn": "আল-লাতিফ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7d125da8-ab90-5dd1-8ae1-c47c3069ef24', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "What does \"Al-Hayy\" mean?", "bn": "\"আল-হাইয়ু\" অর্থ কী?"}', '{"en": "\"Allah — there is no god but He, the Ever-Living (al-Hayy), the Sustainer of all (al-Qayyum).\" (Ayat al-Kursi)", "bn": "\"আল্লাহ — তিনি ছাড়া কোনো ইলাহ নেই, তিনি চিরঞ্জীব (আল-হাইয়ু), সবকিছুর ধারক (আল-কাইয়ুম)।\" (আয়াতুল কুরসি)"}', 'Quran 2:255', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('45831003-704c-57be-baba-28536a0c4f61', '7d125da8-ab90-5dd1-8ae1-c47c3069ef24', '{"en": "The Most Generous", "bn": "মহাদানশীল"}', false, 1), ('f411108e-9916-544e-af5e-934be1cc4834', '7d125da8-ab90-5dd1-8ae1-c47c3069ef24', '{"en": "The Judge", "bn": "বিচারক"}', false, 2), ('f2a1fa40-a997-516a-afb9-700e46a8009d', '7d125da8-ab90-5dd1-8ae1-c47c3069ef24', '{"en": "The Light", "bn": "আলো"}', false, 3), ('18b9b510-5950-5919-8609-5d5966d2a9b3', '7d125da8-ab90-5dd1-8ae1-c47c3069ef24', '{"en": "The Ever-Living", "bn": "চিরঞ্জীব"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('74d0b144-6862-5cbf-90a1-2aeedb8d1e6c', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "What does \"Al-Qayyum\" mean?", "bn": "\"আল-কাইয়ুম\" অর্থ কী?"}', '{"en": "Al-Qayyum stands by Himself and keeps all creation in existence.", "bn": "আল-কাইয়ুম নিজে নিজেই প্রতিষ্ঠিত এবং সমগ্র সৃষ্টিকে টিকিয়ে রাখেন।"}', 'Quran 2:255', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e57f1c14-208f-5ca3-a38f-d23b1367446b', '74d0b144-6862-5cbf-90a1-2aeedb8d1e6c', '{"en": "The Self-Subsisting, who sustains everything", "bn": "চিরস্থায়ী, যিনি সবকিছু ধরে রেখেছেন"}', true, 1), ('642fda00-660b-5a41-a89f-95a6dfa35175', '74d0b144-6862-5cbf-90a1-2aeedb8d1e6c', '{"en": "The Last", "bn": "অন্ত"}', false, 2), ('e1352d0e-07da-5bdd-ac1f-2c37dd743b99', '74d0b144-6862-5cbf-90a1-2aeedb8d1e6c', '{"en": "The Forgiver", "bn": "ক্ষমাকারী"}', false, 3), ('cc03043b-57d9-519a-942b-f74385a51c0a', '74d0b144-6862-5cbf-90a1-2aeedb8d1e6c', '{"en": "The Opener", "bn": "উন্মোচনকারী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('305a0f91-16f5-5c92-9685-c4c84c32868a', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "Which name means \"The One who accepts repentance, again and again\"?", "bn": "কোন নামের অর্থ \"বারবার তওবা কবুলকারী\"?"}', '{"en": "Adam received words from his Lord and He accepted his repentance: \"He is the Accepter of repentance (at-Tawwab), the Most Merciful.\"", "bn": "আদম (আ.) তাঁর রবের কাছ থেকে কিছু বাণী পেলেন, আর আল্লাহ তাঁর তওবা কবুল করলেন: \"তিনি তওবা কবুলকারী (আত-তাওয়াব), পরম দয়ালু।\""}', 'Quran 2:37', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3d6fb1ed-9481-5e08-ac38-53737ce3e780', '305a0f91-16f5-5c92-9685-c4c84c32868a', '{"en": "Al-Jabbar", "bn": "আল-জাব্বার"}', false, 1), ('03b49ccb-e2f3-5248-9c27-73d48123bdc5', '305a0f91-16f5-5c92-9685-c4c84c32868a', '{"en": "At-Tawwab", "bn": "আত-তাওয়াব"}', true, 2), ('210ba9af-0b6a-5e21-a1f2-f117056cff70', '305a0f91-16f5-5c92-9685-c4c84c32868a', '{"en": "Al-Malik", "bn": "আল-মালিক"}', false, 3), ('522a9389-3056-5d90-a6e1-aad87f041acc', '305a0f91-16f5-5c92-9685-c4c84c32868a', '{"en": "Al-Khaliq", "bn": "আল-খালিক"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e6cf6752-5d6a-5dd6-82db-01fc8ce23733', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "What does \"Al-Wahhab\" mean?", "bn": "\"আল-ওয়াহহাব\" অর্থ কী?"}', '{"en": "\"…and grant us mercy from Yourself; You are the Bestower (al-Wahhab).\"", "bn": "\"…আর আপনার পক্ষ থেকে আমাদের রহমত দান করুন; নিশ্চয় আপনি মহাদাতা (আল-ওয়াহহাব)।\""}', 'Quran 3:8', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('2d902a5f-3553-52ef-9d70-93dc96c88fa7', 'e6cf6752-5d6a-5dd6-82db-01fc8ce23733', '{"en": "The Avenger", "bn": "প্রতিশোধ গ্রহণকারী"}', false, 1), ('8dd26f3e-0f53-5d25-bd73-a5c8a66728dd', 'e6cf6752-5d6a-5dd6-82db-01fc8ce23733', '{"en": "The Hidden", "bn": "গোপন"}', false, 2), ('49206913-1f60-5253-b6f1-a064536d6c15', 'e6cf6752-5d6a-5dd6-82db-01fc8ce23733', '{"en": "The Bestower, who gives freely", "bn": "মহাদাতা, যিনি অকাতরে দান করেন"}', true, 3), ('379b25de-78cd-55dc-9ac7-4751fe0d9232', 'e6cf6752-5d6a-5dd6-82db-01fc8ce23733', '{"en": "The Witness", "bn": "সাক্ষী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9a716f2b-8316-5333-abf4-9aac1ad078be', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "Which name means \"The Opener, the Judge who decides with truth\"?", "bn": "কোন নামের অর্থ \"উন্মোচনকারী, যিনি সত্যের সঙ্গে ফয়সালা করেন\"?"}', '{"en": "\"…then He will judge between us in truth. He is the Judge (al-Fattah), the All-Knowing.\"", "bn": "\"…তারপর তিনি আমাদের মধ্যে সত্যের সঙ্গে ফয়সালা করবেন। তিনিই শ্রেষ্ঠ ফয়সালাকারী (আল-ফাত্তাহ), সর্বজ্ঞ।\""}', 'Quran 34:26', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('16a287b2-b61d-5d46-9d5b-c1417860417b', '9a716f2b-8316-5333-abf4-9aac1ad078be', '{"en": "Al-Fattah", "bn": "আল-ফাত্তাহ"}', true, 1), ('25c09e30-0cfc-5192-b17b-8d576b480944', '9a716f2b-8316-5333-abf4-9aac1ad078be', '{"en": "Al-Mujib", "bn": "আল-মুজিব"}', false, 2), ('f1ad477b-88b2-501e-bae4-47ae450f7066', '9a716f2b-8316-5333-abf4-9aac1ad078be', '{"en": "As-Salam", "bn": "আস-সালাম"}', false, 3), ('f3f26646-bb56-5f68-84e8-abcb35d87ccf', '9a716f2b-8316-5333-abf4-9aac1ad078be', '{"en": "Al-Wadud", "bn": "আল-ওয়াদুদ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4b3adc90-7d70-554e-b745-a799b89df656', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "What does \"Al-Latif\" mean?", "bn": "\"আল-লাতিফ\" অর্থ কী?"}', '{"en": "\"Does He who created not know? He is the Subtle (al-Latif), the Aware.\"", "bn": "\"যিনি সৃষ্টি করেছেন তিনি কি জানেন না? তিনি সূক্ষ্মদর্শী (আল-লাতিফ), সম্যক অবগত।\""}', 'Quran 67:14', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('746bd85c-047f-5f8c-87f9-965d16f8364c', '4b3adc90-7d70-554e-b745-a799b89df656', '{"en": "The Mighty", "bn": "মহাপরাক্রমশালী"}', false, 1), ('9816a4d1-face-53cb-9598-0ee4262347bd', '4b3adc90-7d70-554e-b745-a799b89df656', '{"en": "The Owner of the Kingdom", "bn": "সার্বভৌমত্বের মালিক"}', false, 2), ('00ae64aa-69e8-5839-bea0-0387afbc4df7', '4b3adc90-7d70-554e-b745-a799b89df656', '{"en": "The Great", "bn": "মহান"}', false, 3), ('73cd9c33-e974-56e0-b8a7-15fff0c59463', '4b3adc90-7d70-554e-b745-a799b89df656', '{"en": "The Subtle, the Gentle and Kind", "bn": "সূক্ষ্মদর্শী, কোমল ও দয়ালু"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7f9bc5eb-d187-59b7-901f-595d7cfac77b', 'c00dc1a4-a5ea-5f97-9bdf-7e1889828a0b', '{"en": "Which name means \"The One who answers prayers\"?", "bn": "কোন নামের অর্থ \"দোয়ায় সাড়াদানকারী\"?"}', '{"en": "\"…Indeed, my Lord is near and responsive (Mujib).\"", "bn": "\"…নিশ্চয় আমার রব নিকটে, সাড়াদানকারী (মুজিব)।\""}', 'Quran 11:61', 10) ON CONFLICT (id) DO NOTHING;
