INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "Names of Allah in the Quran", "bn": "কুরআনে আল্লাহর নাম"}', 'general', 'hard', 600, 10, 'in_review', 112) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('73ea67ce-4938-5db9-94a6-75e269bdc759', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "\"He is the First and the Last, the Manifest and the Hidden\" is in which surah?", "bn": "\"তিনিই আদি ও অন্ত, প্রকাশ্য ও গোপন\" — কোন সূরায়?"}', '{"en": "Al-Awwal, al-Akhir, az-Zahir and al-Batin come together in al-Hadid 57:3.", "bn": "আল-আউয়াল, আল-আখির, আজ-জাহির ও আল-বাতিন একসঙ্গে এসেছে সূরা হাদিদের ৫৭:৩ আয়াতে।"}', 'Quran 57:3', 1) ON CONFLICT (id) DO NOTHING;
