INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('00bd9c68-5b45-538b-b610-ce62a3a4ec97', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "Many names — al-Malik, al-Quddus, as-Salam, al-Mu’min, al-Muhaymin, al-‘Aziz, al-Jabbar… — come together at the end of which surah?", "bn": "আল-মালিক, আল-কুদ্দুস, আস-সালাম, আল-মুমিন, আল-মুহাইমিন, আল-আজিজ, আল-জাব্বার… — অনেক নাম একসঙ্গে কোন সূরার শেষে?"}', '{"en": "The last three ayahs of al-Hashr (59:22–24) gather many of Allah’s names.", "bn": "সূরা হাশরের শেষ তিন আয়াতে (৫৯:২২–২৪) আল্লাহর অনেক নাম একসঙ্গে এসেছে।"}', 'Quran 59:22–24', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d0eb6593-68d4-5534-a0a0-e1b4d5f00dd6', '00bd9c68-5b45-538b-b610-ce62a3a4ec97', '{"en": "Al-Hashr", "bn": "আল-হাশর"}', true, 1), ('da537fc4-34f0-576b-a66c-db646cb302c5', '00bd9c68-5b45-538b-b610-ce62a3a4ec97', '{"en": "Al-Baqarah", "bn": "আল-বাকারা"}', false, 2), ('4cc6a593-2187-5b07-8a5c-ac92cb6e4757', '00bd9c68-5b45-538b-b610-ce62a3a4ec97', '{"en": "Al-Fatiha", "bn": "আল-ফাতিহা"}', false, 3), ('3b187147-3266-54d2-8b7e-4d6066e63fc2', '00bd9c68-5b45-538b-b610-ce62a3a4ec97', '{"en": "An-Nas", "bn": "আন-নাস"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b9e4e776-b5c5-5788-913e-26b4a3b6e2fc', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "What does \"Al-Musawwir\" mean?", "bn": "\"আল-মুসাওয়ির\" অর্থ কী?"}', '{"en": "\"He is Allah, the Creator (al-Khaliq), the Maker (al-Bari’), the Fashioner (al-Musawwir).\"", "bn": "\"তিনিই আল্লাহ, সৃষ্টিকর্তা (আল-খালিক), উদ্ভাবক (আল-বারি), আকৃতিদাতা (আল-মুসাওয়ির)।\""}', 'Quran 59:24', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7f09b1e4-23c4-5883-9da3-5b49c4c36992', 'b9e4e776-b5c5-5788-913e-26b4a3b6e2fc', '{"en": "The Fashioner, who gives each thing its form", "bn": "আকৃতিদাতা, যিনি প্রত্যেককে রূপ দেন"}', true, 1), ('5d9a2397-132c-5f5b-bb9a-d6bb325271c9', 'b9e4e776-b5c5-5788-913e-26b4a3b6e2fc', '{"en": "The Watcher", "bn": "পর্যবেক্ষক"}', false, 2), ('8040db24-3129-5dcf-8405-c65264bcc65c', 'b9e4e776-b5c5-5788-913e-26b4a3b6e2fc', '{"en": "The Generous", "bn": "দানশীল"}', false, 3), ('d7a8b477-8021-52e5-9200-d75662424c03', 'b9e4e776-b5c5-5788-913e-26b4a3b6e2fc', '{"en": "The Avenger", "bn": "প্রতিশোধ গ্রহণকারী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('07f8d16f-b2d6-5979-9d10-3e96acf62479', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "What does \"Al-Muhaymin\" mean?", "bn": "\"আল-মুহাইমিন\" অর্থ কী?"}', '{"en": "Al-Muhaymin watches over and preserves all things.", "bn": "আল-মুহাইমিন সবকিছুর ওপর দৃষ্টি রাখেন ও রক্ষা করেন।"}', 'Quran 59:23', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('986e2617-70ee-5b40-b380-4c21fd3f7ba2', '07f8d16f-b2d6-5979-9d10-3e96acf62479', '{"en": "The Last", "bn": "অন্ত"}', false, 1), ('f74608f6-9d7c-5c86-a7bf-9a615c345904', '07f8d16f-b2d6-5979-9d10-3e96acf62479', '{"en": "The Guardian who watches over all", "bn": "রক্ষক, যিনি সবকিছুর তত্ত্বাবধান করেন"}', true, 2), ('00c8512f-ebca-5547-b61b-a9bbe58a5c0a', '07f8d16f-b2d6-5979-9d10-3e96acf62479', '{"en": "The Loving", "bn": "প্রেমময়"}', false, 3), ('d21e7ef7-6a7b-525d-a20f-0c9d8f762feb', '07f8d16f-b2d6-5979-9d10-3e96acf62479', '{"en": "The Light", "bn": "আলো"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2999b4f6-d36e-5f55-884d-148441ef76eb', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "The Laylat al-Qadr dua \"Allahumma innaka ‘afuwwun tuhibbul-‘afwa fa‘fu ‘anni\" calls Allah…?", "bn": "লাইলাতুল কদরের দোয়া \"আল্লাহুম্মা ইন্নাকা আফুউন তুহিব্বুল আফওয়া ফা‘ফু আন্নি\"-তে আল্লাহকে কী বলা হয়েছে?"}', '{"en": "\"O Allah, You are the Pardoner (‘Afuww), You love to pardon, so pardon me.\"", "bn": "\"হে আল্লাহ, আপনি ক্ষমাশীল (আফুউ), ক্ষমা করতে ভালোবাসেন, তাই আমাকে ক্ষমা করুন।\""}', 'Jami‘ at-Tirmidhi 3513', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b6499404-9e8a-5a72-9794-788db6ba15a5', '2999b4f6-d36e-5f55-884d-148441ef76eb', '{"en": "Al-‘Aziz, the Mighty", "bn": "আল-আজিজ, মহাপরাক্রমশালী"}', false, 1), ('533ec1b7-c7a5-5108-83d8-484729603c25', '2999b4f6-d36e-5f55-884d-148441ef76eb', '{"en": "Al-Ghani, the Rich", "bn": "আল-গনি, অমুখাপেক্ষী"}', false, 2), ('32e03bb8-da79-597c-b7e7-178eaa268d33', '2999b4f6-d36e-5f55-884d-148441ef76eb', '{"en": "Al-Hakim, the Wise", "bn": "আল-হাকিম, প্রজ্ঞাময়"}', false, 3), ('2ebefad2-73db-5679-a37c-b6aa97e0dd50', '2999b4f6-d36e-5f55-884d-148441ef76eb', '{"en": "Al-‘Afuww, the Pardoner who erases sins", "bn": "আল-আফুউ, গুনাহ মুছে দেওয়া ক্ষমাকারী"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e5139f73-9670-5237-b7c7-67cc05c237b2', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "In \"Hasbunallahu wa ni‘mal-Wakil\", what does al-Wakil mean?", "bn": "\"হাসবুনাল্লাহু ওয়া নি‘মাল ওয়াকিল\"-এ আল-ওয়াকিল অর্থ কী?"}', '{"en": "\"Allah is sufficient for us, and He is the best Disposer of affairs (al-Wakil).\"", "bn": "\"আল্লাহই আমাদের জন্য যথেষ্ট, আর তিনি কতই না উত্তম কর্মবিধায়ক (আল-ওয়াকিল)।\""}', 'Quran 3:173', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('26067f88-aaf4-5a19-bd3f-adadd70f7e0c', 'e5139f73-9670-5237-b7c7-67cc05c237b2', '{"en": "The Witness", "bn": "সাক্ষী"}', false, 1), ('ea9cafde-7fb8-5718-9dd3-dcff63b05d6d', 'e5139f73-9670-5237-b7c7-67cc05c237b2', '{"en": "The King", "bn": "বাদশাহ"}', false, 2), ('ccbfbd3e-8ecb-51fa-a037-7255f586e155', 'e5139f73-9670-5237-b7c7-67cc05c237b2', '{"en": "The Trustee, on whom we rely for our affairs", "bn": "কর্মবিধায়ক, যাঁর ওপর আমরা ভরসা করি"}', true, 3), ('8980cae3-69b6-5fd4-a131-ff372e0f09b5', 'e5139f73-9670-5237-b7c7-67cc05c237b2', '{"en": "The Creator", "bn": "সৃষ্টিকর্তা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5dfd8a18-6453-538f-a6e9-d8816bc21d75', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "What does \"Ash-Shakur\" mean?", "bn": "\"আশ-শাকুর\" অর্থ কী?"}', '{"en": "\"…that He may give them their rewards in full and increase them from His bounty. He is Forgiving, Appreciative (Shakur).\"", "bn": "\"…যাতে তিনি তাদের পূর্ণ প্রতিদান দেন এবং নিজ অনুগ্রহে আরও বাড়িয়ে দেন। তিনি ক্ষমাশীল, গুণগ্রাহী (শাকুর)।\""}', 'Quran 35:30', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('567a5cd6-aeb0-5164-940d-20145a58d61a', '5dfd8a18-6453-538f-a6e9-d8816bc21d75', '{"en": "The Appreciative, who rewards even small deeds", "bn": "গুণগ্রাহী, যিনি ছোট আমলেরও বড় প্রতিদান দেন"}', true, 1), ('4d77fb67-da10-5692-93df-c5c951ed09a9', '5dfd8a18-6453-538f-a6e9-d8816bc21d75', '{"en": "The Patient", "bn": "ধৈর্যশীল"}', false, 2), ('31538045-d26f-555a-bdd9-b73c7021a46b', '5dfd8a18-6453-538f-a6e9-d8816bc21d75', '{"en": "The Strong", "bn": "শক্তিমান"}', false, 3), ('71d293d8-9e40-5314-b373-8363f5b1bd2a', '5dfd8a18-6453-538f-a6e9-d8816bc21d75', '{"en": "The Near", "bn": "নিকটবর্তী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fda72c98-213a-560f-b800-3b7be60c4f66', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "What does \"Al-Ghani\" mean?", "bn": "\"আল-গনি\" অর্থ কী?"}', '{"en": "\"O people, you are the ones in need of Allah, and Allah is the Free of need (al-Ghani), the Praiseworthy.\"", "bn": "\"হে মানুষ, তোমরাই আল্লাহর মুখাপেক্ষী, আর আল্লাহ অমুখাপেক্ষী (আল-গনি), প্রশংসিত।\""}', 'Quran 35:15', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cbdf01da-1339-5e6c-be9b-6a5357707019', 'fda72c98-213a-560f-b800-3b7be60c4f66', '{"en": "The Hidden", "bn": "গোপন"}', false, 1), ('d3ff4490-ff8c-512e-9ddf-e684d655a008', 'fda72c98-213a-560f-b800-3b7be60c4f66', '{"en": "The Free of all need", "bn": "অমুখাপেক্ষী, কারো মুখাপেক্ষী নন"}', true, 2), ('2f43f61b-931d-5b3e-8e04-9ce91c4a9fa5', 'fda72c98-213a-560f-b800-3b7be60c4f66', '{"en": "The Judge", "bn": "বিচারক"}', false, 3), ('1970dbc0-7cd2-57ac-a7ff-63e1e7ea8d9c', 'fda72c98-213a-560f-b800-3b7be60c4f66', '{"en": "The Light", "bn": "আলো"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9db8f3d3-3ab0-567e-a2a9-7c0ac7ad7a64', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "Which name means \"The Most Kind, full of gentle compassion\"?", "bn": "কোন নামের অর্থ \"অতি স্নেহশীল, কোমল দয়ার অধিকারী\"?"}', '{"en": "\"Indeed Allah is, to the people, Most Kind (Ra’uf) and Most Merciful.\"", "bn": "\"নিশ্চয় আল্লাহ মানুষের প্রতি অতি স্নেহশীল (রাউফ), পরম দয়ালু।\""}', 'Quran 2:143', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('55256c70-5cfa-5825-a6d4-a3a2c3c18182', '9db8f3d3-3ab0-567e-a2a9-7c0ac7ad7a64', '{"en": "Al-Qawi", "bn": "আল-কাওয়ি"}', false, 1), ('481a2166-239a-50e0-837f-aedf543268d5', '9db8f3d3-3ab0-567e-a2a9-7c0ac7ad7a64', '{"en": "Al-Mutakabbir", "bn": "আল-মুতাকাব্বির"}', false, 2), ('a034455b-c99a-5999-a106-2d5f2bf1e43d', '9db8f3d3-3ab0-567e-a2a9-7c0ac7ad7a64', '{"en": "Al-Jabbar", "bn": "আল-জাব্বার"}', false, 3), ('9e0ba927-0afa-5a87-a981-155a67880f32', '9db8f3d3-3ab0-567e-a2a9-7c0ac7ad7a64', '{"en": "Ar-Ra’uf", "bn": "আর-রাউফ"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('32cef401-cf2b-528d-b5c2-be30f1abe287', '68baf2e8-923b-5c1e-90c5-f51cd61537c4', '{"en": "What does \"Al-Hafiz\" mean?", "bn": "\"আল-হাফিজ\" অর্থ কী?"}', '{"en": "\"…Indeed, my Lord is Guardian (Hafiz) over all things.\"", "bn": "\"…নিশ্চয় আমার রব সবকিছুর হেফাজতকারী (হাফিজ)।\""}', 'Quran 11:57', 10) ON CONFLICT (id) DO NOTHING;
