INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('d5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Prophets of Allah — part 4", "bn": "আল্লাহর নবীগণ — পর্ব ৪"}', 'prophets', 'medium', NULL, 10, 'in_review', 113) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e4a10d87-a156-567b-8cca-0e7d19e2caec', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Which prophet is called \"Dhun-Nun\", the companion of the fish?", "bn": "কোন নবীকে \"যুন-নুন\" বা মাছওয়ালা বলা হয়?"}', '{"en": "\"And (remember) Dhun-Nun, when he went off in anger…\"", "bn": "\"আর (স্মরণ করুন) যুন-নুনের কথা, যখন তিনি রাগ করে চলে গিয়েছিলেন…\""}', 'Quran 21:87', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('733a9c37-c921-5c73-8bb3-f8f8fe2b928c', 'e4a10d87-a156-567b-8cca-0e7d19e2caec', '{"en": "Musa", "bn": "মুসা (আ.)"}', false, 1), ('c0cbea44-db1d-5daa-b4ba-303ff8590302', 'e4a10d87-a156-567b-8cca-0e7d19e2caec', '{"en": "Yunus", "bn": "ইউনুস (আ.)"}', true, 2), ('b50d6b19-938d-5663-b42c-8bddf1894a97', 'e4a10d87-a156-567b-8cca-0e7d19e2caec', '{"en": "Nuh", "bn": "নূহ (আ.)"}', false, 3), ('39df9042-159f-58d2-bc5e-2dac0c5d283e', 'e4a10d87-a156-567b-8cca-0e7d19e2caec', '{"en": "Ilyas", "bn": "ইলিয়াস (আ.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4ee0f80d-8777-5cbf-91bd-ffb2225e7bb5', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Which prophet is praised in the Quran as \"true to his promise\"?", "bn": "কুরআনে কোন নবীকে \"প্রতিশ্রুতি রক্ষায় সত্যবাদী\" বলে প্রশংসা করা হয়েছে?"}', '{"en": "\"And mention Isma‘il in the Book; he was true to his promise, and he was a messenger, a prophet.\"", "bn": "\"আর কিতাবে ইসমাইলের কথা বর্ণনা করুন; তিনি ছিলেন প্রতিশ্রুতি রক্ষায় সত্যবাদী, এবং রাসুল ও নবী।\""}', 'Quran 19:54', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('4880f740-ba57-5391-8699-0a0853ae5663', '4ee0f80d-8777-5cbf-91bd-ffb2225e7bb5', '{"en": "Isma‘il", "bn": "ইসমাইল (আ.)"}', true, 1), ('bd924300-becd-58bc-8805-223dcd70ee19', '4ee0f80d-8777-5cbf-91bd-ffb2225e7bb5', '{"en": "Lut", "bn": "লুত (আ.)"}', false, 2), ('c705a5f3-64e5-59fa-b03a-2d267d27c426', '4ee0f80d-8777-5cbf-91bd-ffb2225e7bb5', '{"en": "Hud", "bn": "হুদ (আ.)"}', false, 3), ('4f2d1efc-d881-55b7-a5ee-647b7c9d675e', '4ee0f80d-8777-5cbf-91bd-ffb2225e7bb5', '{"en": "Ayyub", "bn": "আইয়ুব (আ.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9b955798-19cd-53ac-9693-3bef862580e7', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Which prophet was also called Isra’il?", "bn": "কোন নবীর আরেক নাম ইসরাইল?"}', '{"en": "Isra’il is Ya‘qub (AS); his descendants are the Children of Isra’il (Bani Isra’il).", "bn": "ইসরাইল হলেন ইয়াকুব (আ.); তাঁর বংশধররাই বনি ইসরাইল।"}', 'Quran 3:93; Quran 19:58', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a750a790-48cf-5170-b818-0db22f4f3156', '9b955798-19cd-53ac-9693-3bef862580e7', '{"en": "Ibrahim", "bn": "ইবরাহিম (আ.)"}', false, 1), ('86f97080-dd96-554b-830b-21a662670402', '9b955798-19cd-53ac-9693-3bef862580e7', '{"en": "Ishaq", "bn": "ইসহাক (আ.)"}', false, 2), ('cad6a4e4-2c6d-5ac6-916f-9a455abfbe48', '9b955798-19cd-53ac-9693-3bef862580e7', '{"en": "Ya‘qub", "bn": "ইয়াকুব (আ.)"}', true, 3), ('8135f91b-1a72-53d0-8b7f-03cd99e2a016', '9b955798-19cd-53ac-9693-3bef862580e7', '{"en": "Yusuf", "bn": "ইউসুফ (আ.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d00cd8f0-0d73-5e37-be1d-88cea44e741b', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Which prophet was sent to a people who worshipped an idol called Ba‘l?", "bn": "কোন নবীকে বা‘ল নামের মূর্তিপূজারী জাতির কাছে পাঠানো হয়েছিল?"}', '{"en": "\"And Ilyas was among the messengers… Do you call upon Ba‘l and leave the best of creators?\"", "bn": "\"আর ইলিয়াস ছিলেন রাসুলদের একজন… তোমরা কি বা‘লকে ডাকো আর সর্বশ্রেষ্ঠ স্রষ্টাকে ছেড়ে দাও?\""}', 'Quran 37:123–125', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('63eef121-218d-5fa0-b940-a5bdbf063611', 'd00cd8f0-0d73-5e37-be1d-88cea44e741b', '{"en": "Salih", "bn": "সালেহ (আ.)"}', false, 1), ('ae6b3b19-43ab-5683-a563-be6d476b8675', 'd00cd8f0-0d73-5e37-be1d-88cea44e741b', '{"en": "Shu‘ayb", "bn": "শুআইব (আ.)"}', false, 2), ('115e0d15-b0df-5df7-ada0-fa45fde9047f', 'd00cd8f0-0d73-5e37-be1d-88cea44e741b', '{"en": "Yunus", "bn": "ইউনুস (আ.)"}', false, 3), ('2475ace0-d802-5f00-bee0-82782a091bd1', 'd00cd8f0-0d73-5e37-be1d-88cea44e741b', '{"en": "Ilyas", "bn": "ইলিয়াস (আ.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8b399bc5-40e7-556b-9e86-9412aafaf380', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Which prophet spoke as a baby in the cradle?", "bn": "কোন নবী দোলনায় শিশু অবস্থায় কথা বলেছেন?"}', '{"en": "\"He said: I am the servant of Allah; He has given me the Book and made me a prophet.\"", "bn": "\"তিনি বললেন: আমি আল্লাহর বান্দা; তিনি আমাকে কিতাব দিয়েছেন এবং আমাকে নবী বানিয়েছেন।\""}', 'Quran 19:29–30', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e5a7703b-4c93-5e96-964c-61d07b4b2476', '8b399bc5-40e7-556b-9e86-9412aafaf380', '{"en": "Yahya", "bn": "ইয়াহইয়া (আ.)"}', false, 1), ('5722f54d-0d27-5b6e-8d5c-f61bea8cb1e6', '8b399bc5-40e7-556b-9e86-9412aafaf380', '{"en": "Isa", "bn": "ঈসা (আ.)"}', true, 2), ('aa2c13a3-3bb3-51fd-867a-324470443cec', '8b399bc5-40e7-556b-9e86-9412aafaf380', '{"en": "Musa", "bn": "মুসা (আ.)"}', false, 3), ('2800a03c-befa-51b8-9fad-08f511aea09e', '8b399bc5-40e7-556b-9e86-9412aafaf380', '{"en": "Sulayman", "bn": "সুলাইমান (আ.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('dc0f3e89-9e8d-5dba-a038-f23d7e6e5371', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "How long did Nuh live among his people?", "bn": "নূহ (আ.) তাঁর জাতির মধ্যে কত বছর ছিলেন?"}', '{"en": "\"…and he stayed among them a thousand years less fifty years.\"", "bn": "\"…তিনি তাদের মধ্যে পঞ্চাশ কম এক হাজার বছর অবস্থান করেছিলেন।\""}', 'Quran 29:14', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('030c1ca9-ab4b-5dd5-8bd5-4b99789e4a33', 'dc0f3e89-9e8d-5dba-a038-f23d7e6e5371', '{"en": "A thousand years less fifty (950)", "bn": "পঞ্চাশ কম এক হাজার বছর (৯৫০)"}', true, 1), ('3a374585-4927-5efd-85c0-10bd1eb3b5cd', 'dc0f3e89-9e8d-5dba-a038-f23d7e6e5371', '{"en": "100 years", "bn": "১০০ বছর"}', false, 2), ('48100f8e-1c22-559f-94b9-7ee774098b25', 'dc0f3e89-9e8d-5dba-a038-f23d7e6e5371', '{"en": "40 years", "bn": "৪০ বছর"}', false, 3), ('a0799f08-d4d5-5f12-b18d-1f1fdfc69232', 'dc0f3e89-9e8d-5dba-a038-f23d7e6e5371', '{"en": "300 years", "bn": "৩০০ বছর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ac111d9e-3fc1-5d68-953f-0902fb68ac15', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "In the Quran, Azar was the father of which prophet?", "bn": "কুরআনে আজর কোন নবীর পিতা?"}', '{"en": "\"And when Ibrahim said to his father Azar: Do you take idols as gods?\"", "bn": "\"আর যখন ইবরাহিম তাঁর পিতা আজরকে বললেন: আপনি কি মূর্তিগুলোকে ইলাহ বানিয়েছেন?\""}', 'Quran 6:74', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ee16b355-0882-5af2-b255-3cfb1c82b1d4', 'ac111d9e-3fc1-5d68-953f-0902fb68ac15', '{"en": "Nuh", "bn": "নূহ (আ.)"}', false, 1), ('69148bb3-fd4f-562a-96cd-267155f76837', 'ac111d9e-3fc1-5d68-953f-0902fb68ac15', '{"en": "Musa", "bn": "মুসা (আ.)"}', false, 2), ('526844a8-7e85-5f3b-9e69-85401c847ebb', 'ac111d9e-3fc1-5d68-953f-0902fb68ac15', '{"en": "Ibrahim", "bn": "ইবরাহিম (আ.)"}', true, 3), ('885d405c-d17b-5bc8-9058-94f2171911e1', 'ac111d9e-3fc1-5d68-953f-0902fb68ac15', '{"en": "Yusuf", "bn": "ইউসুফ (আ.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('61b2a88a-aa0a-58f1-976e-c007f8e96e42', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Which prophet worked as a shepherd for eight or ten years in Madyan before his marriage?", "bn": "কোন নবী বিয়ের আগে মাদইয়ানে আট বা দশ বছর মেষ চরিয়েছেন?"}', '{"en": "The old man of Madyan said: \"…on condition that you work for me eight years; and if you complete ten, it is from you.\"", "bn": "মাদইয়ানের বৃদ্ধ বললেন: \"…এই শর্তে যে তুমি আট বছর আমার কাজ করবে; আর দশ বছর পূর্ণ করলে তা তোমার পক্ষ থেকে।\""}', 'Quran 28:27–29', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('258b9fbc-6191-5e50-b4de-5f6500d5f607', '61b2a88a-aa0a-58f1-976e-c007f8e96e42', '{"en": "Dawud", "bn": "দাউদ (আ.)"}', false, 1), ('e376d6e4-4abb-5d2d-8b20-c02e159234f3', '61b2a88a-aa0a-58f1-976e-c007f8e96e42', '{"en": "Harun", "bn": "হারুন (আ.)"}', false, 2), ('8fa2b475-32d2-5aef-91f4-85620315c9d6', '61b2a88a-aa0a-58f1-976e-c007f8e96e42', '{"en": "Shu‘ayb", "bn": "শুআইব (আ.)"}', false, 3), ('26d397c2-0903-53a2-97ac-1b02313e162b', '61b2a88a-aa0a-58f1-976e-c007f8e96e42', '{"en": "Musa", "bn": "মুসা (আ.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('16968864-dd3b-53b2-b164-a10c30acad1f', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "What did Allah send to teach the son of Adam how to bury his brother?", "bn": "আদমের পুত্রকে ভাইয়ের লাশ দাফন শেখাতে আল্লাহ কী পাঠিয়েছিলেন?"}', '{"en": "\"Then Allah sent a crow scratching the ground, to show him how to hide his brother’s body.\"", "bn": "\"তারপর আল্লাহ একটি কাক পাঠালেন, যে মাটি খুঁড়ছিল, তাকে দেখাতে কীভাবে ভাইয়ের লাশ ঢাকবে।\""}', 'Quran 5:31', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7ced4328-45fa-54d4-bdd7-76da2bcbe6e2', '16968864-dd3b-53b2-b164-a10c30acad1f', '{"en": "A crow", "bn": "একটি কাক"}', true, 1), ('404ec812-136f-5c3e-b2ee-9124fe9167f9', '16968864-dd3b-53b2-b164-a10c30acad1f', '{"en": "An angel", "bn": "একজন ফেরেশতা"}', false, 2), ('298944a5-467a-528c-93ca-ec66811c601a', '16968864-dd3b-53b2-b164-a10c30acad1f', '{"en": "A dove", "bn": "একটি ঘুঘু"}', false, 3), ('bbdcd683-5412-5caf-8f0f-dce97b9da5f1', '16968864-dd3b-53b2-b164-a10c30acad1f', '{"en": "A wolf", "bn": "একটি নেকড়ে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c22e5ab9-db9d-53f2-b94b-707dd3b9684e', 'd5adad9c-484a-51bd-b651-6232e18cc6a0', '{"en": "Which prophet prayed \"Rabbishrah li sadri\" — my Lord, expand my chest for me?", "bn": "কোন নবী দোয়া করেছিলেন \"রাব্বিশরাহ লি সাদরি\" — হে আমার রব, আমার বক্ষ প্রশস্ত করে দিন?"}', '{"en": "Sent to Pharaoh, Musa (AS) asked Allah to expand his chest, ease his task and loosen the knot of his tongue.", "bn": "ফেরাউনের কাছে প্রেরিত হয়ে মুসা (আ.) বক্ষ প্রশস্ত, কাজ সহজ ও জিহ্বার জড়তা দূর করার দোয়া করেন।"}', 'Quran 20:25–28', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('84b73310-89dc-51dc-9ccd-e4be87768678', 'c22e5ab9-db9d-53f2-b94b-707dd3b9684e', '{"en": "Ibrahim", "bn": "ইবরাহিম (আ.)"}', false, 1), ('d899d3e1-3d58-55d5-bc42-dd5fc0cb1748', 'c22e5ab9-db9d-53f2-b94b-707dd3b9684e', '{"en": "Musa", "bn": "মুসা (আ.)"}', true, 2), ('394620a0-bc74-5842-a0eb-d8c87b4a3fae', 'c22e5ab9-db9d-53f2-b94b-707dd3b9684e', '{"en": "Zakariyya", "bn": "জাকারিয়া (আ.)"}', false, 3), ('a61186eb-4481-58ae-a198-561d58fd1436', 'c22e5ab9-db9d-53f2-b94b-707dd3b9684e', '{"en": "Yunus", "bn": "ইউনুস (আ.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Companions — part 2", "bn": "সাহাবিগণ — পর্ব ২"}', 'history', 'medium', NULL, 10, 'in_review', 114) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4b84a53e-3dc6-5a7c-bf66-8f3e82d3e3e9', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Which companion is the only one mentioned by name in the Quran?", "bn": "কোন সাহাবির নাম কুরআনে সরাসরি উল্লেখ আছে?"}', '{"en": "\"…So when Zayd had ended his marriage to her…\" — Zayd (RA) is the only companion named in the Quran.", "bn": "\"…অতঃপর যায়েদ যখন তার সঙ্গে বিবাহ সম্পর্ক ছিন্ন করল…\" — যায়েদ (রা.)-ই একমাত্র সাহাবি যাঁর নাম কুরআনে এসেছে।"}', 'Quran 33:37', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ac12061e-c661-53ce-ae20-acc153504c1a', '4b84a53e-3dc6-5a7c-bf66-8f3e82d3e3e9', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 1), ('06e4179c-ef16-5db9-ad9b-b39b8185ac06', '4b84a53e-3dc6-5a7c-bf66-8f3e82d3e3e9', '{"en": "Bilal", "bn": "বিলাল (রা.)"}', false, 2), ('31c73662-328d-50f3-9903-aa0986e77635', '4b84a53e-3dc6-5a7c-bf66-8f3e82d3e3e9', '{"en": "Zayd ibn Harithah", "bn": "যায়েদ ইবনে হারিসা (রা.)"}', true, 3), ('a55cc6d4-ee97-58e2-94f5-1553d7641ad5', '4b84a53e-3dc6-5a7c-bf66-8f3e82d3e3e9', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f21bef99-69a7-531f-b764-863156b7c633', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Who was sent to Madinah before the Hijrah to teach the Quran?", "bn": "হিজরতের আগে কুরআন শেখাতে কাকে মদিনায় পাঠানো হয়েছিল?"}', '{"en": "Al-Bara’ (RA): \"The first to come to us (in Madinah) were Mus‘ab ibn ‘Umayr and Ibn Umm Maktum; they taught people the Quran.\"", "bn": "বারা (রা.): \"আমাদের কাছে (মদিনায়) প্রথম আসেন মুসআব ইবনে উমাইর ও ইবনে উম্মে মাকতুম; তাঁরা মানুষকে কুরআন শেখাতেন।\""}', 'Sahih al-Bukhari 3925', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('5f7a9a89-6149-51f5-a2db-91315872ef8a', 'f21bef99-69a7-531f-b764-863156b7c633', '{"en": "Mus‘ab ibn ‘Umayr", "bn": "মুসআব ইবনে উমাইর (রা.)"}', true, 1), ('37f48992-b546-5a70-9cc2-5c56f564e225', 'f21bef99-69a7-531f-b764-863156b7c633', '{"en": "Khalid ibn al-Walid", "bn": "খালিদ ইবনুল ওয়ালিদ (রা.)"}', false, 2), ('b5faf74a-abd3-5417-9c0f-b7a75a78bedc', 'f21bef99-69a7-531f-b764-863156b7c633', '{"en": "Abu Hurayrah", "bn": "আবু হুরায়রা (রা.)"}', false, 3), ('df7610a2-094e-52fd-afb2-00bb929d2350', 'f21bef99-69a7-531f-b764-863156b7c633', '{"en": "Salman al-Farisi", "bn": "সালমান ফারসি (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('cacae5af-85a7-59b8-bb62-b6f2acef95f5', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Whom did the Prophet ﷺ send to Yemen to teach and call people to Islam?", "bn": "নবী ﷺ কাকে ইয়েমেনে শিক্ষা ও দাওয়াতের জন্য পাঠিয়েছিলেন?"}', '{"en": "He ﷺ sent Mu‘adh to Yemen: \"Call them to testify that there is no god but Allah…\"", "bn": "নবী ﷺ মুআজ (রা.)-কে ইয়েমেনে পাঠিয়ে বলেন: \"তাদের ডাকো সাক্ষ্য দিতে যে আল্লাহ ছাড়া কোনো ইলাহ নেই…\""}', 'Sahih al-Bukhari 1395', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d29b46e5-6215-5138-9180-963b03627973', 'cacae5af-85a7-59b8-bb62-b6f2acef95f5', '{"en": "Hamzah", "bn": "হামজা (রা.)"}', false, 1), ('9d42fdf4-6008-5d9b-9987-615418a380b9', 'cacae5af-85a7-59b8-bb62-b6f2acef95f5', '{"en": "Mu‘adh ibn Jabal", "bn": "মুআজ ইবনে জাবাল (রা.)"}', true, 2), ('57199928-8ddd-590d-aed6-7ddbd3811a50', 'cacae5af-85a7-59b8-bb62-b6f2acef95f5', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 3), ('5e6f9571-1b27-5869-a80e-b7bdc93a9a3d', 'cacae5af-85a7-59b8-bb62-b6f2acef95f5', '{"en": "Bilal", "bn": "বিলাল (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('97aa04e2-ca7a-568c-a498-26cedaf38f36', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "For whom did the Prophet ﷺ pray, \"O Allah, give him understanding of the religion\"?", "bn": "নবী ﷺ কার জন্য দোয়া করেছিলেন, \"হে আল্লাহ, তাকে দ্বীনের গভীর জ্ঞান দিন\"?"}', '{"en": "Ibn ‘Abbas (RA) became the great scholar of tafsir, \"the interpreter of the Quran\".", "bn": "ইবনে আব্বাস (রা.) হয়ে ওঠেন তাফসিরের মহান আলেম, \"কুরআনের ভাষ্যকার\"।"}', 'Sahih al-Bukhari 143', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('66cb065c-5932-5a4d-9bc8-07ffc09496bb', '97aa04e2-ca7a-568c-a498-26cedaf38f36', '{"en": "Abu Sufyan", "bn": "আবু সুফিয়ান (রা.)"}', false, 1), ('3bc55286-a9ff-53a7-97c8-2dd4e685d17c', '97aa04e2-ca7a-568c-a498-26cedaf38f36', '{"en": "Khalid ibn al-Walid", "bn": "খালিদ ইবনুল ওয়ালিদ (রা.)"}', false, 2), ('d4044772-4fd4-55f5-8a6e-cb075c228d95', '97aa04e2-ca7a-568c-a498-26cedaf38f36', '{"en": "Hassan ibn Thabit", "bn": "হাসসান ইবনে সাবিত (রা.)"}', false, 3), ('c6373c3b-c762-5e86-b452-d839bae6c62b', '97aa04e2-ca7a-568c-a498-26cedaf38f36', '{"en": "‘Abdullah ibn ‘Abbas", "bn": "আবদুল্লাহ ইবনে আব্বাস (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('138e3327-db0c-5d65-9c62-a9b5bda2f6c7', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Which companion was the poet who defended the Prophet ﷺ with his poems?", "bn": "কোন সাহাবি কবিতার মাধ্যমে নবী ﷺ-এর পক্ষে জবাব দিতেন?"}', '{"en": "He ﷺ said to Hassan: \"Answer them (in verse), and Jibril is with you.\"", "bn": "নবী ﷺ হাসসান (রা.)-কে বলেন: \"তাদের (কবিতায়) জবাব দাও, জিবরাইল তোমার সঙ্গে আছেন।\""}', 'Sahih al-Bukhari 3213', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('dfb0f2ea-c078-5b53-8c3b-84f3b3e0cc9b', '138e3327-db0c-5d65-9c62-a9b5bda2f6c7', '{"en": "Hassan ibn Thabit", "bn": "হাসসান ইবনে সাবিত (রা.)"}', true, 1), ('1760b510-c631-5219-ac3f-7ac7141d40a1', '138e3327-db0c-5d65-9c62-a9b5bda2f6c7', '{"en": "Abu Dharr", "bn": "আবু যর (রা.)"}', false, 2), ('0a0fef17-8fc6-5667-9dfb-483a3ce0d1ab', '138e3327-db0c-5d65-9c62-a9b5bda2f6c7', '{"en": "Anas ibn Malik", "bn": "আনাস ইবনে মালিক (রা.)"}', false, 3), ('d4371c56-00b6-50e4-8a23-858e7c6bc8e7', '138e3327-db0c-5d65-9c62-a9b5bda2f6c7', '{"en": "Sa‘d ibn Mu‘adh", "bn": "সাদ ইবনে মুআজ (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7cbfe7b5-dc2f-57f6-8156-aa68d428ee11', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "In whose house did the Prophet ﷺ stay when he first arrived in Madinah?", "bn": "মদিনায় পৌঁছে নবী ﷺ প্রথমে কার বাড়িতে উঠেছিলেন?"}', '{"en": "He ﷺ stayed with Abu Ayyub al-Ansari (RA) until his rooms beside the masjid were built.", "bn": "মসজিদের পাশে হুজরা তৈরি হওয়া পর্যন্ত নবী ﷺ আবু আইয়ুব আনসারি (রা.)-এর বাড়িতে ছিলেন।"}', 'Sahih Muslim 2053', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e29cab6d-f66c-59ee-9116-ca7941609555', '7cbfe7b5-dc2f-57f6-8156-aa68d428ee11', '{"en": "‘Umar", "bn": "উমর (রা.)"}', false, 1), ('23166f65-b6bb-58b5-83dc-39d97fd46176', '7cbfe7b5-dc2f-57f6-8156-aa68d428ee11', '{"en": "Abu Ayyub al-Ansari", "bn": "আবু আইয়ুব আনসারি (রা.)"}', true, 2), ('5c97899a-12b5-5d18-b3bd-c9af73f7fb35', '7cbfe7b5-dc2f-57f6-8156-aa68d428ee11', '{"en": "Abu Talib", "bn": "আবু তালিব"}', false, 3), ('5eb2f902-1d02-5ced-b608-19229c7adcbd', '7cbfe7b5-dc2f-57f6-8156-aa68d428ee11', '{"en": "Mu‘adh", "bn": "মুআজ (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f68d80cf-dda3-58d9-a0ec-407c6b5bf612', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Which companion served the Prophet ﷺ for ten years?", "bn": "কোন সাহাবি দশ বছর নবী ﷺ-এর খেদমত করেছেন?"}', '{"en": "Anas (RA): \"I served him for ten years, and he never once said to me ‘Uff’.\"", "bn": "আনাস (রা.): \"আমি দশ বছর তাঁর খেদমত করেছি, তিনি কখনো আমাকে ‘উহ্‌’ পর্যন্ত বলেননি।\""}', 'Sahih Muslim 2309', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('066ac0a8-b2d1-530c-b0b0-966b29092b0f', 'f68d80cf-dda3-58d9-a0ec-407c6b5bf612', '{"en": "Zayd ibn Thabit", "bn": "যায়েদ ইবনে সাবিত (রা.)"}', false, 1), ('a10061a4-2c0f-57b0-a27b-2cdb6e6dabda', 'f68d80cf-dda3-58d9-a0ec-407c6b5bf612', '{"en": "Abu ‘Ubaydah", "bn": "আবু উবাইদা (রা.)"}', false, 2), ('20da1c96-e299-5e8f-b595-9fe03fa5dab2', 'f68d80cf-dda3-58d9-a0ec-407c6b5bf612', '{"en": "Anas ibn Malik", "bn": "আনাস ইবনে মালিক (রা.)"}', true, 3), ('ec0c549f-8d32-57cc-83c7-92e6bd8836d9', 'f68d80cf-dda3-58d9-a0ec-407c6b5bf612', '{"en": "Ja‘far", "bn": "জাফর (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('82080631-9f46-5ef5-bd4e-39808ff7a75a', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Who spoke for the Muslims before the Negus (an-Najashi) in Abyssinia?", "bn": "আবিসিনিয়ায় নাজাশির সামনে মুসলিমদের পক্ষে কে কথা বলেছিলেন?"}', '{"en": "Ja‘far (RA) described Islam and recited the opening of Surah Maryam, and the Negus wept.", "bn": "জাফর (রা.) ইসলামের পরিচয় দিলেন এবং সূরা মারইয়ামের শুরু তিলাওয়াত করলেন; নাজাশি কেঁদে ফেললেন।"}', 'Musnad Ahmad 1740', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fa91dad2-972e-5a81-b52d-5832fe754900', '82080631-9f46-5ef5-bd4e-39808ff7a75a', '{"en": "Ja‘far ibn Abi Talib", "bn": "জাফর ইবনে আবি তালিব (রা.)"}', true, 1), ('44aefb5b-6da3-57c2-ae1b-3a8017ed8e26', '82080631-9f46-5ef5-bd4e-39808ff7a75a', '{"en": "Hamzah", "bn": "হামজা (রা.)"}', false, 2), ('5635b34f-ea20-57b1-9f05-f1771efd5313', '82080631-9f46-5ef5-bd4e-39808ff7a75a', '{"en": "Bilal", "bn": "বিলাল (রা.)"}', false, 3), ('d8d7dc14-30dc-5dd2-bf12-df53a896119c', '82080631-9f46-5ef5-bd4e-39808ff7a75a', '{"en": "‘Amr ibn al-‘As", "bn": "আমর ইবনুল আস"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b57af6ed-4a9f-5ee0-8f83-1294a7cddc23', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "At whose death did the Throne of the Most Merciful shake?", "bn": "কার মৃত্যুতে দয়াময়ের আরশ কেঁপে উঠেছিল?"}', '{"en": "\"The Throne shook at the death of Sa‘d ibn Mu‘adh,\" the leader of the Aws.", "bn": "\"সাদ ইবনে মুআজের মৃত্যুতে আরশ কেঁপে উঠেছে,\" — তিনি ছিলেন আওস গোত্রের নেতা।"}', 'Sahih al-Bukhari 3803', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f1b6c662-5840-5699-8fb5-3e81dd66ea56', 'b57af6ed-4a9f-5ee0-8f83-1294a7cddc23', '{"en": "Hamzah", "bn": "হামজা (রা.)"}', false, 1), ('dd44c3e1-cc1f-5130-9a1d-fa65cb6990d7', 'b57af6ed-4a9f-5ee0-8f83-1294a7cddc23', '{"en": "Mus‘ab ibn ‘Umayr", "bn": "মুসআব ইবনে উমাইর (রা.)"}', false, 2), ('5f6fdade-38e5-503e-8a7d-80cad0a9b411', 'b57af6ed-4a9f-5ee0-8f83-1294a7cddc23', '{"en": "Ja‘far", "bn": "জাফর (রা.)"}', false, 3), ('ecf63b23-6465-52bf-808d-c1894f0adc46', 'b57af6ed-4a9f-5ee0-8f83-1294a7cddc23', '{"en": "Sa‘d ibn Mu‘adh", "bn": "সাদ ইবনে মুআজ (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c43f8049-3c25-5636-bf0c-d9456b31d6a0', '549aa58e-22f7-5537-b06a-ae95999f3bf4', '{"en": "Ibn Mas‘ud said, \"We have been strong ever since … accepted Islam.\" Who?", "bn": "ইবনে মাসউদ (রা.) বলেন, \"… ইসলাম গ্রহণের পর থেকে আমরা শক্তিশালী হয়েছি।\" কে?"}', '{"en": "\"We have remained powerful since ‘Umar accepted Islam.\"", "bn": "\"উমর (রা.) ইসলাম গ্রহণের পর থেকে আমরা সবসময় শক্তিশালী ছিলাম।\""}', 'Sahih al-Bukhari 3684', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b6c0f652-7b53-588e-9595-874cfa55b0d3', 'c43f8049-3c25-5636-bf0c-d9456b31d6a0', '{"en": "Abu Sufyan", "bn": "আবু সুফিয়ান (রা.)"}', false, 1), ('13fd9e68-df6f-5616-89e3-2802607a6bb8', 'c43f8049-3c25-5636-bf0c-d9456b31d6a0', '{"en": "‘Umar", "bn": "উমর (রা.)"}', true, 2), ('58381933-e017-5c64-b521-b26d6405d00f', 'c43f8049-3c25-5636-bf0c-d9456b31d6a0', '{"en": "Khalid", "bn": "খালিদ (রা.)"}', false, 3), ('02ff8876-f266-5f89-94a0-2d9a4c5a75ad', 'c43f8049-3c25-5636-bf0c-d9456b31d6a0', '{"en": "Salman", "bn": "সালমান (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "The ten promised Paradise & more", "bn": "জান্নাতের সুসংবাদপ্রাপ্ত দশজন ও অন্যান্য"}', 'history', 'hard', 600, 10, 'in_review', 115) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e8c9ef39-9fe6-586e-b827-3c96673a29f3', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "The ten companions given the good news of Paradise in one hadith are called…?", "bn": "এক হাদিসে জান্নাতের সুসংবাদপ্রাপ্ত দশ সাহাবিকে কী বলা হয়?"}', '{"en": "‘Abd ar-Rahman ibn ‘Awf (RA) narrated: \"Abu Bakr is in Paradise, ‘Umar is in Paradise…\" — ten names.", "bn": "আবদুর রহমান ইবনে আউফ (রা.) বর্ণনা করেন: \"আবু বকর জান্নাতি, উমর জান্নাতি…\" — দশজনের নাম।"}', 'Jami‘ at-Tirmidhi 3747', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('04e718f9-84d9-5393-81e9-255a128119e1', 'e8c9ef39-9fe6-586e-b827-3c96673a29f3', '{"en": "Ahl as-Suffah", "bn": "আহলুস সুফফা"}', false, 1), ('abc469a3-0666-5d84-9828-316c3dfaf8ca', 'e8c9ef39-9fe6-586e-b827-3c96673a29f3', '{"en": "Al-‘Asharah al-Mubashsharah", "bn": "আশারায়ে মুবাশশারা"}', true, 2), ('f4acb8af-eed9-5314-b836-2c53ff60b86e', 'e8c9ef39-9fe6-586e-b827-3c96673a29f3', '{"en": "Al-Ansar", "bn": "আনসার"}', false, 3), ('1f988bad-e5bb-5fd7-b784-656acdcabfa0', 'e8c9ef39-9fe6-586e-b827-3c96673a29f3', '{"en": "Ahl Badr", "bn": "আহলে বদর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('eb0a6070-e025-57e7-b8eb-b2dd9833401e', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "Which of these is NOT among the ten in that hadith?", "bn": "ঐ হাদিসের দশজনের মধ্যে কে নেই?"}', '{"en": "Bilal (RA) was given glad tidings in other hadith, but is not one of these ten.", "bn": "বিলাল (রা.)-কে অন্য হাদিসে সুসংবাদ দেওয়া হয়েছে, কিন্তু তিনি এই দশজনের মধ্যে নেই।"}', 'Jami‘ at-Tirmidhi 3747', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('6bb32ef3-4cb9-5a04-8885-b84516273f2f', 'eb0a6070-e025-57e7-b8eb-b2dd9833401e', '{"en": "Talhah", "bn": "তালহা (রা.)"}', false, 1), ('e36c154d-2ec5-5269-a7a4-4191853a365e', 'eb0a6070-e025-57e7-b8eb-b2dd9833401e', '{"en": "Az-Zubayr", "bn": "জুবাইর (রা.)"}', false, 2), ('d487c229-6ef5-584b-9d7e-3578edb2f55a', 'eb0a6070-e025-57e7-b8eb-b2dd9833401e', '{"en": "Sa‘d ibn Abi Waqqas", "bn": "সাদ ইবনে আবি ওয়াক্কাস (রা.)"}', false, 3), ('d4645064-c0f5-58b9-9235-d603d951af49', 'eb0a6070-e025-57e7-b8eb-b2dd9833401e', '{"en": "Bilal", "bn": "বিলাল (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('23f3891e-53a2-53e9-9453-5a4d8e626c6b', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "Who shielded the Prophet ﷺ at Uhud until his hand was paralysed?", "bn": "উহুদে কে নবী ﷺ-কে আড়াল করে রক্ষা করেছিলেন, যতক্ষণ না তাঁর হাত অবশ হয়ে যায়?"}', '{"en": "Qays: \"I saw the hand of Talhah, paralysed; he had shielded the Prophet ﷺ with it.\"", "bn": "কায়েস: \"আমি তালহার অবশ হাত দেখেছি; সেই হাত দিয়ে তিনি নবী ﷺ-কে রক্ষা করেছিলেন।\""}', 'Sahih al-Bukhari 3724', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cf2501a6-7c3d-5a57-8520-d9fac75f09f2', '23f3891e-53a2-53e9-9453-5a4d8e626c6b', '{"en": "Talhah ibn ‘Ubaydullah", "bn": "তালহা ইবনে উবাইদুল্লাহ (রা.)"}', true, 1), ('41c72aa6-c520-5159-bb5d-acf192cc0bac', '23f3891e-53a2-53e9-9453-5a4d8e626c6b', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 2), ('86700cc9-bf22-555f-8022-540ed8f0d318', '23f3891e-53a2-53e9-9453-5a4d8e626c6b', '{"en": "Abu Hurayrah", "bn": "আবু হুরায়রা (রা.)"}', false, 3), ('3596e05c-f9a9-517d-9d47-aa4cf3b0ace3', '23f3891e-53a2-53e9-9453-5a4d8e626c6b', '{"en": "Salman", "bn": "সালমান (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('221a215e-b22a-5e27-8e81-0ad045db023e', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "Who was the first to shoot an arrow in the path of Allah?", "bn": "আল্লাহর পথে সর্বপ্রথম তীর নিক্ষেপ করেন কে?"}', '{"en": "Sa‘d (RA): \"I was the first of the Arabs to shoot an arrow in the path of Allah.\"", "bn": "সাদ (রা.): \"আরবদের মধ্যে আমিই প্রথম আল্লাহর পথে তীর নিক্ষেপ করেছি।\""}', 'Sahih al-Bukhari 3728', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b65c01bf-4b1e-54f1-942b-438862613d22', '221a215e-b22a-5e27-8e81-0ad045db023e', '{"en": "Hamzah", "bn": "হামজা (রা.)"}', false, 1), ('8cf4c047-ca11-5424-8caf-7b309e7d075e', '221a215e-b22a-5e27-8e81-0ad045db023e', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 2), ('e1baa337-8469-5a0c-b988-adbbb9d92449', '221a215e-b22a-5e27-8e81-0ad045db023e', '{"en": "Sa‘d ibn Abi Waqqas", "bn": "সাদ ইবনে আবি ওয়াক্কাস (রা.)"}', true, 3), ('00cf590c-e9c7-52d9-9896-388e913423ce', '221a215e-b22a-5e27-8e81-0ad045db023e', '{"en": "Khalid", "bn": "খালিদ (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4b54ca5c-ff5c-5ce5-9554-8810bc4532c9', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "The Prophet ﷺ said, \"Every prophet has a disciple (hawari), and my disciple is…\"", "bn": "নবী ﷺ বলেছেন, \"প্রত্যেক নবীর একজন হাওয়ারি (একান্ত সহযোগী) আছে, আর আমার হাওয়ারি হলো…\""}', '{"en": "\"Every prophet has a hawari, and my hawari is az-Zubayr.\"", "bn": "\"প্রত্যেক নবীর হাওয়ারি আছে, আর আমার হাওয়ারি জুবাইর।\""}', 'Sahih al-Bukhari 2846', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('354be432-4e06-59ed-9f73-efa189139f34', '4b54ca5c-ff5c-5ce5-9554-8810bc4532c9', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 1), ('5dd19f06-955d-5746-8125-72b9587d9651', '4b54ca5c-ff5c-5ce5-9554-8810bc4532c9', '{"en": "Az-Zubayr ibn al-‘Awwam", "bn": "জুবাইর ইবনুল আওয়াম (রা.)"}', true, 2), ('018ff37d-bac2-59d1-8704-8884b9a1a5d8', '4b54ca5c-ff5c-5ce5-9554-8810bc4532c9', '{"en": "Mu‘adh", "bn": "মুআজ (রা.)"}', false, 3), ('12ec1c79-795b-543c-9a1f-992f556bcfe4', '4b54ca5c-ff5c-5ce5-9554-8810bc4532c9', '{"en": "Anas", "bn": "আনাস (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('96dd1d66-d353-57bc-acf6-5b562333d44a', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "Which of the ten, offered half of an Ansari’s wealth, said only \"Show me the market\"?", "bn": "দশজনের কে আনসারি ভাইয়ের অর্ধেক সম্পদের প্রস্তাব পেয়ে শুধু বললেন, \"আমাকে বাজার দেখিয়ে দাও\"?"}', '{"en": "Brothered with Sa‘d ibn ar-Rabi‘, he refused the gift, traded in the market and became wealthy.", "bn": "সাদ ইবনুর রাবি (রা.)-এর সঙ্গে ভ্রাতৃত্ব হলে তিনি উপহার নিলেন না, বাজারে ব্যবসা করে সম্পদশালী হলেন।"}', 'Sahih al-Bukhari 2048', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c139151c-8169-52c9-a044-6b13e890fcdc', '96dd1d66-d353-57bc-acf6-5b562333d44a', '{"en": "‘Abd ar-Rahman ibn ‘Awf", "bn": "আবদুর রহমান ইবনে আউফ (রা.)"}', true, 1), ('3038167c-b8c1-5b74-9e74-ec45ffe01a3f', '96dd1d66-d353-57bc-acf6-5b562333d44a', '{"en": "Sa‘id ibn Zayd", "bn": "সাঈদ ইবনে যায়েদ (রা.)"}', false, 2), ('0cb99cb8-019c-5085-a00f-ab104ba5db98', '96dd1d66-d353-57bc-acf6-5b562333d44a', '{"en": "Abu ‘Ubaydah", "bn": "আবু উবাইদা (রা.)"}', false, 3), ('801f850c-dd43-53a8-8134-adefab79f975', '96dd1d66-d353-57bc-acf6-5b562333d44a', '{"en": "‘Umar", "bn": "উমর (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ef241475-036e-5349-94bc-2e03fd1952b5', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "Shortly before his death, the Prophet ﷺ made which young companion commander of an army?", "bn": "ইন্তেকালের কিছু আগে নবী ﷺ কোন তরুণ সাহাবিকে সেনাপতি নিযুক্ত করেন?"}', '{"en": "Some objected to his youth; the Prophet ﷺ said he was fit to command, as his father Zayd had been.", "bn": "তাঁর অল্প বয়স নিয়ে কেউ আপত্তি করলে নবী ﷺ বললেন, সে নেতৃত্বের যোগ্য, যেমন তার পিতা যায়েদ ছিলেন।"}', 'Sahih al-Bukhari 4469', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('33bae6f1-7dd2-51ec-88bc-f7bda0234cc4', 'ef241475-036e-5349-94bc-2e03fd1952b5', '{"en": "Anas ibn Malik", "bn": "আনাস ইবনে মালিক (রা.)"}', false, 1), ('1fa37a69-2ce0-523a-b200-e7a5c97546b4', 'ef241475-036e-5349-94bc-2e03fd1952b5', '{"en": "‘Abdullah ibn ‘Umar", "bn": "আবদুল্লাহ ইবনে উমর (রা.)"}', false, 2), ('7c1df23a-a064-515c-810f-4b68c18d342f', 'ef241475-036e-5349-94bc-2e03fd1952b5', '{"en": "Mu‘awiyah", "bn": "মুআবিয়া (রা.)"}', false, 3), ('f1942311-cf69-5bb5-99b5-435142bcd055', 'ef241475-036e-5349-94bc-2e03fd1952b5', '{"en": "Usamah ibn Zayd", "bn": "উসামা ইবনে যায়েদ (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('710394a4-e046-5243-b921-ce429152ddb6', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "At Mu’tah, the three commanders named by the Prophet ﷺ were Zayd ibn Harithah, Ja‘far and…?", "bn": "মুতার যুদ্ধে নবী ﷺ-এর নিযুক্ত তিন সেনাপতি: যায়েদ ইবনে হারিসা, জাফর এবং…?"}', '{"en": "\"If Zayd is killed, then Ja‘far; and if Ja‘far is killed, then ‘Abdullah ibn Rawahah.\" All three were martyred.", "bn": "\"যায়েদ শহিদ হলে জাফর; জাফর শহিদ হলে আবদুল্লাহ ইবনে রাওয়াহা।\" তিনজনই শহিদ হন।"}', 'Sahih al-Bukhari 4261', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b1cb7bf2-7908-5f37-b843-3ce25506ccfa', '710394a4-e046-5243-b921-ce429152ddb6', '{"en": "‘Abdullah ibn Rawahah", "bn": "আবদুল্লাহ ইবনে রাওয়াহা (রা.)"}', true, 1), ('e6513ce7-08cf-5b68-a28d-b3a8405d4f16', '710394a4-e046-5243-b921-ce429152ddb6', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 2), ('0c835f1f-6738-5e2b-a6ca-33babbb20d4d', '710394a4-e046-5243-b921-ce429152ddb6', '{"en": "Bilal", "bn": "বিলাল (রা.)"}', false, 3), ('961f00de-2c62-5926-b3e8-6371d912f81c', '710394a4-e046-5243-b921-ce429152ddb6', '{"en": "Sa‘d ibn Mu‘adh", "bn": "সাদ ইবনে মুআজ (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c21b653d-7ba5-56ad-a4e7-632782023dd7', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "\"Learn the Quran from four\" — which of these was one of the four?", "bn": "\"চারজনের কাছ থেকে কুরআন শেখো\" — নিচের কে সেই চারজনের একজন?"}', '{"en": "The four: ‘Abdullah ibn Mas‘ud, Salim, Mu‘adh ibn Jabal and Ubayy ibn Ka‘b.", "bn": "চারজন: আবদুল্লাহ ইবনে মাসউদ, সালিম, মুআজ ইবনে জাবাল ও উবাই ইবনে কাব (রা.)।"}', 'Sahih al-Bukhari 3758', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0736afcb-1c08-5a3f-91ad-866740e97526', 'c21b653d-7ba5-56ad-a4e7-632782023dd7', '{"en": "Khalid ibn al-Walid", "bn": "খালিদ ইবনুল ওয়ালিদ (রা.)"}', false, 1), ('cd85be8f-9db0-51eb-9d79-9830b3df9456', 'c21b653d-7ba5-56ad-a4e7-632782023dd7', '{"en": "Abu Sufyan", "bn": "আবু সুফিয়ান (রা.)"}', false, 2), ('b2fe3806-bad8-59b5-900c-07cdb67f37e3', 'c21b653d-7ba5-56ad-a4e7-632782023dd7', '{"en": "‘Abdullah ibn Mas‘ud", "bn": "আবদুল্লাহ ইবনে মাসউদ (রা.)"}', true, 3), ('5d327a0d-3f4e-520c-92d4-87824c04b35f', 'c21b653d-7ba5-56ad-a4e7-632782023dd7', '{"en": "‘Amr ibn al-‘As", "bn": "আমর ইবনুল আস (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8ea69be8-c2c0-5407-9da7-15680e56fda0', 'e792330b-93b3-594a-be26-fdf5c926dec9', '{"en": "Sa‘id ibn Zayd, one of the ten, was married to the sister of…?", "bn": "দশজনের একজন সাঈদ ইবনে যায়েদ (রা.) কার বোনকে বিয়ে করেছিলেন?"}', '{"en": "Sa‘id said that before ‘Umar became Muslim, he had tied up Sa‘id and his own sister for their Islam.", "bn": "সাঈদ (রা.) বলেন, ইসলাম গ্রহণের আগে উমর তাঁকে ও নিজের বোনকে ইসলামের কারণে বেঁধে রেখেছিলেন।"}', 'Sahih al-Bukhari 3862', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9067b80f-500c-57bb-9f77-4f705c382066', '8ea69be8-c2c0-5407-9da7-15680e56fda0', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 1), ('944bb14b-a10f-587d-9f26-c9d46fc7ef6f', '8ea69be8-c2c0-5407-9da7-15680e56fda0', '{"en": "‘Umar ibn al-Khattab", "bn": "উমর ইবনুল খাত্তাব (রা.)"}', true, 2), ('8adba862-d061-58d3-a015-c40a1565e81c', '8ea69be8-c2c0-5407-9da7-15680e56fda0', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 3), ('1c24855c-8bb5-5705-b223-b954fe0d7860', '8ea69be8-c2c0-5407-9da7-15680e56fda0', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Mothers of the Believers", "bn": "উম্মুল মুমিনিন"}', 'seerah', 'medium', NULL, 10, 'in_review', 116) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('607998b7-e560-5b3c-91c0-65fdb892bb05', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Which surah says \"…and his wives are their mothers\"?", "bn": "কোন সূরায় আছে \"…আর তাঁর স্ত্রীগণ তাদের মা\"?"}', '{"en": "\"The Prophet is closer to the believers than their own selves, and his wives are their mothers.\"", "bn": "\"নবী মুমিনদের কাছে তাদের নিজেদের চেয়েও ঘনিষ্ঠ, আর তাঁর স্ত্রীগণ তাদের মা।\""}', 'Quran 33:6', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1027c38b-cb74-5ef9-ae67-08df463a46af', '607998b7-e560-5b3c-91c0-65fdb892bb05', '{"en": "An-Nisa", "bn": "আন-নিসা"}', false, 1), ('e0657f08-2fd1-58e1-905a-7d4b6511cfdb', '607998b7-e560-5b3c-91c0-65fdb892bb05', '{"en": "Al-Ahzab", "bn": "আল-আহযাব"}', true, 2), ('92796ff9-5243-54ad-8e87-5f1c9b3fac33', '607998b7-e560-5b3c-91c0-65fdb892bb05', '{"en": "At-Tahrim", "bn": "আত-তাহরিম"}', false, 3), ('76562225-535f-5b9b-9a9c-d4c2487b5ecb', '607998b7-e560-5b3c-91c0-65fdb892bb05', '{"en": "Maryam", "bn": "মারইয়াম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6780fb13-2dd3-5a4a-b461-3d994ed29ba4', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Hafsah (RA), a Mother of the Believers, was the daughter of…?", "bn": "উম্মুল মুমিনিন হাফসা (রা.) কার কন্যা?"}', '{"en": "Hafsah bint ‘Umar (RA) married the Prophet ﷺ after her first husband died.", "bn": "হাফসা বিনতে উমর (রা.) প্রথম স্বামীর মৃত্যুর পর নবী ﷺ-এর সঙ্গে বিবাহবন্ধনে আবদ্ধ হন।"}', 'Sahih al-Bukhari 4005', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1f879974-116d-52ab-b42d-04e9d64eb3f6', '6780fb13-2dd3-5a4a-b461-3d994ed29ba4', '{"en": "‘Umar ibn al-Khattab", "bn": "উমর ইবনুল খাত্তাব (রা.)"}', true, 1), ('b921eefd-3bbd-5307-b414-c7d6ad637ea9', '6780fb13-2dd3-5a4a-b461-3d994ed29ba4', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 2), ('2ae1f574-4c1c-521b-a5d0-2927f29d88c0', '6780fb13-2dd3-5a4a-b461-3d994ed29ba4', '{"en": "Abu Sufyan", "bn": "আবু সুফিয়ান (রা.)"}', false, 3), ('99d74615-76c0-5a11-ac19-a3498ea16d2b', '6780fb13-2dd3-5a4a-b461-3d994ed29ba4', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('269140e3-760d-5351-abb0-0e809364cbe0', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "After ‘Umar’s death, with whom were the pages of the Quran gathered by Abu Bakr kept?", "bn": "উমর (রা.)-এর মৃত্যুর পর আবু বকর (রা.)-এর সংকলিত কুরআনের পাণ্ডুলিপি কার কাছে ছিল?"}', '{"en": "The pages stayed with Abu Bakr, then ‘Umar, then Hafsah; ‘Uthman had copies made from them.", "bn": "পাণ্ডুলিপি ছিল আবু বকর, তারপর উমর, তারপর হাফসা (রা.)-এর কাছে; উসমান (রা.) সেখান থেকে কপি করান।"}', 'Sahih al-Bukhari 4986–4987', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('651589a4-2659-58ef-9278-a5e108c29f6b', '269140e3-760d-5351-abb0-0e809364cbe0', '{"en": "‘A’ishah", "bn": "আয়েশা (রা.)"}', false, 1), ('916908b7-5ca7-54d8-8469-8fe42a01253b', '269140e3-760d-5351-abb0-0e809364cbe0', '{"en": "Fatimah", "bn": "ফাতিমা (রা.)"}', false, 2), ('6e90363b-8edc-55b2-ada9-23d032a92adc', '269140e3-760d-5351-abb0-0e809364cbe0', '{"en": "Hafsah", "bn": "হাফসা (রা.)"}', true, 3), ('467b2287-3e63-5b7f-8fa8-cc5840c661ae', '269140e3-760d-5351-abb0-0e809364cbe0', '{"en": "Umm Salamah", "bn": "উম্মে সালামা (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b3ecc540-e699-56da-8e59-e0ddec7f344e', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Which Mother of the Believers gave her turn (day) to ‘A’ishah?", "bn": "কোন উম্মুল মুমিনিন নিজের পালার দিন আয়েশা (রা.)-কে দিয়ে দিয়েছিলেন?"}', '{"en": "‘A’ishah (RA): \"Sawdah gave her day to ‘A’ishah.\"", "bn": "আয়েশা (রা.): \"সাওদা (রা.) তাঁর দিনটি আয়েশাকে দিয়ে দিয়েছিলেন।\""}', 'Sahih al-Bukhari 5212', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fc6b29b3-988c-500c-9d38-11edc1054b4b', 'b3ecc540-e699-56da-8e59-e0ddec7f344e', '{"en": "Zaynab bint Jahsh", "bn": "জয়নাব বিনতে জাহশ (রা.)"}', false, 1), ('e45fdbc8-c846-558e-af9d-c473aac8e8fa', 'b3ecc540-e699-56da-8e59-e0ddec7f344e', '{"en": "Safiyyah", "bn": "সাফিয়্যা (রা.)"}', false, 2), ('e5adaf61-5cf9-57ef-90da-5c4e6b61be6f', 'b3ecc540-e699-56da-8e59-e0ddec7f344e', '{"en": "Juwayriyah", "bn": "জুওয়াইরিয়া (রা.)"}', false, 3), ('2101f37b-effa-5b1d-a9ff-34dd0c1d59d7', 'b3ecc540-e699-56da-8e59-e0ddec7f344e', '{"en": "Sawdah bint Zam‘ah", "bn": "সাওদা বিনতে জামআ (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f6bb323d-4ca4-5407-8dd0-509bf25d87f5', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Whose marriage to the Prophet ﷺ is told in Surah al-Ahzab (33:37)?", "bn": "সূরা আহযাবে (৩৩:৩৭) কার সঙ্গে নবী ﷺ-এর বিবাহের কথা আছে?"}', '{"en": "Zaynab (RA) used to say to the other wives: \"Allah married me to him from above the seven heavens.\"", "bn": "জয়নাব (রা.) অন্য স্ত্রীদের বলতেন: \"আল্লাহ সাত আসমানের ওপর থেকে আমার বিয়ে দিয়েছেন।\""}', 'Quran 33:37; Sahih al-Bukhari 7420', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('53c6dd6d-509d-5610-b385-2b74aa207d72', 'f6bb323d-4ca4-5407-8dd0-509bf25d87f5', '{"en": "Zaynab bint Jahsh", "bn": "জয়নাব বিনতে জাহশ (রা.)"}', true, 1), ('ba11ad81-44eb-5a0e-a484-cf59cb59c894', 'f6bb323d-4ca4-5407-8dd0-509bf25d87f5', '{"en": "Khadijah", "bn": "খাদিজা (রা.)"}', false, 2), ('8ffd344f-123e-5f8e-97ba-bedab9079bde', 'f6bb323d-4ca4-5407-8dd0-509bf25d87f5', '{"en": "Maymunah", "bn": "মাইমুনা (রা.)"}', false, 3), ('185257ef-b81f-5e35-87cf-03bcdb196e59', 'f6bb323d-4ca4-5407-8dd0-509bf25d87f5', '{"en": "Sawdah", "bn": "সাওদা (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('cb291a61-05cd-5999-90e6-525a5c8ceb52', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Which Mother of the Believers was the daughter of Abu Sufyan, married while she was in Abyssinia?", "bn": "কোন উম্মুল মুমিনিন আবু সুফিয়ানের কন্যা, যাঁর বিয়ে হয়েছিল আবিসিনিয়ায় থাকা অবস্থায়?"}', '{"en": "Umm Habibah (Ramlah) bint Abi Sufyan; the Negus arranged her marriage and gave her mahr.", "bn": "উম্মে হাবিবা (রামলা) বিনতে আবি সুফিয়ান; নাজাশি তাঁর বিয়ের ব্যবস্থা করেন ও মোহর দেন।"}', 'Sunan Abi Dawud 2107', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9dc54f55-1872-5f93-9a69-3b0b8f1e6600', 'cb291a61-05cd-5999-90e6-525a5c8ceb52', '{"en": "Hafsah", "bn": "হাফসা (রা.)"}', false, 1), ('eb95c732-ed16-5240-88ac-5b9d62e24fbd', 'cb291a61-05cd-5999-90e6-525a5c8ceb52', '{"en": "Umm Habibah", "bn": "উম্মে হাবিবা (রা.)"}', true, 2), ('6c5799fd-f6f1-5e50-bb42-54d69b281e7c', 'cb291a61-05cd-5999-90e6-525a5c8ceb52', '{"en": "Umm Salamah", "bn": "উম্মে সালামা (রা.)"}', false, 3), ('8afc23fe-c12c-51ec-9edb-ef4a3ee20373', 'cb291a61-05cd-5999-90e6-525a5c8ceb52', '{"en": "‘A’ishah", "bn": "আয়েশা (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('851933c3-c2f1-5a60-9705-214bf241df7b', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "At Hudaybiyah, whose advice was \"go out, sacrifice and shave, and the people will follow\"?", "bn": "হুদাইবিয়ায় কার পরামর্শ ছিল \"আপনি বের হয়ে কুরবানি করুন ও মাথা মুণ্ডন করুন, মানুষ অনুসরণ করবে\"?"}', '{"en": "He ﷺ did so, and the companions rushed to sacrifice and shave.", "bn": "নবী ﷺ তা-ই করলেন, আর সাহাবিরা দ্রুত কুরবানি ও মাথা মুণ্ডন করলেন।"}', 'Sahih al-Bukhari 2731', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f5bb79a6-897a-531d-936d-734c956c7255', '851933c3-c2f1-5a60-9705-214bf241df7b', '{"en": "Sawdah", "bn": "সাওদা (রা.)"}', false, 1), ('9856a98e-1623-5dbd-bb51-5fb8ccaceacc', '851933c3-c2f1-5a60-9705-214bf241df7b', '{"en": "Juwayriyah", "bn": "জুওয়াইরিয়া (রা.)"}', false, 2), ('316bd51d-5b0d-5654-a30a-13eb4fdfc40a', '851933c3-c2f1-5a60-9705-214bf241df7b', '{"en": "Umm Salamah", "bn": "উম্মে সালামা (রা.)"}', true, 3), ('9149d849-b96b-5b74-9d0b-86a8136b16c8', '851933c3-c2f1-5a60-9705-214bf241df7b', '{"en": "Safiyyah", "bn": "সাফিয়্যা (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b28ab673-978a-5a2e-a923-6e0981ada400', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Whose marriage to the Prophet ﷺ led the Muslims to free many captives of her tribe, Banu al-Mustaliq?", "bn": "কার সঙ্গে নবী ﷺ-এর বিয়ের কারণে মুসলিমরা তাঁর গোত্র বনু মুস্তালিকের বহু বন্দিকে মুক্ত করে দেয়?"}', '{"en": "‘A’ishah (RA): \"I know of no woman more blessed for her people than her.\"", "bn": "আয়েশা (রা.): \"নিজের গোত্রের জন্য তাঁর চেয়ে বেশি বরকতময় কোনো নারীর কথা আমি জানি না।\""}', 'Sunan Abi Dawud 3931', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7d3c89db-bb82-5e54-8662-13a80c1ce563', 'b28ab673-978a-5a2e-a923-6e0981ada400', '{"en": "Maymunah", "bn": "মাইমুনা (রা.)"}', false, 1), ('0148ffe1-8dfe-5833-b775-6fdedf04a1e1', 'b28ab673-978a-5a2e-a923-6e0981ada400', '{"en": "Zaynab bint Khuzaymah", "bn": "জয়নাব বিনতে খুযাইমা (রা.)"}', false, 2), ('5cdc8af2-dac9-5031-92ab-25d2ea1b39e9', 'b28ab673-978a-5a2e-a923-6e0981ada400', '{"en": "Hafsah", "bn": "হাফসা (রা.)"}', false, 3), ('f5140526-ef3e-51b4-8049-5dd486851a8c', 'b28ab673-978a-5a2e-a923-6e0981ada400', '{"en": "Juwayriyah bint al-Harith", "bn": "জুওয়াইরিয়া বিনতে হারিস (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7e5cfca1-da63-5434-910f-42f81ede2599', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "Which Mother of the Believers was the daughter of Huyayy ibn Akhtab, married after Khaybar?", "bn": "কোন উম্মুল মুমিনিন হুয়াই ইবনে আখতাবের কন্যা, খায়বারের পর যাঁর বিয়ে হয়?"}', '{"en": "He ﷺ freed Safiyyah (RA) and made her freedom her mahr.", "bn": "নবী ﷺ সাফিয়্যা (রা.)-কে মুক্ত করেন এবং মুক্তিকেই তাঁর মোহর বানান।"}', 'Sahih al-Bukhari 4200', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3ca369e8-884e-5255-a53e-561731191dad', '7e5cfca1-da63-5434-910f-42f81ede2599', '{"en": "Safiyyah", "bn": "সাফিয়্যা (রা.)"}', true, 1), ('234a4205-4feb-531f-9feb-3afa627d5c89', '7e5cfca1-da63-5434-910f-42f81ede2599', '{"en": "Sawdah", "bn": "সাওদা (রা.)"}', false, 2), ('4195d3a4-b305-5fb1-b239-4e7c8b781c29', '7e5cfca1-da63-5434-910f-42f81ede2599', '{"en": "Umm Habibah", "bn": "উম্মে হাবিবা (রা.)"}', false, 3), ('27514e9e-82ca-59dd-8f58-862ec2fefe14', '7e5cfca1-da63-5434-910f-42f81ede2599', '{"en": "Zaynab bint Jahsh", "bn": "জয়নাব বিনতে জাহশ (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a8c37b2c-7406-58bd-a0fd-98b46518497b', '506d7347-25bc-5ecd-b2d2-370a182f0b88', '{"en": "The innocence of ‘A’ishah (RA) from the slander was revealed in which surah?", "bn": "অপবাদ থেকে আয়েশা (রা.)-এর নির্দোষিতা কোন সূরায় নাজিল হয়?"}', '{"en": "\"Indeed, those who came with the slander are a group among you…\" — ten ayahs of an-Nur.", "bn": "\"নিশ্চয় যারা এই অপবাদ রটনা করেছে তারা তোমাদেরই একটি দল…\" — সূরা নূরের দশ আয়াত।"}', 'Quran 24:11–20; Sahih al-Bukhari 4750', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('721dd0c0-c223-5d47-a77c-9a2146422006', 'a8c37b2c-7406-58bd-a0fd-98b46518497b', '{"en": "Al-Ahzab", "bn": "আল-আহযাব"}', false, 1), ('8d8d45be-acb0-5347-9963-2337977bc0ca', 'a8c37b2c-7406-58bd-a0fd-98b46518497b', '{"en": "An-Nur", "bn": "আন-নূর"}', true, 2), ('b3d8f458-3d97-51af-849d-fc4ca20976ca', 'a8c37b2c-7406-58bd-a0fd-98b46518497b', '{"en": "Al-Hujurat", "bn": "আল-হুজুরাত"}', false, 3), ('4161c763-6b0b-5733-b29f-a087627e543e', 'a8c37b2c-7406-58bd-a0fd-98b46518497b', '{"en": "Al-Mujadilah", "bn": "আল-মুজাদালা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "Seerah: the Makkan years", "bn": "সীরাত: মক্কী জীবন"}', 'seerah', 'medium', NULL, 10, 'in_review', 117) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c7ccca29-0504-5258-91af-d36b9f67df18', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "On which hill did the Prophet ﷺ first openly call the clans of Quraysh?", "bn": "নবী ﷺ কোন পাহাড়ে উঠে প্রথম প্রকাশ্যে কুরাইশ গোত্রগুলোকে ডেকেছিলেন?"}', '{"en": "When \"Warn your nearest kin\" was revealed, he ﷺ climbed as-Safa and called out to the clans.", "bn": "\"আপনার নিকটাত্মীয়দের সতর্ক করুন\" নাজিল হলে নবী ﷺ সাফায় উঠে গোত্রগুলোকে ডাকলেন।"}', 'Quran 26:214; Sahih al-Bukhari 4770', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7e79acea-d26e-56ac-a749-163553068e3c', 'c7ccca29-0504-5258-91af-d36b9f67df18', '{"en": "Uhud", "bn": "উহুদ"}', false, 1), ('92c2ecff-6a88-5fdc-8573-5b7f6f5bc72c', 'c7ccca29-0504-5258-91af-d36b9f67df18', '{"en": "Thawr", "bn": "সাওর"}', false, 2), ('f37a27f3-26ca-52d2-8b57-b1b0fb7dca25', 'c7ccca29-0504-5258-91af-d36b9f67df18', '{"en": "As-Safa", "bn": "সাফা"}', true, 3), ('9fff899d-45bb-5fcb-93dc-cf081a3afb0e', 'c7ccca29-0504-5258-91af-d36b9f67df18', '{"en": "Arafat", "bn": "আরাফাত"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ecd90cdd-e71e-526d-a9bb-ec32fef00a45', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "In whose house did the early Muslims meet in secret to learn Islam?", "bn": "প্রথম যুগের মুসলিমরা গোপনে কার বাড়িতে মিলিত হয়ে ইসলাম শিখতেন?"}', '{"en": "Dar al-Arqam near as-Safa was the first centre of teaching Islam in Makkah.", "bn": "সাফার কাছে দারুল আরকাম ছিল মক্কায় ইসলাম শিক্ষার প্রথম কেন্দ্র।"}', 'Sirah Ibn Hisham; Ibn Sa‘d, at-Tabaqat', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('80c32fce-e6f6-5c0a-9024-078465a3ea5e', 'ecd90cdd-e71e-526d-a9bb-ec32fef00a45', '{"en": "Al-Arqam ibn Abi al-Arqam (Dar al-Arqam)", "bn": "আরকাম ইবনে আবিল আরকাম (দারুল আরকাম)"}', true, 1), ('aea8ee59-4615-5d9b-a6f8-6a31d00b9134', 'ecd90cdd-e71e-526d-a9bb-ec32fef00a45', '{"en": "Abu Jahl", "bn": "আবু জাহল"}', false, 2), ('e78d83c5-6562-5dbd-ab9a-529d12b26dfe', 'ecd90cdd-e71e-526d-a9bb-ec32fef00a45', '{"en": "Abu Lahab", "bn": "আবু লাহাব"}', false, 3), ('580285b5-0cd8-573f-ae50-322e855a73de', 'ecd90cdd-e71e-526d-a9bb-ec32fef00a45', '{"en": "Waraqah", "bn": "ওয়ারাকা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1d2be755-e135-5f8d-904a-8ff54fd22957', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "To which land did the first Muslims emigrate to escape persecution?", "bn": "নির্যাতন থেকে বাঁচতে প্রথম মুসলিমরা কোন দেশে হিজরত করেন?"}', '{"en": "The Prophet ﷺ sent them to Abyssinia, whose king wronged no one.", "bn": "নবী ﷺ তাঁদের আবিসিনিয়ায় পাঠান, যার বাদশাহ কারো ওপর জুলুম করতেন না।"}', 'Musnad Ahmad 1740; Sirah Ibn Hisham', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f67b1cdf-9c31-52ed-bc08-888a820a9c00', '1d2be755-e135-5f8d-904a-8ff54fd22957', '{"en": "Yemen", "bn": "ইয়েমেন"}', false, 1), ('aab5238d-cffa-5bed-864f-0a491b91d9ab', '1d2be755-e135-5f8d-904a-8ff54fd22957', '{"en": "Abyssinia (Habashah)", "bn": "আবিসিনিয়া (হাবশা)"}', true, 2), ('2186567f-f2a0-5bcf-8b69-8c9d262dfcf3', '1d2be755-e135-5f8d-904a-8ff54fd22957', '{"en": "Persia", "bn": "পারস্য"}', false, 3), ('d89e337a-2f8f-5167-9aa6-6352a409fd22', '1d2be755-e135-5f8d-904a-8ff54fd22957', '{"en": "Egypt", "bn": "মিসর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('dd8bbf7d-ad1b-5566-ab2c-d216013736e1', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "What was the title of the just king of Abyssinia who protected the Muslims?", "bn": "মুসলিমদের আশ্রয়দাতা আবিসিনিয়ার ন্যায়পরায়ণ বাদশাহর উপাধি কী?"}', '{"en": "When the Negus died, the Prophet ﷺ prayed the funeral prayer for him in Madinah.", "bn": "নাজাশির মৃত্যুর পর নবী ﷺ মদিনায় তাঁর গায়েবানা জানাযা পড়েন।"}', 'Sahih al-Bukhari 1333', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ee0c17c3-99da-510b-92eb-30c3ccc3f88b', 'dd8bbf7d-ad1b-5566-ab2c-d216013736e1', '{"en": "Kisra", "bn": "কিসরা"}', false, 1), ('d7e64230-a533-50df-88a9-36ab25e8b14a', 'dd8bbf7d-ad1b-5566-ab2c-d216013736e1', '{"en": "Qaysar", "bn": "কায়সার"}', false, 2), ('a7258184-8904-59d7-b70d-2297013e506c', 'dd8bbf7d-ad1b-5566-ab2c-d216013736e1', '{"en": "Fir‘awn", "bn": "ফেরাউন"}', false, 3), ('997368ad-d82a-571f-8b7d-b03a29c27503', 'dd8bbf7d-ad1b-5566-ab2c-d216013736e1', '{"en": "An-Najashi (the Negus)", "bn": "নাজাশি"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2186098e-6663-5fbd-81e0-79ed46121d75', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "For about how long were Banu Hashim boycotted in the valley of Abu Talib?", "bn": "আবু তালিব উপত্যকায় বনু হাশিমকে প্রায় কত দিন বয়কট করে রাখা হয়েছিল?"}', '{"en": "Quraysh signed a pact to boycott them; it lasted about three years before it collapsed.", "bn": "কুরাইশরা বয়কটের চুক্তি করে; প্রায় তিন বছর পর তা ভেঙে যায়।"}', 'Sirah Ibn Hisham', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1e04fb5b-26e2-5fd6-a469-3d6e822161f6', '2186098e-6663-5fbd-81e0-79ed46121d75', '{"en": "Three months", "bn": "তিন মাস"}', false, 1), ('7cb46fe7-0918-5425-a846-f3cf40c95fa2', '2186098e-6663-5fbd-81e0-79ed46121d75', '{"en": "Ten years", "bn": "দশ বছর"}', false, 2), ('345ddfe3-055c-5d37-99e1-ee30884eeb20', '2186098e-6663-5fbd-81e0-79ed46121d75', '{"en": "About three years", "bn": "প্রায় তিন বছর"}', true, 3), ('702b06fa-52c7-50e3-b27c-bde46978fb19', '2186098e-6663-5fbd-81e0-79ed46121d75', '{"en": "Forty days", "bn": "চল্লিশ দিন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('260c2e87-4539-52c7-b467-5531a1383a0d', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "In which cave did the Prophet ﷺ and Abu Bakr hide during the Hijrah?", "bn": "হিজরতের সময় নবী ﷺ ও আবু বকর (রা.) কোন গুহায় আত্মগোপন করেছিলেন?"}', '{"en": "They stayed three nights in a cave in Mount Thawr.", "bn": "তাঁরা সাওর পাহাড়ের একটি গুহায় তিন রাত ছিলেন।"}', 'Sahih al-Bukhari 3905', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d76360da-d577-5b6a-a655-a0069fc7225e', '260c2e87-4539-52c7-b467-5531a1383a0d', '{"en": "Hira", "bn": "হেরা"}', false, 1), ('cbe30502-7e82-5a74-9ad8-fce36f15a4db', '260c2e87-4539-52c7-b467-5531a1383a0d', '{"en": "Thawr", "bn": "সাওর"}', true, 2), ('23de1b13-e04a-5b33-8778-13ab42dd9099', '260c2e87-4539-52c7-b467-5531a1383a0d', '{"en": "Uhud", "bn": "উহুদ"}', false, 3), ('bc85d0a2-1080-5396-8a14-31c8c27a1ad0', '260c2e87-4539-52c7-b467-5531a1383a0d', '{"en": "Al-Kahf", "bn": "আল-কাহফ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('13fdc825-98a2-5061-85ba-91ef14799865', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "Who slept in the Prophet’s ﷺ bed on the night of the Hijrah?", "bn": "হিজরতের রাতে কে নবী ﷺ-এর বিছানায় শুয়েছিলেন?"}', '{"en": "‘Ali (RA) stayed behind, slept in his bed and returned the trusts people had left with the Prophet ﷺ.", "bn": "আলী (রা.) থেকে গেলেন, নবীজির বিছানায় ঘুমালেন এবং মানুষের আমানত ফেরত দিলেন।"}', 'Sirah Ibn Hisham; Musnad Ahmad (from Ibn ‘Abbas)', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('219e81a0-6a6a-547f-ab21-0934cd14e06a', '13fdc825-98a2-5061-85ba-91ef14799865', '{"en": "‘Ali ibn Abi Talib", "bn": "আলী ইবনে আবি তালিব (রা.)"}', true, 1), ('de0438f0-c251-55c7-a04a-c7cdeec80ed9', '13fdc825-98a2-5061-85ba-91ef14799865', '{"en": "Zayd ibn Harithah", "bn": "যায়েদ ইবনে হারিসা (রা.)"}', false, 2), ('dbaa4771-0b6d-5e8e-a85b-c7fc6eab81bd', '13fdc825-98a2-5061-85ba-91ef14799865', '{"en": "Bilal", "bn": "বিলাল (রা.)"}', false, 3), ('e06fa6ad-598d-5935-9517-afaecac29fce', '13fdc825-98a2-5061-85ba-91ef14799865', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('816d079f-5c1f-5caf-801b-3d341f77e51a', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "Where did the people of Yathrib (Madinah) pledge allegiance to the Prophet ﷺ before the Hijrah?", "bn": "হিজরতের আগে ইয়াসরিবের (মদিনার) লোকেরা কোথায় নবী ﷺ-এর হাতে বায়আত গ্রহণ করে?"}', '{"en": "‘Ubadah ibn as-Samit (RA) was among those who gave the pledge on the night of al-‘Aqabah.", "bn": "উবাদা ইবনে সামিত (রা.) আকাবার রাতে বায়আতকারীদের একজন ছিলেন।"}', 'Sahih al-Bukhari 3892–3893', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('aad6ef88-da8c-5cb9-9d20-432ca6f47cb8', '816d079f-5c1f-5caf-801b-3d341f77e51a', '{"en": "Badr", "bn": "বদর"}', false, 1), ('d4ab65ab-0a1b-54a9-a3cc-7f2b624624e6', '816d079f-5c1f-5caf-801b-3d341f77e51a', '{"en": "Ta’if", "bn": "তায়েফ"}', false, 2), ('c3457d25-93c3-5380-910d-fb665f1e8534', '816d079f-5c1f-5caf-801b-3d341f77e51a', '{"en": "Hudaybiyah", "bn": "হুদাইবিয়া"}', false, 3), ('dec8e2cb-3001-537d-af56-04563cad9195', '816d079f-5c1f-5caf-801b-3d341f77e51a', '{"en": "Al-‘Aqabah", "bn": "আকাবা"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('61cdf6d7-8037-54a2-84f1-4209dda76cca', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "For how many years did the Prophet ﷺ stay in Makkah after the revelation began?", "bn": "ওহি শুরুর পর নবী ﷺ মক্কায় কত বছর ছিলেন?"}', '{"en": "Ibn ‘Abbas (RA): he stayed thirteen years in Makkah receiving revelation, then emigrated and lived ten years in Madinah.", "bn": "ইবনে আব্বাস (রা.): তিনি ওহি পেয়ে মক্কায় তেরো বছর ছিলেন, তারপর হিজরত করে মদিনায় দশ বছর ছিলেন।"}', 'Sahih al-Bukhari 3902', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ce670444-fe83-55d6-993d-dcdbf59d6381', '61cdf6d7-8037-54a2-84f1-4209dda76cca', '{"en": "5", "bn": "৫"}', false, 1), ('63981872-3bf9-5e46-8307-f648db025d2a', '61cdf6d7-8037-54a2-84f1-4209dda76cca', '{"en": "10", "bn": "১০"}', false, 2), ('ea8be7a8-0509-57c9-a4d8-f25f23c6dd48', '61cdf6d7-8037-54a2-84f1-4209dda76cca', '{"en": "13", "bn": "১৩"}', true, 3), ('0a574d86-bc3b-5515-bfc4-c78b0394874b', '61cdf6d7-8037-54a2-84f1-4209dda76cca', '{"en": "23", "bn": "২৩"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a4fbab83-2395-5673-b3ac-7d5f696d2bf2', '2fe08e6c-01df-5b7d-8f19-404033e2313e', '{"en": "When the people of Makkah asked for a sign, what happened to the moon?", "bn": "মক্কাবাসী নিদর্শন চাইলে চাঁদের কী হয়েছিল?"}', '{"en": "\"The Hour has drawn near and the moon has split.\"", "bn": "\"কিয়ামত নিকটবর্তী হয়েছে এবং চাঁদ দ্বিখণ্ডিত হয়েছে।\""}', 'Quran 54:1; Sahih al-Bukhari 3868', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('203ec307-9420-535e-91b9-f4265448c9da', 'a4fbab83-2395-5673-b3ac-7d5f696d2bf2', '{"en": "It split in two", "bn": "দুই টুকরা হয়েছিল"}', true, 1), ('00fb1188-b19e-55e2-bf10-dd3759df767a', 'a4fbab83-2395-5673-b3ac-7d5f696d2bf2', '{"en": "It turned red", "bn": "লাল হয়ে গিয়েছিল"}', false, 2), ('a33eaf1f-a23e-5538-8153-0851365ec97c', 'a4fbab83-2395-5673-b3ac-7d5f696d2bf2', '{"en": "It vanished for a month", "bn": "এক মাস অদৃশ্য ছিল"}', false, 3), ('62ebbcd6-5cd8-543b-be94-34b1260e2c59', 'a4fbab83-2395-5673-b3ac-7d5f696d2bf2', '{"en": "It rose in the west", "bn": "পশ্চিমে উদিত হয়েছিল"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "Seerah: the Madinan years", "bn": "সীরাত: মাদানী জীবন"}', 'seerah', 'hard', 600, 10, 'in_review', 118) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('470fcf98-39e5-5c10-a6be-fc398d8e2585', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "The bond the Prophet ﷺ made between the Muhajirun and the Ansar is called…?", "bn": "মুহাজির ও আনসারদের মধ্যে নবী ﷺ যে বন্ধন স্থাপন করেন তাকে কী বলে?"}', '{"en": "Each emigrant was made the brother of an Ansari, like ‘Abd ar-Rahman ibn ‘Awf and Sa‘d ibn ar-Rabi‘.", "bn": "প্রত্যেক মুহাজিরকে একজন আনসারির ভাই বানানো হয়, যেমন আবদুর রহমান ইবনে আউফ ও সাদ ইবনুর রাবি।"}', 'Sahih al-Bukhari 2048', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3036f1ef-bfbe-5bb7-91aa-8f81170fdd8f', '470fcf98-39e5-5c10-a6be-fc398d8e2585', '{"en": "Al-Mu’akhah (brotherhood)", "bn": "মুআখাত (ভ্রাতৃত্ব)"}', true, 1), ('45419397-b512-502a-8321-3bc19be7b454', '470fcf98-39e5-5c10-a6be-fc398d8e2585', '{"en": "Al-Hijrah", "bn": "হিজরত"}', false, 2), ('f37e0ec8-7921-5113-8224-4ed9a0382f99', '470fcf98-39e5-5c10-a6be-fc398d8e2585', '{"en": "Al-Bay‘ah", "bn": "বায়আত"}', false, 3), ('976754e5-78cc-5837-beb5-3a61328c8849', '470fcf98-39e5-5c10-a6be-fc398d8e2585', '{"en": "As-Sulh", "bn": "সন্ধি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('562f05fc-0657-53c4-b4db-744e3d2bf852', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "About how long after the Hijrah did the qiblah change to the Ka‘bah?", "bn": "হিজরতের প্রায় কত দিন পর কিবলা কাবার দিকে পরিবর্তিত হয়?"}', '{"en": "Al-Bara’ (RA): he prayed toward Bayt al-Maqdis for sixteen or seventeen months, then the qiblah was turned.", "bn": "বারা (রা.): নবী ﷺ ষোলো বা সতেরো মাস বায়তুল মাকদিসের দিকে নামাজ পড়েন, তারপর কিবলা পরিবর্তিত হয়।"}', 'Sahih al-Bukhari 40; Quran 2:144', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('efcd7ef9-798e-5365-8b5d-039403e89823', '562f05fc-0657-53c4-b4db-744e3d2bf852', '{"en": "One week", "bn": "এক সপ্তাহ"}', false, 1), ('e5fc032e-c1f3-5ffd-a717-183a0f1b708b', '562f05fc-0657-53c4-b4db-744e3d2bf852', '{"en": "Five years", "bn": "পাঁচ বছর"}', false, 2), ('d8aecf44-3e61-5bd4-b5c5-adf24719820d', '562f05fc-0657-53c4-b4db-744e3d2bf852', '{"en": "Sixteen or seventeen months", "bn": "ষোলো বা সতেরো মাস"}', true, 3), ('ff89ecba-6d16-5a5d-9305-885e18cbd6cc', '562f05fc-0657-53c4-b4db-744e3d2bf852', '{"en": "Ten years", "bn": "দশ বছর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4ef80447-d360-5ff7-ab18-456078a98a38', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "About how many Muslims fought at Badr?", "bn": "বদরের যুদ্ধে প্রায় কতজন মুসলিম ছিলেন?"}', '{"en": "Al-Bara’ (RA): they were three hundred and ten-odd, like the number who crossed the river with Talut.", "bn": "বারা (রা.): তাঁরা ছিলেন তিনশো দশের কিছু বেশি, তালুতের সঙ্গে নদী পার হওয়া লোকদের সমান।"}', 'Sahih al-Bukhari 3957', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fafb9973-d098-56c6-81a6-26adf10de0b2', '4ef80447-d360-5ff7-ab18-456078a98a38', '{"en": "About 70", "bn": "প্রায় ৭০"}', false, 1), ('a8a15493-8b65-5c30-ab0e-f112ac25c28a', '4ef80447-d360-5ff7-ab18-456078a98a38', '{"en": "About 313", "bn": "প্রায় ৩১৩"}', true, 2), ('be9d576c-03e1-5913-9c3f-0fadf13ab2fa', '4ef80447-d360-5ff7-ab18-456078a98a38', '{"en": "About 1,000", "bn": "প্রায় ১,০০০"}', false, 3), ('4e0291e7-aead-5450-85f1-116b43ca5ff6', '4ef80447-d360-5ff7-ab18-456078a98a38', '{"en": "About 3,000", "bn": "প্রায় ৩,০০০"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7f418419-6655-511c-920e-658d4532df30', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "Who led the people in prayer during the Prophet’s ﷺ final illness?", "bn": "নবী ﷺ-এর শেষ অসুস্থতার সময় কে নামাজে ইমামতি করেছিলেন?"}', '{"en": "\"Tell Abu Bakr to lead the people in prayer.\"", "bn": "\"আবু বকরকে বলো, সে যেন মানুষের নামাজে ইমামতি করে।\""}', 'Sahih al-Bukhari 664', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3d3b82e1-6a71-54cf-8610-710c44aaa071', '7f418419-6655-511c-920e-658d4532df30', '{"en": "‘Umar", "bn": "উমর (রা.)"}', false, 1), ('ac15c2c4-0625-5fea-9938-9cd98f60243e', '7f418419-6655-511c-920e-658d4532df30', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 2), ('a07d6bfc-fb95-5cbf-aefe-28c3b3596e95', '7f418419-6655-511c-920e-658d4532df30', '{"en": "Bilal", "bn": "বিলাল (রা.)"}', false, 3), ('23498aae-a2a0-54a6-b3f0-3002ec25f03d', '7f418419-6655-511c-920e-658d4532df30', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('129f8f15-4c7a-57d5-bb9c-8c3ac40f9650', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "Which was the last military expedition the Prophet ﷺ went out on?", "bn": "নবী ﷺ সর্বশেষ কোন অভিযানে নিজে বের হয়েছিলেন?"}', '{"en": "Ka‘b ibn Malik (RA): \"I never stayed behind the Messenger ﷺ in any expedition except Tabuk,\" his last, in 9 AH.", "bn": "কাব ইবনে মালিক (রা.): \"তাবুক ছাড়া কোনো অভিযানে আমি পিছিয়ে থাকিনি\" — এটি ছিল ৯ হিজরির শেষ অভিযান।"}', 'Sahih al-Bukhari 4418', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('6dc77f64-baa3-50db-a148-c92c5703cf7d', '129f8f15-4c7a-57d5-bb9c-8c3ac40f9650', '{"en": "Tabuk", "bn": "তাবুক"}', true, 1), ('7c4158ec-21fa-5a48-b9d4-fbf764749926', '129f8f15-4c7a-57d5-bb9c-8c3ac40f9650', '{"en": "Badr", "bn": "বদর"}', false, 2), ('39ef999d-6713-5cf0-9322-48a41257bf0f', '129f8f15-4c7a-57d5-bb9c-8c3ac40f9650', '{"en": "Khaybar", "bn": "খায়বার"}', false, 3), ('e65e154d-38df-5382-b135-92e1ee21da76', '129f8f15-4c7a-57d5-bb9c-8c3ac40f9650', '{"en": "Uhud", "bn": "উহুদ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('67891b3c-b68e-5fd3-a59b-2f4cf8c94548', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "In which battle, soon after the conquest of Makkah, did the Muslims’ large numbers at first make them proud?", "bn": "মক্কা বিজয়ের পরপর কোন যুদ্ধে মুসলিমরা প্রথমে নিজেদের সংখ্যাধিক্যে গর্বিত হয়েছিল?"}', '{"en": "\"…and on the day of Hunayn, when your great number pleased you, but it did not help you at all.\"", "bn": "\"…আর হুনাইনের দিন, যখন তোমাদের সংখ্যাধিক্য তোমাদের মুগ্ধ করেছিল, কিন্তু তা তোমাদের কোনো কাজে আসেনি।\""}', 'Quran 9:25', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('262359b9-dc9f-562b-96fa-63a793a427d8', '67891b3c-b68e-5fd3-a59b-2f4cf8c94548', '{"en": "Badr", "bn": "বদর"}', false, 1), ('057b6766-e9b3-51db-a866-4143f0f8708a', '67891b3c-b68e-5fd3-a59b-2f4cf8c94548', '{"en": "Mu’tah", "bn": "মুতা"}', false, 2), ('7e83b2da-9717-5ebd-b00a-df6668f57a5d', '67891b3c-b68e-5fd3-a59b-2f4cf8c94548', '{"en": "Hunayn", "bn": "হুনাইন"}', true, 3), ('440ff248-5c56-5ec0-84df-90ecc281876e', '67891b3c-b68e-5fd3-a59b-2f4cf8c94548', '{"en": "The Trench", "bn": "খন্দক"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('63aaa5d1-9698-5b49-a28e-1a97c2bc36ad', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "In which year was Khaybar conquered?", "bn": "খায়বার কোন সালে বিজিত হয়?"}', '{"en": "Khaybar was taken in 7 AH, after the Treaty of Hudaybiyah (6 AH).", "bn": "হুদাইবিয়ার সন্ধির (৬ হিজরি) পর ৭ হিজরিতে খায়বার বিজয় হয়।"}', 'Sahih al-Bukhari 4197; Sirah Ibn Hisham', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3bafa2e8-a67c-5c78-9a2d-8f9b2f5dd173', '63aaa5d1-9698-5b49-a28e-1a97c2bc36ad', '{"en": "2 AH", "bn": "২ হিজরি"}', false, 1), ('c56b842e-9aef-55d6-91bb-85efca4852dd', '63aaa5d1-9698-5b49-a28e-1a97c2bc36ad', '{"en": "7 AH", "bn": "৭ হিজরি"}', true, 2), ('3ff76fd0-6b60-5811-b88f-589f332858a8', '63aaa5d1-9698-5b49-a28e-1a97c2bc36ad', '{"en": "5 AH", "bn": "৫ হিজরি"}', false, 3), ('dafa867c-8458-5265-9bab-7b19f07ac894', '63aaa5d1-9698-5b49-a28e-1a97c2bc36ad', '{"en": "10 AH", "bn": "১০ হিজরি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ef08719d-5b86-597b-8958-1a552519a8fe', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "The year 9 AH, when tribes from all over Arabia came to accept Islam, is called…?", "bn": "৯ হিজরি সাল, যখন আরবের নানা গোত্র এসে ইসলাম গ্রহণ করে, তাকে কী বলে?"}', '{"en": "After Makkah was conquered, delegations came one after another; Surah an-Nasr describes people entering Islam in crowds.", "bn": "মক্কা বিজয়ের পর একের পর এক প্রতিনিধিদল আসে; সূরা নাসরে দলে দলে ইসলামে প্রবেশের কথা আছে।"}', 'Quran 110:2; Sirah Ibn Hisham', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('4a764795-12b0-5648-918b-595336bba40f', 'ef08719d-5b86-597b-8958-1a552519a8fe', '{"en": "The Year of Sorrow", "bn": "দুঃখের বছর"}', false, 1), ('bb2da55f-abb7-5ae5-99f0-0ead04b6eb2c', 'ef08719d-5b86-597b-8958-1a552519a8fe', '{"en": "The Year of the Elephant", "bn": "হাতির বছর"}', false, 2), ('34815082-9f61-5c0a-a3ed-924e85ca7695', 'ef08719d-5b86-597b-8958-1a552519a8fe', '{"en": "The Year of Victory", "bn": "বিজয়ের বছর"}', false, 3), ('2be07fbb-2a99-5bdb-9f96-74724694e756', 'ef08719d-5b86-597b-8958-1a552519a8fe', '{"en": "The Year of Delegations (‘Am al-Wufud)", "bn": "প্রতিনিধিদলের বছর (আমুল উফুদ)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('08ae5cbc-2067-553a-8161-82d4d817272d', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "At what age did the Prophet ﷺ pass away?", "bn": "নবী ﷺ কত বছর বয়সে ইন্তেকাল করেন?"}', '{"en": "‘A’ishah (RA): he passed away at the age of sixty-three.", "bn": "আয়েশা (রা.): তিনি তেষট্টি বছর বয়সে ইন্তেকাল করেন।"}', 'Sahih al-Bukhari 3536', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('510c200b-3a90-577f-9b5d-816b6fda7547', '08ae5cbc-2067-553a-8161-82d4d817272d', '{"en": "63", "bn": "৬৩"}', true, 1), ('74deb7d5-6825-51a1-b6f1-cd80a8b7c517', '08ae5cbc-2067-553a-8161-82d4d817272d', '{"en": "60", "bn": "৬০"}', false, 2), ('78d953ab-8a29-5f91-9fe3-5bda0b6b28ad', '08ae5cbc-2067-553a-8161-82d4d817272d', '{"en": "70", "bn": "৭০"}', false, 3), ('7b59e250-db84-572c-b4c0-5a5adceab311', '08ae5cbc-2067-553a-8161-82d4d817272d', '{"en": "53", "bn": "৫৩"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f4196557-2adf-5d47-9f0b-0c3e34fb2a8f', 'cf791eff-8900-518b-9b48-76580d3bb826', '{"en": "What was the name of the Prophet’s ﷺ she-camel, which he rode in the Farewell Hajj?", "bn": "বিদায় হজে নবী ﷺ যে উটনীতে আরোহণ করেছিলেন, তার নাম কী?"}', '{"en": "Jabir (RA) describes him riding al-Qaswa’ at Dhul-Hulayfah and at Arafah.", "bn": "জাবির (রা.) বর্ণনা করেন, তিনি যুলহুলাইফা ও আরাফায় কাসওয়ায় আরোহণ করেছিলেন।"}', 'Sahih Muslim 1218', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f8f4287b-334b-5b46-8b1a-a9ae0194dc02', 'f4196557-2adf-5d47-9f0b-0c3e34fb2a8f', '{"en": "Al-Buraq", "bn": "বুরাক"}', false, 1), ('8e56ed2a-4132-5d5d-930d-d50cf1f6a48c', 'f4196557-2adf-5d47-9f0b-0c3e34fb2a8f', '{"en": "Al-Qaswa’", "bn": "কাসওয়া"}', true, 2), ('3d35cdf7-9830-5523-9878-834c3cc6632f', 'f4196557-2adf-5d47-9f0b-0c3e34fb2a8f', '{"en": "Duldul", "bn": "দুলদুল"}', false, 3), ('77d34e13-e82b-5301-b720-59dba90398ed', 'f4196557-2adf-5d47-9f0b-0c3e34fb2a8f', '{"en": "The she-camel of Salih", "bn": "সালেহ (আ.)-এর উটনী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "The Rightly Guided Caliphate", "bn": "খোলাফায়ে রাশেদিন"}', 'history', 'medium', NULL, 10, 'in_review', 119) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4b429732-2707-5229-8529-66769da0ca46', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "The Prophet ﷺ said the caliphate (in the way of prophethood) would last…?", "bn": "নবী ﷺ বলেছেন, (নবুয়তের আদর্শে) খিলাফত কত বছর থাকবে?"}', '{"en": "\"The caliphate in my ummah will be thirty years,\" — roughly the time of the four rightly guided caliphs (with al-Hasan).", "bn": "\"আমার উম্মতের মধ্যে খিলাফত থাকবে ত্রিশ বছর\" — মোটামুটি চার খলিফার (হাসান (রা.)-সহ) সময়কাল।"}', 'Sunan Abi Dawud 4646; Jami‘ at-Tirmidhi 2226', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('193b2d9c-586a-5088-8670-4238320391b9', '4b429732-2707-5229-8529-66769da0ca46', '{"en": "10 years", "bn": "১০ বছর"}', false, 1), ('b0924532-6485-5b12-8656-9618958680d0', '4b429732-2707-5229-8529-66769da0ca46', '{"en": "100 years", "bn": "১০০ বছর"}', false, 2), ('423140d5-e940-5ff7-8a0c-80b1fc661610', '4b429732-2707-5229-8529-66769da0ca46', '{"en": "30 years", "bn": "৩০ বছর"}', true, 3), ('337b5cb4-c470-5cb0-a83d-7ca652109f97', '4b429732-2707-5229-8529-66769da0ca46', '{"en": "12 years", "bn": "১২ বছর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('72428de6-5b30-586f-ac87-4ba42c54503d', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "Which caliph fought those who refused to pay zakat after the Prophet ﷺ died?", "bn": "নবী ﷺ-এর ইন্তেকালের পর যাকাত দিতে অস্বীকারকারীদের বিরুদ্ধে কোন খলিফা লড়াই করেন?"}', '{"en": "Abu Bakr (RA): \"By Allah, I will fight whoever separates salah from zakat.\"", "bn": "আবু বকর (রা.): \"আল্লাহর কসম, যে নামাজ ও যাকাতের মধ্যে পার্থক্য করবে, আমি তার বিরুদ্ধে লড়ব।\""}', 'Sahih al-Bukhari 1400', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('45b0c32f-acab-508d-a439-8a1da649a0c9', '72428de6-5b30-586f-ac87-4ba42c54503d', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', true, 1), ('de95a54f-fd16-5173-9ee9-fdd802eb5eea', '72428de6-5b30-586f-ac87-4ba42c54503d', '{"en": "‘Umar", "bn": "উমর (রা.)"}', false, 2), ('bcf9dc19-1284-53c3-abe1-d251cafc14a5', '72428de6-5b30-586f-ac87-4ba42c54503d', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 3), ('69e93f9b-9d32-55fa-ac5a-bdeb837d1165', '72428de6-5b30-586f-ac87-4ba42c54503d', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('71ea7698-20aa-56ca-a920-13053a93aaee', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "Which caliph started dating years by the Hijri calendar?", "bn": "কোন খলিফা হিজরি সাল গণনা চালু করেন?"}', '{"en": "In ‘Umar’s caliphate the companions agreed to count the years from the Hijrah.", "bn": "উমর (রা.)-এর খিলাফতকালে সাহাবিরা হিজরত থেকে সাল গণনায় একমত হন।"}', 'Tarikh at-Tabari; Sahih al-Bukhari 3934', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('da9c29f8-1f65-57cd-b2a9-091fb39cf793', '71ea7698-20aa-56ca-a920-13053a93aaee', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 1), ('b0d32efa-15c2-5bfa-8ab4-35ae494994c3', '71ea7698-20aa-56ca-a920-13053a93aaee', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 2), ('38720f91-66e5-524c-9ba9-f31dd899d8aa', '71ea7698-20aa-56ca-a920-13053a93aaee', '{"en": "Mu‘awiyah", "bn": "মুআবিয়া (রা.)"}', false, 3), ('5f686dd0-1b67-54f8-b016-300de095ce83', '71ea7698-20aa-56ca-a920-13053a93aaee', '{"en": "‘Umar", "bn": "উমর (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fef95c77-beec-5f54-92a3-3462112d6e1d', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "In whose caliphate did Jerusalem come under Muslim rule, the caliph himself coming to receive it?", "bn": "কার খিলাফতকালে জেরুজালেম মুসলিমদের অধীনে আসে, খলিফা নিজে এসে তা গ্রহণ করেন?"}', '{"en": "‘Umar (RA) travelled to Jerusalem (about 637–638 CE) and gave its people a covenant of safety.", "bn": "উমর (রা.) জেরুজালেমে গিয়ে (প্রায় ৬৩৭–৬৩৮ খ্রি.) সেখানকার মানুষকে নিরাপত্তার অঙ্গীকারনামা দেন।"}', 'Tarikh at-Tabari', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('6b8a967d-8db1-5871-b1b1-3e3be2fb2902', 'fef95c77-beec-5f54-92a3-3462112d6e1d', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 1), ('d03ef858-3410-5d1b-aac0-1c22a16c6837', 'fef95c77-beec-5f54-92a3-3462112d6e1d', '{"en": "‘Umar", "bn": "উমর (রা.)"}', true, 2), ('19c3dd6e-0e11-5b38-8c92-2fd37736c07c', 'fef95c77-beec-5f54-92a3-3462112d6e1d', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 3), ('05f8c636-a24d-59d2-a460-cd49c23330bc', 'fef95c77-beec-5f54-92a3-3462112d6e1d', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('314dbe2c-d0f6-59d3-b1db-0fc63997c85f', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "The great battle against the Byzantine army in Syria in 636 CE was at…?", "bn": "৬৩৬ খ্রিস্টাব্দে সিরিয়ায় বাইজেন্টাইন বাহিনীর বিরুদ্ধে মহাযুদ্ধ কোথায় হয়?"}', '{"en": "At al-Yarmuk the Muslims, with Khalid ibn al-Walid among the commanders, defeated the Byzantines.", "bn": "ইয়ারমুকে খালিদ ইবনুল ওয়ালিদ (রা.)-সহ মুসলিম সেনাপতিরা বাইজেন্টাইনদের পরাজিত করেন।"}', 'Tarikh at-Tabari; al-Bidayah wan-Nihayah', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3a24e8e5-507b-53dc-9bac-b4072347ff48', '314dbe2c-d0f6-59d3-b1db-0fc63997c85f', '{"en": "Al-Yarmuk", "bn": "ইয়ারমুক"}', true, 1), ('797e687e-28e9-5f12-a82a-ca628eb591eb', '314dbe2c-d0f6-59d3-b1db-0fc63997c85f', '{"en": "Badr", "bn": "বদর"}', false, 2), ('b9d8a7b0-a33d-581a-a825-c5b4d9c65815', '314dbe2c-d0f6-59d3-b1db-0fc63997c85f', '{"en": "Nahawand", "bn": "নাহাওয়ান্দ"}', false, 3), ('f41e0b80-6b9f-567f-a898-81268d30c01f', '314dbe2c-d0f6-59d3-b1db-0fc63997c85f', '{"en": "Hunayn", "bn": "হুনাইন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('96c02bb5-86b8-5251-9820-8240dc2585a9', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "Who commanded the Muslims at al-Qadisiyyah against the Persian army?", "bn": "কাদিসিয়ায় পারস্য বাহিনীর বিরুদ্ধে মুসলিমদের সেনাপতি কে ছিলেন?"}', '{"en": "Sent by ‘Umar (RA), Sa‘d defeated the Persians at al-Qadisiyyah and later entered al-Mada’in.", "bn": "উমর (রা.)-এর পাঠানো সাদ (রা.) কাদিসিয়ায় পারসিকদের পরাজিত করেন এবং পরে মাদায়েনে প্রবেশ করেন।"}', 'Tarikh at-Tabari', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('67bd9f53-1af0-5cd6-a99a-2eb13a8bf81b', '96c02bb5-86b8-5251-9820-8240dc2585a9', '{"en": "Khalid ibn al-Walid", "bn": "খালিদ ইবনুল ওয়ালিদ (রা.)"}', false, 1), ('330c20f7-051e-5cb8-aee0-5c83572d6306', '96c02bb5-86b8-5251-9820-8240dc2585a9', '{"en": "‘Amr ibn al-‘As", "bn": "আমর ইবনুল আস (রা.)"}', false, 2), ('37e84ddd-7362-53b7-9143-251964e7e696', '96c02bb5-86b8-5251-9820-8240dc2585a9', '{"en": "Sa‘d ibn Abi Waqqas", "bn": "সাদ ইবনে আবি ওয়াক্কাস (রা.)"}', true, 3), ('4c04e996-ad15-5841-9988-cbc8f620a46f', '96c02bb5-86b8-5251-9820-8240dc2585a9', '{"en": "Abu Hurayrah", "bn": "আবু হুরায়রা (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('78f0976c-2846-5bbd-a374-9f2bc3c82e23', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "Which caliph was martyred in his house while reading the Quran?", "bn": "কোন খলিফা নিজ গৃহে কুরআন পাঠরত অবস্থায় শহিদ হন?"}', '{"en": "‘Uthman (RA) was besieged by rebels and martyred in 35 AH, his mushaf open before him.", "bn": "উসমান (রা.) বিদ্রোহীদের দ্বারা অবরুদ্ধ হয়ে ৩৫ হিজরিতে শহিদ হন, তখন তাঁর সামনে মুসহাফ খোলা ছিল।"}', 'Tarikh at-Tabari; al-Bidayah wan-Nihayah', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fc64798d-90da-500e-bdfe-754cf5395257', '78f0976c-2846-5bbd-a374-9f2bc3c82e23', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 1), ('25bc8bb9-2fd7-5232-ae7b-14b40e1b4755', '78f0976c-2846-5bbd-a374-9f2bc3c82e23', '{"en": "‘Umar", "bn": "উমর (রা.)"}', false, 2), ('6e10e528-e853-5cde-aedf-6ea3e8301ed6', '78f0976c-2846-5bbd-a374-9f2bc3c82e23', '{"en": "‘Ali", "bn": "আলী (রা.)"}', false, 3), ('38afce31-5d73-53e0-ab5b-f69e836f5f5b', '78f0976c-2846-5bbd-a374-9f2bc3c82e23', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('bd801e6b-8fa7-5822-a419-6e42a3e5c736', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "Which caliph made Kufa his capital?", "bn": "কোন খলিফা কুফাকে রাজধানী করেন?"}', '{"en": "‘Ali (RA) moved from Madinah to Kufa in Iraq.", "bn": "আলী (রা.) মদিনা থেকে ইরাকের কুফায় রাজধানী সরিয়ে নেন।"}', 'Tarikh at-Tabari', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0da046c2-5cb9-5dbe-bf28-f0f0c0d557b5', 'bd801e6b-8fa7-5822-a419-6e42a3e5c736', '{"en": "‘Ali", "bn": "আলী (রা.)"}', true, 1), ('58db2077-2a63-579d-aba2-c98766bb3c76', 'bd801e6b-8fa7-5822-a419-6e42a3e5c736', '{"en": "‘Umar", "bn": "উমর (রা.)"}', false, 2), ('5fe0a15a-d132-5d33-8c1f-7970b68b4b3f', 'bd801e6b-8fa7-5822-a419-6e42a3e5c736', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 3), ('12de2e3c-5b54-59ba-b51f-47e10aa8599d', 'bd801e6b-8fa7-5822-a419-6e42a3e5c736', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('34c510f5-439c-5d39-b82b-e1974cbe3eba', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "About how long was Abu Bakr’s caliphate?", "bn": "আবু বকর (রা.)-এর খিলাফতকাল প্রায় কত দিন?"}', '{"en": "From 11 AH to his death in 13 AH: about two years and three months.", "bn": "১১ হিজরি থেকে ১৩ হিজরিতে তাঁর ইন্তেকাল পর্যন্ত: প্রায় দুই বছর তিন মাস।"}', 'Tarikh at-Tabari', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8a26d9b1-3607-5d58-97c3-d639f9c8d218', '34c510f5-439c-5d39-b82b-e1974cbe3eba', '{"en": "Ten years", "bn": "দশ বছর"}', false, 1), ('c57d0125-46c3-592c-adbb-51e369e6b4d4', '34c510f5-439c-5d39-b82b-e1974cbe3eba', '{"en": "About two years", "bn": "প্রায় দুই বছর"}', true, 2), ('b2c9d787-f15c-5351-bd30-f114e86f426c', '34c510f5-439c-5d39-b82b-e1974cbe3eba', '{"en": "Six months", "bn": "ছয় মাস"}', false, 3), ('1e1a9ac8-c6d4-55dd-9012-8168b189aff9', '34c510f5-439c-5d39-b82b-e1974cbe3eba', '{"en": "Twelve years", "bn": "বারো বছর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a020e243-9ad7-5a7d-b737-1d84be8c0279', '3c81f1c1-994e-58ce-94f3-d9c71f63afcc', '{"en": "Which caliph was stabbed while leading the Fajr prayer?", "bn": "কোন খলিফা ফজরের নামাজে ইমামতি করার সময় ছুরিকাহত হন?"}', '{"en": "‘Umar (RA) was stabbed by Abu Lu’lu’ah while beginning the Fajr prayer and died days later (23 AH).", "bn": "উমর (রা.) ফজরের নামাজ শুরু করার সময় আবু লুলুর ছুরিকাঘাতে আহত হন এবং কিছুদিন পর (২৩ হিজরি) শহিদ হন।"}', 'Sahih al-Bukhari 3700', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3454a067-90b9-5c82-bf3a-df9ea8f4b979', 'a020e243-9ad7-5a7d-b737-1d84be8c0279', '{"en": "‘Uthman", "bn": "উসমান (রা.)"}', false, 1), ('bb4fb17f-1a64-5601-850d-6cab0e62c2ed', 'a020e243-9ad7-5a7d-b737-1d84be8c0279', '{"en": "Abu Bakr", "bn": "আবু বকর (রা.)"}', false, 2), ('66d1604e-1387-50e1-a269-09ff12ead409', 'a020e243-9ad7-5a7d-b737-1d84be8c0279', '{"en": "‘Umar", "bn": "উমর (রা.)"}', true, 3), ('1eea52ed-0e7c-557c-b7b0-f3e9763ce0ce', 'a020e243-9ad7-5a7d-b737-1d84be8c0279', '{"en": "Mu‘awiyah", "bn": "মুআবিয়া (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
