INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1d941339-0f77-5a5c-9dff-8e5cd39aed8d', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "The shrine of Hazrat Shah Makhdum Rupos is in…?", "bn": "হযরত শাহ মখদুম রূপোশ (রহ.)-এর মাজার কোথায়?"}', '{"en": "Shah Makhdum is remembered for spreading Islam in the Rajshahi region.", "bn": "শাহ মখদুম (রহ.) রাজশাহী অঞ্চলে ইসলাম প্রচারের জন্য স্মরণীয়।"}', 'Banglapedia: Shah Makhdum Rupos', 1) ON CONFLICT (id) DO NOTHING;
