INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('025b5d24-9ca1-5214-a911-225d24eb6379', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "Which sultan united Bengal and was called \"Shah-i-Bangalah\"?", "bn": "কোন সুলতান বাংলাকে ঐক্যবদ্ধ করে \"শাহ-ই-বাঙ্গালাহ\" উপাধি পান?"}', '{"en": "Ilyas Shah united the regions of Bengal around 1352 CE and founded the Ilyas Shahi dynasty.", "bn": "ইলিয়াস শাহ প্রায় ১৩৫২ খ্রিস্টাব্দে বাংলার অঞ্চলগুলোকে ঐক্যবদ্ধ করে ইলিয়াস শাহি বংশ প্রতিষ্ঠা করেন।"}', 'Banglapedia: Ilyas Shah', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fa5724fc-e3eb-5aa4-83ea-6fac2b737a40', '025b5d24-9ca1-5214-a911-225d24eb6379', '{"en": "Alauddin Husain Shah", "bn": "আলাউদ্দিন হোসেন শাহ"}', false, 1), ('88f6cdbd-b6ef-5e02-87bc-7102a0ae2222', '025b5d24-9ca1-5214-a911-225d24eb6379', '{"en": "Shamsuddin Ilyas Shah", "bn": "শামসুদ্দিন ইলিয়াস শাহ"}', true, 2), ('96d7ee3d-c7c7-5d53-bab7-77a6001b4d89', '025b5d24-9ca1-5214-a911-225d24eb6379', '{"en": "Bakhtiyar Khalji", "bn": "বখতিয়ার খলজি"}', false, 3), ('1f036004-db41-5d5c-9604-875310b3c2c7', '025b5d24-9ca1-5214-a911-225d24eb6379', '{"en": "Isa Khan", "bn": "ঈসা খাঁ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f8e553ca-a7a3-5660-91dc-28c3b53a6987', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "The Choto Sona Mosque (Small Golden Mosque) is in which district?", "bn": "ছোট সোনা মসজিদ কোন জেলায়?"}', '{"en": "It stands at Shibganj in Chapainawabganj, in the old Gaur area, from the time of Sultan Husain Shah.", "bn": "এটি চাঁপাইনবাবগঞ্জের শিবগঞ্জে, প্রাচীন গৌড় এলাকায়, সুলতান হোসেন শাহের আমলের।"}', 'Banglapedia: Chhota Sona Mosque', 3) ON CONFLICT (id) DO NOTHING;
