INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7ad91b2e-5216-5b0e-8e49-30c765867b13', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "Which Bengal sultan built the huge Adina Mosque at Pandua?", "bn": "পান্ডুয়ার বিশাল আদিনা মসজিদ কোন সুলতান নির্মাণ করেন?"}', '{"en": "Sultan Sikandar Shah, son of Ilyas Shah, built it in the 1370s; it was among the largest mosques of the subcontinent.", "bn": "ইলিয়াস শাহের পুত্র সুলতান সিকান্দার শাহ ১৩৭০-এর দশকে এটি নির্মাণ করেন; এটি উপমহাদেশের বৃহত্তম মসজিদগুলোর একটি ছিল।"}', 'Banglapedia: Adina Mosque', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('498a6c8e-5c52-5675-9c61-1cc85530f47f', '7ad91b2e-5216-5b0e-8e49-30c765867b13', '{"en": "Sikandar Shah", "bn": "সিকান্দার শাহ"}', true, 1), ('856c95c5-4ae5-5f91-9fd8-93e1cd571777', '7ad91b2e-5216-5b0e-8e49-30c765867b13', '{"en": "Ghiyasuddin Azam Shah", "bn": "গিয়াসউদ্দিন আজম শাহ"}', false, 2), ('39d2618a-9c7f-528e-b454-0d58ca0945b3', '7ad91b2e-5216-5b0e-8e49-30c765867b13', '{"en": "Shaista Khan", "bn": "শায়েস্তা খান"}', false, 3), ('14c6060a-12c8-5940-83c0-3e7ee075280e', '7ad91b2e-5216-5b0e-8e49-30c765867b13', '{"en": "Khan Jahan Ali", "bn": "খান জাহান আলী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b84465a8-f046-55bf-ad92-6d4580641b3a', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "Who wrote the beloved Eid song \"O mon Ramzaner oi rozar sheshe elo khushir Eid\"?", "bn": "\"ও মন রমজানের ওই রোজার শেষে এলো খুশির ঈদ\" গানটি কে লিখেছেন?"}', '{"en": "National poet Kazi Nazrul Islam wrote it, and Abbasuddin Ahmed first sang it; it is one of his many Islamic songs.", "bn": "জাতীয় কবি কাজী নজরুল ইসলাম এটি লেখেন, প্রথম গেয়েছিলেন আব্বাসউদ্দীন আহমদ; এটি তাঁর অসংখ্য ইসলামি গানের একটি।"}', 'Banglapedia: Kazi Nazrul Islam', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a4bf74ec-33ae-511d-b6de-a442426d521e', 'b84465a8-f046-55bf-ad92-6d4580641b3a', '{"en": "Rabindranath Tagore", "bn": "রবীন্দ্রনাথ ঠাকুর"}', false, 1), ('8eb5bc43-707e-5f2d-b4d8-6ddfeb69a589', 'b84465a8-f046-55bf-ad92-6d4580641b3a', '{"en": "Jasimuddin", "bn": "জসীমউদ্দীন"}', false, 2), ('56da98ab-6409-5391-811c-c4274cdb1212', 'b84465a8-f046-55bf-ad92-6d4580641b3a', '{"en": "Farrukh Ahmad", "bn": "ফররুখ আহমদ"}', false, 3), ('951f81cb-3544-502e-a29e-89bbfcd9b490', 'b84465a8-f046-55bf-ad92-6d4580641b3a', '{"en": "Kazi Nazrul Islam", "bn": "কাজী নজরুল ইসলাম"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b772c91f-111b-5bf7-9b71-7f295e898c6b', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "\"Bishad Sindhu\", the Bangla classic about the tragedy of Karbala, was written by…?", "bn": "কারবালার বিয়োগান্ত ঘটনা নিয়ে বাংলা ধ্রুপদি গ্রন্থ \"বিষাদ সিন্ধু\" কে লিখেছেন?"}', '{"en": "Mir Mosharraf Hossain published Bishad Sindhu in parts from 1885.", "bn": "মীর মশাররফ হোসেন ১৮৮৫ সাল থেকে খণ্ডে খণ্ডে বিষাদ সিন্ধু প্রকাশ করেন।"}', 'Banglapedia: Mir Mosharraf Hossain', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d92523ce-2f82-5e27-955d-3ca2bb81cff9', 'b772c91f-111b-5bf7-9b71-7f295e898c6b', '{"en": "Kazi Nazrul Islam", "bn": "কাজী নজরুল ইসলাম"}', false, 1), ('687779ab-00a0-5b95-997a-a93b7e075f5f', 'b772c91f-111b-5bf7-9b71-7f295e898c6b', '{"en": "Mir Mosharraf Hossain", "bn": "মীর মশাররফ হোসেন"}', true, 2), ('4a1ca99a-a9bc-582c-a6ca-555106b61e25', 'b772c91f-111b-5bf7-9b71-7f295e898c6b', '{"en": "Begum Rokeya", "bn": "বেগম রোকেয়া"}', false, 3), ('f134d285-bb8d-5726-89d8-1eef05f85254', 'b772c91f-111b-5bf7-9b71-7f295e898c6b', '{"en": "Ismail Hossain Siraji", "bn": "ইসমাইল হোসেন সিরাজী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('13842d6c-e33a-577d-b827-c743f0d36c26', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "Which saint, said to be a nephew of Shah Jalal, also has his shrine in Sylhet?", "bn": "শাহজালাল (রহ.)-এর ভাগ্নে হিসেবে পরিচিত কোন সাধকের মাজারও সিলেটে?"}', '{"en": "Shah Paran’s shrine is at Khadim Nagar on the edge of Sylhet city.", "bn": "শাহ পরান (রহ.)-এর মাজার সিলেট শহরের প্রান্তে খাদিমনগরে।"}', 'Banglapedia: Shah Paran', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e6b0f7de-1ab1-5aa7-bbeb-6256dd7380bb', '13842d6c-e33a-577d-b827-c743f0d36c26', '{"en": "Khan Jahan Ali", "bn": "খান জাহান আলী"}', false, 1), ('cfa17270-452f-5b7b-9c0f-b3a1eb14ea46', '13842d6c-e33a-577d-b827-c743f0d36c26', '{"en": "Shah Makhdum", "bn": "শাহ মখদুম"}', false, 2), ('8effa33b-220a-5733-ab1c-7d7df8eaa96d', '13842d6c-e33a-577d-b827-c743f0d36c26', '{"en": "Shah Paran", "bn": "শাহ পরান"}', true, 3), ('e7d0fa0f-0f0c-5427-ad57-e287ea3407ef', '13842d6c-e33a-577d-b827-c743f0d36c26', '{"en": "Shah Ali Baghdadi", "bn": "শাহ আলী বাগদাদি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('faa458db-adb7-53d6-a09a-02044c4f4db2', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "The Kusumba Mosque, a Sultanate-era stone mosque shown on the five-taka note, is in…?", "bn": "পাঁচ টাকার নোটে ছাপা সুলতানি আমলের পাথরের কুসুম্বা মসজিদ কোথায়?"}', '{"en": "It was built in 1558–59 at Manda, Naogaon, during the Afghan Sultanate.", "bn": "এটি ১৫৫৮–৫৯ সালে আফগান সুলতানি আমলে নওগাঁর মান্দায় নির্মিত।"}', 'Banglapedia: Kusumba Mosque', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a3740313-1e3d-5c69-a34a-8dd90915e7b3', 'faa458db-adb7-53d6-a09a-02044c4f4db2', '{"en": "Bagerhat", "bn": "বাগেরহাট"}', false, 1), ('2aa10067-d74f-55dd-9ffa-9f2cb82a323c', 'faa458db-adb7-53d6-a09a-02044c4f4db2', '{"en": "Sonargaon", "bn": "সোনারগাঁও"}', false, 2), ('38bd29f8-91da-5842-9285-fb2fd5085ff4', 'faa458db-adb7-53d6-a09a-02044c4f4db2', '{"en": "Old Dhaka", "bn": "পুরান ঢাকা"}', false, 3), ('7a03cb7c-060e-5c17-94b2-aafbeb519e61', 'faa458db-adb7-53d6-a09a-02044c4f4db2', '{"en": "Naogaon", "bn": "নওগাঁ"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0aa28bf3-1ca6-593c-9bd0-2a2e3b7d286f', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "Which sultan of Bengal (1494–1519) is remembered for supporting Bangla literature?", "bn": "বাংলার কোন সুলতান (১৪৯৪–১৫১৯) বাংলা সাহিত্যের পৃষ্ঠপোষকতার জন্য স্মরণীয়?"}', '{"en": "Husain Shah’s reign is called a golden age of Bengal; poets wrote in Bangla under his patronage.", "bn": "হোসেন শাহের শাসনকালকে বাংলার স্বর্ণযুগ বলা হয়; তাঁর পৃষ্ঠপোষকতায় কবিরা বাংলায় লিখতেন।"}', 'Banglapedia: Husain Shah', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('36cef577-b056-58e6-aa3a-43932275fe01', '0aa28bf3-1ca6-593c-9bd0-2a2e3b7d286f', '{"en": "Alauddin Husain Shah", "bn": "আলাউদ্দিন হোসেন শাহ"}', true, 1), ('b2de5598-dde3-5453-96be-bf8025e29648', '0aa28bf3-1ca6-593c-9bd0-2a2e3b7d286f', '{"en": "Sikandar Shah", "bn": "সিকান্দার শাহ"}', false, 2), ('b52af541-ecbf-5e8f-b2a1-151a94f0c09a', '0aa28bf3-1ca6-593c-9bd0-2a2e3b7d286f', '{"en": "Murshid Quli Khan", "bn": "মুর্শিদ কুলি খান"}', false, 3), ('a4cddf86-b5ea-5031-8ba2-bbe1ef737203', '0aa28bf3-1ca6-593c-9bd0-2a2e3b7d286f', '{"en": "Siraj ud-Daulah", "bn": "সিরাজউদ্দৌলা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1b446262-d735-5f08-b139-94d43bf1d721', '81b44d3d-2da9-509c-a5c1-5bef99273b98', '{"en": "Sonargaon, an old capital of Bengal, is in which district today?", "bn": "বাংলার প্রাচীন রাজধানী সোনারগাঁও বর্তমানে কোন জেলায়?"}', '{"en": "Sonargaon was the seat of Fakhruddin Mubarak Shah and a great centre of trade and learning.", "bn": "সোনারগাঁও ছিল ফখরুদ্দিন মুবারক শাহের রাজধানী এবং বাণিজ্য ও শিক্ষার বড় কেন্দ্র।"}', 'Banglapedia: Sonargaon', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8b546452-54f0-5bfc-b58b-359f37f91526', '1b446262-d735-5f08-b139-94d43bf1d721', '{"en": "Gazipur", "bn": "গাজীপুর"}', false, 1), ('5b627cd4-25fc-59f8-b74c-9cfeb1c09173', '1b446262-d735-5f08-b139-94d43bf1d721', '{"en": "Narayanganj", "bn": "নারায়ণগঞ্জ"}', true, 2), ('30da63b2-18fa-5daa-a5f0-48e6f5f62fed', '1b446262-d735-5f08-b139-94d43bf1d721', '{"en": "Munshiganj", "bn": "মুন্সিগঞ্জ"}', false, 3), ('527d1696-8d7f-5ea6-afa8-858451dafc01', '1b446262-d735-5f08-b139-94d43bf1d721', '{"en": "Narsingdi", "bn": "নরসিংদী"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('d88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Get to know the surahs", "bn": "সূরা পরিচিতি"}', 'quran', 'medium', NULL, 10, 'in_review', 121) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9231ae8e-8280-51d8-99d3-21bad2dc99a6', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Which surah of thirty ayahs intercedes for its reader until he is forgiven?", "bn": "ত্রিশ আয়াতের কোন সূরা তার পাঠকের জন্য সুপারিশ করবে, যতক্ষণ না তাকে ক্ষমা করা হয়?"}', '{"en": "\"A surah of the Quran of thirty ayahs interceded for a man until he was forgiven: Tabarakalladhi biyadihil-mulk.\"", "bn": "\"কুরআনের ত্রিশ আয়াতের একটি সূরা এক ব্যক্তির জন্য সুপারিশ করেছে, অবশেষে তাকে ক্ষমা করা হয়েছে: তাবারাকাল্লাযি বিয়াদিহিল মুলক।\""}', 'Jami‘ at-Tirmidhi 2891; Sunan Abi Dawud 1400', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('468d8d61-e7d3-54fe-87ee-14964fc859e2', '9231ae8e-8280-51d8-99d3-21bad2dc99a6', '{"en": "Al-Mulk", "bn": "আল-মুলক"}', true, 1), ('b0b7327c-c515-5fe7-a94f-4779660422f0', '9231ae8e-8280-51d8-99d3-21bad2dc99a6', '{"en": "Yasin", "bn": "ইয়াসিন"}', false, 2), ('21e5820c-9ba1-5d88-b9a2-7d8e7cf64ebd', '9231ae8e-8280-51d8-99d3-21bad2dc99a6', '{"en": "Ar-Rahman", "bn": "আর-রহমান"}', false, 3), ('3edd7fde-ed43-5668-91bf-e4a2c19308f3', '9231ae8e-8280-51d8-99d3-21bad2dc99a6', '{"en": "Al-Waqi‘ah", "bn": "আল-ওয়াকিআ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ec1f644b-708b-56e7-b219-168556b01aa0', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Memorising the first ten ayahs of which surah protects from the Dajjal?", "bn": "কোন সূরার প্রথম দশ আয়াত মুখস্থ করলে দাজ্জাল থেকে সুরক্ষা পাওয়া যায়?"}', '{"en": "\"Whoever memorises ten ayahs from the beginning of Surah al-Kahf will be protected from the Dajjal.\"", "bn": "\"যে সূরা কাহফের প্রথম দশ আয়াত মুখস্থ করবে, সে দাজ্জাল থেকে সুরক্ষিত থাকবে।\""}', 'Sahih Muslim 809', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('99b5d4ed-f388-5d88-8bac-636d06d1d06e', 'ec1f644b-708b-56e7-b219-168556b01aa0', '{"en": "Al-Baqarah", "bn": "আল-বাকারা"}', false, 1), ('e61a3f0b-f874-5cfd-abde-e4ea9d594dcc', 'ec1f644b-708b-56e7-b219-168556b01aa0', '{"en": "Yusuf", "bn": "ইউসুফ"}', false, 2), ('ecca9f7e-44de-51c1-b275-33e81d3d9c79', 'ec1f644b-708b-56e7-b219-168556b01aa0', '{"en": "Al-Kahf", "bn": "আল-কাহফ"}', true, 3), ('4711805a-69ee-5460-a6e5-253a875badbd', 'ec1f644b-708b-56e7-b219-168556b01aa0', '{"en": "Maryam", "bn": "মারইয়াম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4dd2ac60-ddff-5c1f-8c85-166522789a7c', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "The last two ayahs of which surah are enough for whoever recites them at night?", "bn": "কোন সূরার শেষ দুই আয়াত রাতে পড়লে তা পাঠকের জন্য যথেষ্ট হয়?"}', '{"en": "\"Whoever recites the last two ayahs of Surah al-Baqarah at night, they will suffice him.\"", "bn": "\"যে রাতে সূরা বাকারার শেষ দুই আয়াত পড়বে, তা তার জন্য যথেষ্ট হবে।\""}', 'Sahih al-Bukhari 5009', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3d477907-d396-5864-bce3-abc1ccd3efc8', '4dd2ac60-ddff-5c1f-8c85-166522789a7c', '{"en": "Al-Mulk", "bn": "আল-মুলক"}', false, 1), ('026409bb-bdcd-55cc-b420-dc6766763a92', '4dd2ac60-ddff-5c1f-8c85-166522789a7c', '{"en": "Al-Baqarah", "bn": "আল-বাকারা"}', true, 2), ('c88ed139-8dfe-55ac-9e21-294e074fb2a9', '4dd2ac60-ddff-5c1f-8c85-166522789a7c', '{"en": "Al Imran", "bn": "আলে ইমরান"}', false, 3), ('61a4459c-b891-5378-830a-b0465b593287', '4dd2ac60-ddff-5c1f-8c85-166522789a7c', '{"en": "Al-Hashr", "bn": "আল-হাশর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3737dc8d-75fe-594d-a07c-2958c6d3c258', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Which surah is named after a woman?", "bn": "কোন সূরার নাম একজন নারীর নামে?"}', '{"en": "Surah Maryam (19) is the only surah named after a woman, the mother of Isa (AS).", "bn": "সূরা মারইয়াম (১৯) একমাত্র সূরা যার নাম একজন নারীর নামে — ঈসা (আ.)-এর মা।"}', 'Quran 19', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('642fd60e-ad10-5050-8b43-0eeacaba341b', '3737dc8d-75fe-594d-a07c-2958c6d3c258', '{"en": "An-Nisa", "bn": "আন-নিসা"}', false, 1), ('f2161d99-0eac-5174-96aa-73088c1da3f3', '3737dc8d-75fe-594d-a07c-2958c6d3c258', '{"en": "Al-Mumtahanah", "bn": "আল-মুমতাহিনা"}', false, 2), ('be754e8d-9338-5819-832f-2cb7e56af6f3', '3737dc8d-75fe-594d-a07c-2958c6d3c258', '{"en": "Al-Mujadilah", "bn": "আল-মুজাদালা"}', false, 3), ('40688e3c-8092-5bf0-aedb-3653a18e86c1', '3737dc8d-75fe-594d-a07c-2958c6d3c258', '{"en": "Maryam", "bn": "মারইয়াম"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9bb9df5b-c25e-5f6c-9870-60a68949ac81', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Which surah has a wise man’s advice to his son: \"Do not associate anything with Allah\"?", "bn": "কোন সূরায় এক জ্ঞানী পিতার পুত্রকে উপদেশ আছে: \"আল্লাহর সঙ্গে কাউকে শরিক কোরো না\"?"}', '{"en": "\"And when Luqman said to his son, advising him: O my son, do not associate anything with Allah…\"", "bn": "\"আর যখন লুকমান তার পুত্রকে উপদেশ দিয়ে বলল: হে আমার পুত্র, আল্লাহর সঙ্গে কোনো শরিক কোরো না…\""}', 'Quran 31:13', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d0b140f2-0d56-5eb9-860d-5b489ef9c273', '9bb9df5b-c25e-5f6c-9870-60a68949ac81', '{"en": "Luqman", "bn": "লুকমান"}', true, 1), ('8de46cdf-cb59-5fcd-822c-a7e80a893b56', '9bb9df5b-c25e-5f6c-9870-60a68949ac81', '{"en": "Yusuf", "bn": "ইউসুফ"}', false, 2), ('5b067d94-71fd-506d-955e-eb658a4f07ec', '9bb9df5b-c25e-5f6c-9870-60a68949ac81', '{"en": "Ibrahim", "bn": "ইবরাহিম"}', false, 3), ('2c11f04a-eb20-55de-9c28-e842a3e6fa85', '9bb9df5b-c25e-5f6c-9870-60a68949ac81', '{"en": "Nuh", "bn": "নূহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5bc9be31-4485-5c39-843b-745f4a0f0e7e', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "\"We relate to you the best of stories\" opens the story in which surah?", "bn": "\"আমি আপনার কাছে সর্বোত্তম কাহিনি বর্ণনা করছি\" — কোন সূরার কাহিনির শুরুতে?"}', '{"en": "Surah Yusuf (12:3) tells one whole story from start to end.", "bn": "সূরা ইউসুফ (১২:৩) শুরু থেকে শেষ পর্যন্ত একটি পূর্ণ কাহিনি বলে।"}', 'Quran 12:3', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('40dc0dec-55b0-5b24-9d69-1ab9cea23ac8', '5bc9be31-4485-5c39-843b-745f4a0f0e7e', '{"en": "Al-Kahf", "bn": "আল-কাহফ"}', false, 1), ('f0e467e9-25f6-5230-8f33-3a51f6d2024d', '5bc9be31-4485-5c39-843b-745f4a0f0e7e', '{"en": "Al-Qasas", "bn": "আল-কাসাস"}', false, 2), ('0d8e5aa9-3f4c-58c3-a403-cd15ae726674', '5bc9be31-4485-5c39-843b-745f4a0f0e7e', '{"en": "Yusuf", "bn": "ইউসুফ"}', true, 3), ('ff49f577-525f-502c-914a-ffe29bc7edbc', '5bc9be31-4485-5c39-843b-745f4a0f0e7e', '{"en": "Ta-Ha", "bn": "ত্বা-হা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6d168796-9567-5ff7-9c9a-0e8c50b30908', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Which surah was revealed about the Battle of Badr?", "bn": "কোন সূরা বদর যুদ্ধ সম্পর্কে নাজিল হয়?"}', '{"en": "Ibn ‘Abbas (RA) said Surah al-Anfal was revealed about Badr.", "bn": "ইবনে আব্বাস (রা.) বলেন, সূরা আনফাল বদর সম্পর্কে নাজিল হয়েছে।"}', 'Sahih al-Bukhari 4645', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e3e600f2-893b-5323-b328-69515f63c035', '6d168796-9567-5ff7-9c9a-0e8c50b30908', '{"en": "Al-Ahzab", "bn": "আল-আহযাব"}', false, 1), ('740481fd-7fdf-5596-8a4b-7dbc2435b456', '6d168796-9567-5ff7-9c9a-0e8c50b30908', '{"en": "Al-Anfal", "bn": "আল-আনফাল"}', true, 2), ('91f72306-7370-513f-bf83-5269f4f45e63', '6d168796-9567-5ff7-9c9a-0e8c50b30908', '{"en": "Al-Fath", "bn": "আল-ফাতহ"}', false, 3), ('6a8e96c1-f9ab-5c7f-85c7-29e1e031ee06', '6d168796-9567-5ff7-9c9a-0e8c50b30908', '{"en": "Al-Hashr", "bn": "আল-হাশর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('df9c1314-73bb-5f41-a478-76df2e53c66c', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Which surah begins \"Indeed, We have given you a clear victory\", revealed after Hudaybiyah?", "bn": "হুদাইবিয়ার পর নাজিল হওয়া কোন সূরা \"নিশ্চয় আমি আপনাকে সুস্পষ্ট বিজয় দিয়েছি\" দিয়ে শুরু?"}', '{"en": "He ﷺ said: \"A surah has been revealed to me tonight that is dearer to me than everything the sun rises upon.\"", "bn": "নবী ﷺ বললেন: \"আজ রাতে আমার ওপর এমন একটি সূরা নাজিল হয়েছে, যা সূর্য যার ওপর উদিত হয় তার সবকিছুর চেয়ে আমার কাছে প্রিয়।\""}', 'Quran 48:1; Sahih al-Bukhari 4833', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c1fefc6b-83c6-5651-b939-d14adb94de56', 'df9c1314-73bb-5f41-a478-76df2e53c66c', '{"en": "An-Nasr", "bn": "আন-নাসর"}', false, 1), ('8b2a74a4-d5cd-56bd-815b-728ef2bcafa3', 'df9c1314-73bb-5f41-a478-76df2e53c66c', '{"en": "Al-Fajr", "bn": "আল-ফাজর"}', false, 2), ('d9233ec0-837a-5cbe-8d3b-e6fbbb4837e7', 'df9c1314-73bb-5f41-a478-76df2e53c66c', '{"en": "Al-Mulk", "bn": "আল-মুলক"}', false, 3), ('50956bbc-e72e-51fe-b6bd-91b25104a396', 'df9c1314-73bb-5f41-a478-76df2e53c66c', '{"en": "Al-Fath", "bn": "আল-ফাতহ"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d4c98610-34eb-5739-8a82-26d297ea80a4', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Which surah is also called \"Bani Isra’il\"?", "bn": "কোন সূরার আরেক নাম \"বনি ইসরাইল\"?"}', '{"en": "Ibn Mas‘ud (RA) named \"Bani Isra’il, al-Kahf, Maryam…\" among the earliest surahs he learned.", "bn": "ইবনে মাসউদ (রা.) \"বনি ইসরাইল, কাহফ, মারইয়াম…\"-কে তাঁর প্রথম দিকে শেখা সূরার মধ্যে উল্লেখ করেছেন।"}', 'Sahih al-Bukhari 4708', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a1189209-e2e8-5145-836d-f1d8e995f890', 'd4c98610-34eb-5739-8a82-26d297ea80a4', '{"en": "Al-Isra’", "bn": "আল-ইসরা"}', true, 1), ('78e8bbc3-7012-54ee-b948-550feab649d6', 'd4c98610-34eb-5739-8a82-26d297ea80a4', '{"en": "Al-Baqarah", "bn": "আল-বাকারা"}', false, 2), ('cf3092ea-67be-56d5-b4d9-d345111473fc', 'd4c98610-34eb-5739-8a82-26d297ea80a4', '{"en": "Al-Ma’idah", "bn": "আল-মায়িদা"}', false, 3), ('32dca9d1-8c4e-59ed-8f40-fd8ed3ceb1db', 'd4c98610-34eb-5739-8a82-26d297ea80a4', '{"en": "Ta-Ha", "bn": "ত্বা-হা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c650aca9-3308-5acf-b109-1ae5f12d4b14', 'd88da883-6056-582f-a9bd-51cc202cc3eb', '{"en": "Which surah teaches: do not raise your voices above the Prophet’s, and verify news brought by a sinner?", "bn": "কোন সূরা শেখায়: নবীর কণ্ঠের ওপর কণ্ঠ উঁচু কোরো না, আর ফাসিক খবর আনলে যাচাই করো?"}', '{"en": "Al-Hujurat (49) is a surah of manners: voices (49:2), checking news (49:6), mocking and backbiting (49:11–12).", "bn": "সূরা হুজুরাত (৪৯) আদবের সূরা: কণ্ঠস্বর (৪৯:২), সংবাদ যাচাই (৪৯:৬), উপহাস ও গিবত (৪৯:১১–১২)।"}', 'Quran 49:2; Quran 49:6', 10) ON CONFLICT (id) DO NOTHING;
