INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('bc90d91c-c68b-56a9-a300-d349ea6d0fa5', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "According to Ibn ‘Abbas, which was the last complete surah to be revealed?", "bn": "ইবনে আব্বাস (রা.)-এর মতে পূর্ণাঙ্গ সূরা হিসেবে সর্বশেষ কোনটি নাজিল হয়?"}', '{"en": "Ibn ‘Abbas (RA): \"The last surah revealed all at once was: Idha ja’a nasrullahi wal-fath.\"", "bn": "ইবনে আব্বাস (রা.): \"একসঙ্গে নাজিল হওয়া সর্বশেষ সূরা: ইযা জা-আ নাসরুল্লাহি ওয়াল ফাতহ।\""}', 'Sahih Muslim 3024', 1) ON CONFLICT (id) DO NOTHING;
