INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('03210b5c-f0e7-5a94-bf39-912829bd6626', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah begins with a woman pleading with the Prophet ﷺ about her husband?", "bn": "কোন সূরা শুরু হয়েছে স্বামীর ব্যাপারে নবী ﷺ-এর কাছে এক নারীর আবেদন দিয়ে?"}', '{"en": "\"Allah has heard the words of the woman who pleads with you about her husband…\"", "bn": "\"আল্লাহ সেই নারীর কথা শুনেছেন, যে তার স্বামীর বিষয়ে আপনার সঙ্গে বাদানুবাদ করছিল…\""}', 'Quran 58:1', 2) ON CONFLICT (id) DO NOTHING;
