INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('edff9e46-5a82-5833-8717-8cb2e2f75910', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah is also called \"Bara’ah\"?", "bn": "কোন সূরার আরেক নাম \"বারাআত\"?"}', '{"en": "At-Tawbah opens with \"Bara’ah\" (a declaration of disassociation); al-Bara’ (RA) mentions it by that name.", "bn": "সূরা তাওবা শুরু হয় \"বারাআত\" (সম্পর্কচ্ছেদের ঘোষণা) দিয়ে; বারা (রা.) এ নামেই উল্লেখ করেছেন।"}', 'Quran 9:1; Sahih al-Bukhari 4654', 3) ON CONFLICT (id) DO NOTHING;
