INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7604437f-83dd-5577-a0cf-7b380fb6ca02', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah opens: \"The Hour has drawn near and the moon has split\"?", "bn": "কোন সূরা শুরু হয়: \"কিয়ামত নিকটবর্তী হয়েছে এবং চাঁদ দ্বিখণ্ডিত হয়েছে\"?"}', '{"en": "Surah al-Qamar (\"the Moon\"), 54:1.", "bn": "সূরা আল-কামার (\"চাঁদ\"), ৫৪:১।"}', 'Quran 54:1', 4) ON CONFLICT (id) DO NOTHING;
