INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a4f787ce-c9df-5527-b71e-eabc71ad0518', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah tells of the People of the Ditch (Ashab al-Ukhdud)?", "bn": "কোন সূরায় গর্তওয়ালাদের (আসহাবুল উখদুদ) কাহিনি আছে?"}', '{"en": "\"Cursed were the people of the ditch, the fire full of fuel…\"", "bn": "\"ধ্বংস হয়েছে গর্তওয়ালারা, ইন্ধনপূর্ণ আগুনের…\""}', 'Quran 85:4–5', 5) ON CONFLICT (id) DO NOTHING;
