INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('314b0ee0-12f0-5f7d-91cc-d789e3b3d09d', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah describes the Day when people will be like scattered moths?", "bn": "কোন সূরায় সেই দিনের বর্ণনা আছে, যেদিন মানুষ বিক্ষিপ্ত পতঙ্গের মতো হবে?"}', '{"en": "\"The Day when people will be like scattered moths, and the mountains like carded wool.\"", "bn": "\"যেদিন মানুষ হবে বিক্ষিপ্ত পতঙ্গের মতো, আর পাহাড় হবে ধুনা রঙিন পশমের মতো।\""}', 'Quran 101:4–5', 6) ON CONFLICT (id) DO NOTHING;
