INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5c49d3f5-1b84-5b40-9535-c367ab569fa0', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah ends by mentioning \"the scriptures of Ibrahim and Musa\"?", "bn": "কোন সূরার শেষে \"ইবরাহিম ও মুসার সহিফা\"-র উল্লেখ আছে?"}', '{"en": "\"…and the Hereafter is better and more lasting. This is in the former scriptures, the scriptures of Ibrahim and Musa.\"", "bn": "\"…আর আখিরাত উত্তম ও স্থায়ী। নিশ্চয় এটি আছে পূর্ববর্তী সহিফাসমূহে, ইবরাহিম ও মুসার সহিফায়।\""}', 'Quran 87:17–19', 7) ON CONFLICT (id) DO NOTHING;
