INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e52520f9-508e-5d23-be65-cd8a2fb1fe14', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah begins \"O you wrapped in garments, stand (in prayer) at night, except a little\"?", "bn": "কোন সূরা শুরু হয় \"হে বস্ত্রাবৃত, রাতে (নামাজে) দাঁড়াও, সামান্য অংশ ছাড়া\"?"}', '{"en": "Al-Muzzammil 73:1–2 calls the Prophet ﷺ to the night prayer.", "bn": "আল-মুযযাম্মিল ৭৩:১–২ নবী ﷺ-কে রাতের নামাজের দিকে আহ্বান করে।"}', 'Quran 73:1–2', 8) ON CONFLICT (id) DO NOTHING;
