INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0f581259-88c5-53ec-a319-f2266ba6182d', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah is named after consultation, praising those \"whose affair is by consultation among them\"?", "bn": "কোন সূরার নাম পরামর্শের নামে, যেখানে প্রশংসা আছে \"যাদের কাজ পারস্পরিক পরামর্শের ভিত্তিতে হয়\"?"}', '{"en": "\"…and whose affair is (decided by) consultation (shura) among them.\"", "bn": "\"…আর যাদের কাজ পারস্পরিক পরামর্শের (শূরা) ভিত্তিতে হয়।\""}', 'Quran 42:38', 9) ON CONFLICT (id) DO NOTHING;
