INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('bab050f2-08f6-5fa1-bcf1-cc83aa0f2816', 'c17b0696-842c-5c0b-8f18-1d3d4baac84b', '{"en": "Which surah ends: \"Whoever does an atom’s weight of good will see it\"?", "bn": "কোন সূরার শেষে আছে: \"কেউ অণু পরিমাণ সৎকাজ করলে তা দেখতে পাবে\"?"}', '{"en": "\"So whoever does an atom’s weight of good will see it, and whoever does an atom’s weight of evil will see it.\"", "bn": "\"অতএব কেউ অণু পরিমাণ সৎকাজ করলে তা দেখবে, আর কেউ অণু পরিমাণ অসৎকাজ করলে তাও দেখবে।\""}', 'Quran 99:7–8', 10) ON CONFLICT (id) DO NOTHING;
