INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5ddc5c73-713a-561f-8f59-d250ac480d04', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "A hadith narrated by both al-Bukhari and Muslim is called…?", "bn": "যে হাদিস বুখারি ও মুসলিম উভয়েই বর্ণনা করেছেন, তাকে কী বলে?"}', '{"en": "Muttafaqun ‘alayh = \"agreed upon\" by the two Sahihs.", "bn": "মুত্তাফাকুন আলাইহি = দুই সহিহ গ্রন্থের \"ঐকমত্যপূর্ণ\"।"}', 'Terms of hadith science (mustalah al-hadith)', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f39264e7-8469-56d4-b04d-245215370fd9', '5ddc5c73-713a-561f-8f59-d250ac480d04', '{"en": "Mawdu‘", "bn": "মাওজু"}', false, 1), ('9dff5683-6572-57d9-8891-d06f78fa04b9', '5ddc5c73-713a-561f-8f59-d250ac480d04', '{"en": "Muttafaqun ‘alayh", "bn": "মুত্তাফাকুন আলাইহি"}', true, 2), ('516ab453-be97-552a-bdd3-10e45deef46e', '5ddc5c73-713a-561f-8f59-d250ac480d04', '{"en": "Mursal", "bn": "মুরসাল"}', false, 3), ('6235ecb9-ddf8-5600-a514-9ee07af3c826', '5ddc5c73-713a-561f-8f59-d250ac480d04', '{"en": "Gharib", "bn": "গরিব"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('71942c03-690e-5740-8efa-d1c2630de183', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "A fabricated \"hadith\", falsely attributed to the Prophet ﷺ, is called…?", "bn": "নবী ﷺ-এর নামে মিথ্যা বানানো \"হাদিস\"-কে কী বলে?"}', '{"en": "\"Whoever lies about me deliberately, let him take his seat in the Fire.\"", "bn": "\"যে ইচ্ছাকৃতভাবে আমার নামে মিথ্যা বলে, সে যেন জাহান্নামে তার ঠিকানা বানিয়ে নেয়।\""}', 'Sahih al-Bukhari 110', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('876c5d0a-bc8f-57d2-b9e5-3fad795200d1', '71942c03-690e-5740-8efa-d1c2630de183', '{"en": "Sahih", "bn": "সহিহ"}', false, 1), ('0dc5f85d-6e8a-542a-9d32-89f793e2ab14', '71942c03-690e-5740-8efa-d1c2630de183', '{"en": "Hasan", "bn": "হাসান"}', false, 2), ('c87a6ea5-bc07-527c-9fd3-048ebac7dd27', '71942c03-690e-5740-8efa-d1c2630de183', '{"en": "Mawdu‘", "bn": "মাওজু (জাল)"}', true, 3), ('38632d9b-92b8-5ca7-ac31-7dd177194605', '71942c03-690e-5740-8efa-d1c2630de183', '{"en": "Mutawatir", "bn": "মুতাওয়াতির"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5eac536f-2f34-5787-925d-92e3384ca9c8', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "A hadith with a defect in its chain, below the level of hasan, is called…?", "bn": "যে হাদিসের সনদে ত্রুটি আছে এবং যা হাসানের স্তরে পৌঁছায় না, তাকে কী বলে?"}', '{"en": "Hadith are graded sahih (sound), hasan (good) and da‘if (weak).", "bn": "হাদিসের প্রধান স্তর: সহিহ (বিশুদ্ধ), হাসান (উত্তম) ও জয়িফ (দুর্বল)।"}', 'Terms of hadith science (mustalah al-hadith)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e1472c44-b6b5-534b-99d7-f94fb75f80b5', '5eac536f-2f34-5787-925d-92e3384ca9c8', '{"en": "Da‘if (weak)", "bn": "জয়িফ (দুর্বল)"}', true, 1), ('ae12a2c6-8e2c-51af-9af0-208d7ed30b7d', '5eac536f-2f34-5787-925d-92e3384ca9c8', '{"en": "Sahih", "bn": "সহিহ"}', false, 2), ('88ac5da2-c826-5a11-bdc2-c0741b3fa46b', '5eac536f-2f34-5787-925d-92e3384ca9c8', '{"en": "Qudsi", "bn": "কুদসি"}', false, 3), ('f479cd73-11f5-5e6c-9988-ead7aa498203', '5eac536f-2f34-5787-925d-92e3384ca9c8', '{"en": "Muttafaqun ‘alayh", "bn": "মুত্তাফাকুন আলাইহি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5bc36ba9-e679-5366-aa9d-b792ecd19ada', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "A hadith narrated by so many people in every generation that they could not have agreed on a lie is…?", "bn": "প্রতিটি স্তরে এত বেশি মানুষ বর্ণনা করেছেন যে মিথ্যায় একমত হওয়া অসম্ভব — এমন হাদিসকে কী বলে?"}', '{"en": "Mutawatir reports give certain knowledge, like the hadith \"Whoever lies about me deliberately…\".", "bn": "মুতাওয়াতির বর্ণনা নিশ্চিত জ্ঞান দেয়, যেমন \"যে ইচ্ছাকৃতভাবে আমার নামে মিথ্যা বলে…\" হাদিস।"}', 'Terms of hadith science (mustalah al-hadith)', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('21a7bd3d-f4c6-5e64-802a-6dd9843cb5ae', '5bc36ba9-e679-5366-aa9d-b792ecd19ada', '{"en": "Ahad", "bn": "আহাদ"}', false, 1), ('c8bc1108-a802-57de-9315-ea20dc13bf61', '5bc36ba9-e679-5366-aa9d-b792ecd19ada', '{"en": "Mursal", "bn": "মুরসাল"}', false, 2), ('585d8377-7478-58bc-ac54-74d7255f526b', '5bc36ba9-e679-5366-aa9d-b792ecd19ada', '{"en": "Mawquf", "bn": "মাওকুফ"}', false, 3), ('60e4c121-795c-5bd8-b070-ac35d8a27baf', '5bc36ba9-e679-5366-aa9d-b792ecd19ada', '{"en": "Mutawatir", "bn": "মুতাওয়াতির"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7baada64-e741-59f6-a929-ba934f3b766a', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "What is the first hadith in Sahih al-Bukhari about?", "bn": "সহিহ বুখারির প্রথম হাদিস কোন বিষয়ে?"}', '{"en": "Al-Bukhari opened his book with the hadith of intention.", "bn": "ইমাম বুখারি তাঁর গ্রন্থ নিয়তের হাদিস দিয়ে শুরু করেছেন।"}', 'Sahih al-Bukhari 1', 5) ON CONFLICT (id) DO NOTHING;
