INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('46e3bf8f-bad6-56ef-b89e-7176c06c5a55', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "Which companion narrated \"Actions are only by intentions\"?", "bn": "কোন সাহাবি \"সকল কাজ নিয়তের ওপর নির্ভরশীল\" হাদিসটি বর্ণনা করেছেন?"}', '{"en": "‘Umar (RA) said it on the minbar, from the Prophet ﷺ.", "bn": "উমর (রা.) মিম্বারে দাঁড়িয়ে নবী ﷺ থেকে এটি বর্ণনা করেন।"}', 'Sahih al-Bukhari 1', 6) ON CONFLICT (id) DO NOTHING;
