INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4fdbf48d-1aa3-5287-ae7b-cb8a8810504a', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "Imam an-Nawawi’s famous \"Forty Hadith\" actually contains how many hadith?", "bn": "ইমাম নববির বিখ্যাত \"চল্লিশ হাদিস\"-এ আসলে কয়টি হাদিস আছে?"}', '{"en": "Al-Arba‘un an-Nawawiyyah has forty-two hadith; the name keeps the round number.", "bn": "আল-আরবাঈন আন-নাবাবিয়্যাহতে বিয়াল্লিশটি হাদিস আছে; নামটি গোল সংখ্যা ধরে রাখা।"}', 'Al-Arba‘un an-Nawawiyyah', 7) ON CONFLICT (id) DO NOTHING;
