INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2977996f-83d4-59fd-a324-30732290c843', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "Imam al-Bukhari was born in which city?", "bn": "ইমাম বুখারি কোন শহরে জন্মগ্রহণ করেন?"}', '{"en": "Muhammad ibn Isma‘il al-Bukhari was born in Bukhara (in today’s Uzbekistan) in 194 AH.", "bn": "মুহাম্মাদ ইবনে ইসমাইল আল-বুখারি ১৯৪ হিজরিতে বুখারায় (বর্তমান উজবেকিস্তান) জন্মগ্রহণ করেন।"}', 'Siyar A‘lam an-Nubala’', 8) ON CONFLICT (id) DO NOTHING;
