INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('cd347625-7bfb-5b2b-8560-d730fca3f57b', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "The Sunnah is the Prophet’s ﷺ words, actions and…?", "bn": "সুন্নাহ হলো নবী ﷺ-এর কথা, কাজ এবং…?"}', '{"en": "Taqrir: something done in his presence that he saw and did not object to.", "bn": "তাকরির: তাঁর সামনে কিছু করা হলো, তিনি দেখলেন এবং আপত্তি করলেন না।"}', 'Terms of hadith science (mustalah al-hadith)', 9) ON CONFLICT (id) DO NOTHING;
