INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4c841ba4-6f6a-5bfa-8861-163692e60b6f', 'f6c1a7fc-63d9-5e33-875d-c9f3ca2b6166', '{"en": "Which woman narrated the most hadith?", "bn": "কোন নারী সবচেয়ে বেশি হাদিস বর্ণনা করেছেন?"}', '{"en": "‘A’ishah (RA) is among the companions who narrated the most hadith, and the foremost among women.", "bn": "আয়েশা (রা.) সর্বাধিক হাদিস বর্ণনাকারী সাহাবিদের একজন এবং নারীদের মধ্যে শীর্ষে।"}', 'Siyar A‘lam an-Nubala’', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('688e501c-4829-52a1-8085-9a89afb0bdcb', '4c841ba4-6f6a-5bfa-8861-163692e60b6f', '{"en": "‘A’ishah", "bn": "আয়েশা (রা.)"}', true, 1), ('5ffe5605-bb6b-5221-8f69-141342fe0bc2', '4c841ba4-6f6a-5bfa-8861-163692e60b6f', '{"en": "Fatimah", "bn": "ফাতিমা (রা.)"}', false, 2), ('ca19fcb7-ed2a-5ac1-9742-9285e17651fa', '4c841ba4-6f6a-5bfa-8861-163692e60b6f', '{"en": "Khadijah", "bn": "খাদিজা (রা.)"}', false, 3), ('0150e9c5-d4fb-5ea5-bff5-e9c1763e0a11', '4c841ba4-6f6a-5bfa-8861-163692e60b6f', '{"en": "Asma’", "bn": "আসমা (রা.)"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "Everyday duas", "bn": "প্রতিদিনের দোয়া"}', 'general', 'easy', NULL, 10, 'in_review', 124) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b0ad5ee6-e19e-5adf-8382-60794c9cd738', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "What does the bedtime dua \"Bismika Allahumma amutu wa ahya\" mean?", "bn": "ঘুমানোর দোয়া \"বিসমিকা আল্লাহুম্মা আমুতু ওয়া আহইয়া\" অর্থ কী?"}', '{"en": "He ﷺ said it when going to bed; sleep is called a kind of death.", "bn": "নবী ﷺ শোয়ার সময় এটি বলতেন; ঘুমকে এক প্রকার মৃত্যু বলা হয়েছে।"}', 'Sahih al-Bukhari 6324', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ac43f300-16be-5a54-94b4-5e04eaf27796', 'b0ad5ee6-e19e-5adf-8382-60794c9cd738', '{"en": "In Your name, O Allah, I die and I live", "bn": "হে আল্লাহ, আপনার নামেই আমি মরি ও বাঁচি"}', true, 1), ('cd85a9b7-e029-53d3-a508-90d3b479de9a', 'b0ad5ee6-e19e-5adf-8382-60794c9cd738', '{"en": "O Allah, give me good sleep", "bn": "হে আল্লাহ, আমাকে ভালো ঘুম দিন"}', false, 2), ('fb0e134e-03e0-52b5-86a0-3159e279df85', 'b0ad5ee6-e19e-5adf-8382-60794c9cd738', '{"en": "O Allah, forgive my parents", "bn": "হে আল্লাহ, আমার বাবা-মাকে ক্ষমা করুন"}', false, 3), ('5eb987a2-dad7-5103-b98a-8b26359fec60', 'b0ad5ee6-e19e-5adf-8382-60794c9cd738', '{"en": "All praise is for Allah", "bn": "সব প্রশংসা আল্লাহর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e3f79d3d-48ba-5cd5-a7cc-ea8c4988671f', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "When is \"Alhamdu lillahil-ladhi ahyana ba‘da ma amatana wa ilayhin-nushur\" said?", "bn": "\"আলহামদু লিল্লাহিল্লাযি আহইয়ানা বা‘দা মা আমাতানা ওয়া ইলাইহিন নুশুর\" কখন পড়া হয়?"}', '{"en": "\"All praise is for Allah who gave us life after He caused us to die, and to Him is the return.\"", "bn": "\"সব প্রশংসা আল্লাহর, যিনি আমাদের মৃত্যুর পর জীবন দিলেন, আর তাঁর কাছেই ফিরে যেতে হবে।\""}', 'Sahih al-Bukhari 6324', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3772a7b9-790e-58ca-9250-f2a1cea08d4e', 'e3f79d3d-48ba-5cd5-a7cc-ea8c4988671f', '{"en": "Before eating", "bn": "খাওয়ার আগে"}', false, 1), ('c0ce7080-bc42-5425-9ec5-5f0fd2d38b16', 'e3f79d3d-48ba-5cd5-a7cc-ea8c4988671f', '{"en": "On entering the masjid", "bn": "মসজিদে প্রবেশের সময়"}', false, 2), ('5464a768-3b52-5f7a-849d-b6dccd4bb149', 'e3f79d3d-48ba-5cd5-a7cc-ea8c4988671f', '{"en": "On waking up", "bn": "ঘুম থেকে জেগে"}', true, 3), ('eeb4dcda-59d2-54cc-b96c-962d94e4fd4a', 'e3f79d3d-48ba-5cd5-a7cc-ea8c4988671f', '{"en": "When it rains", "bn": "বৃষ্টির সময়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('404ce697-d066-531b-8539-4e18241d73bd', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "What does the dua for entering the masjid, \"Allahummaftah li abwaba rahmatik\", mean?", "bn": "মসজিদে প্রবেশের দোয়া \"আল্লাহুম্মাফতাহ লি আবওয়াবা রাহমাতিক\" অর্থ কী?"}', '{"en": "\"When one of you enters the masjid, let him say: O Allah, open for me the doors of Your mercy.\"", "bn": "\"তোমাদের কেউ মসজিদে প্রবেশ করলে বলবে: হে আল্লাহ, আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন।\""}', 'Sahih Muslim 713', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('835943a6-7e3f-544d-ab9b-2ac66b27328c', '404ce697-d066-531b-8539-4e18241d73bd', '{"en": "O Allah, I ask You of Your bounty", "bn": "হে আল্লাহ, আমি আপনার অনুগ্রহ চাই"}', false, 1), ('42628066-7cc1-5bfa-83f6-b9465ff7465a', '404ce697-d066-531b-8539-4e18241d73bd', '{"en": "O Allah, open for me the doors of Your mercy", "bn": "হে আল্লাহ, আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন"}', true, 2), ('e7f68b3c-10a0-5548-8a9b-3b42a3edcedb', '404ce697-d066-531b-8539-4e18241d73bd', '{"en": "O Allah, protect me from Satan", "bn": "হে আল্লাহ, শয়তান থেকে রক্ষা করুন"}', false, 3), ('756097f7-2212-56a1-9cd1-5b1c8ee12cbc', '404ce697-d066-531b-8539-4e18241d73bd', '{"en": "O Allah, increase my knowledge", "bn": "হে আল্লাহ, আমার জ্ঞান বাড়িয়ে দিন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6d556f78-c605-5bf7-a7e8-ca55a23f2a7e', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "And on leaving the masjid, he ﷺ taught us to say…?", "bn": "আর মসজিদ থেকে বের হওয়ার সময় নবী ﷺ কী বলতে শিখিয়েছেন?"}', '{"en": "\"…and when he leaves, let him say: O Allah, I ask You of Your bounty.\"", "bn": "\"…আর বের হওয়ার সময় বলবে: হে আল্লাহ, আমি আপনার কাছে আপনার অনুগ্রহ প্রার্থনা করি।\""}', 'Sahih Muslim 713', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3bd2c4a0-dc46-51aa-ae42-99a076115187', '6d556f78-c605-5bf7-a7e8-ca55a23f2a7e', '{"en": "Allahumma inni as’aluka min fadlik", "bn": "আল্লাহুম্মা ইন্নি আসআলুকা মিন ফাদলিক"}', true, 1), ('1281e976-f458-5457-809f-213eb6a1ffdf', '6d556f78-c605-5bf7-a7e8-ca55a23f2a7e', '{"en": "Bismillahi tawakkaltu ‘alallah", "bn": "বিসমিল্লাহি তাওয়াক্কালতু আলাল্লাহ"}', false, 2), ('ccd0e03b-6a52-59cb-a404-8d40d0e8be9d', '6d556f78-c605-5bf7-a7e8-ca55a23f2a7e', '{"en": "Subhanaka Allahumma", "bn": "সুবহানাকা আল্লাহুম্মা"}', false, 3), ('0469c8ca-7e19-519c-9114-8195d8e97747', '6d556f78-c605-5bf7-a7e8-ca55a23f2a7e', '{"en": "Inna lillahi wa inna ilayhi raji‘un", "bn": "ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('acd4e7ab-ca98-57b5-b8a9-42d94988137c', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "If you forget to say Bismillah at the start of a meal, what do you say when you remember?", "bn": "খাওয়ার শুরুতে বিসমিল্লাহ বলতে ভুলে গেলে মনে পড়লে কী বলবেন?"}', '{"en": "\"…let him say: In the name of Allah, at its beginning and its end.\"", "bn": "\"…সে যেন বলে: বিসমিল্লাহি আউয়ালাহু ওয়া আখিরাহু — শুরুতে ও শেষে আল্লাহর নামে।\""}', 'Sunan Abi Dawud 3767; Jami‘ at-Tirmidhi 1858', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cc66e80b-5680-597d-b21a-c47fc0ac434c', 'acd4e7ab-ca98-57b5-b8a9-42d94988137c', '{"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}', false, 1), ('5e261c79-cc21-5c78-a3be-9822b17eb007', 'acd4e7ab-ca98-57b5-b8a9-42d94988137c', '{"en": "Nothing", "bn": "কিছুই না"}', false, 2), ('3ff6c81c-1f51-5781-afd8-c09571370440', 'acd4e7ab-ca98-57b5-b8a9-42d94988137c', '{"en": "Astaghfirullah", "bn": "আসতাগফিরুল্লাহ"}', false, 3), ('fe58834a-6960-5d08-8c79-4c476d2e97b2', 'acd4e7ab-ca98-57b5-b8a9-42d94988137c', '{"en": "Bismillahi awwalahu wa akhirahu", "bn": "বিসমিল্লাহি আউয়ালাহু ওয়া আখিরাহু"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a325f043-37a5-5d53-b566-cd7ad97d93f5', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "What does the Quranic dua for parents, \"Rabbir-hamhuma kama rabbayani saghira\", mean?", "bn": "বাবা-মায়ের জন্য কুরআনের দোয়া \"রাব্বির হামহুমা কামা রাব্বায়ানি সাগিরা\" অর্থ কী?"}', '{"en": "Al-Isra’ 17:24, right after the command to be good to parents.", "bn": "আল-ইসরা ১৭:২৪, বাবা-মায়ের সঙ্গে সদ্ব্যবহারের আদেশের ঠিক পরে।"}', 'Quran 17:24', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cc847d0b-7852-5d74-9e0f-dfeafff032f9', 'a325f043-37a5-5d53-b566-cd7ad97d93f5', '{"en": "My Lord, give them wealth", "bn": "হে আমার রব, তাঁদের সম্পদ দিন"}', false, 1), ('83869f12-a272-5296-b1c8-58d608d04385', 'a325f043-37a5-5d53-b566-cd7ad97d93f5', '{"en": "My Lord, forgive me", "bn": "হে আমার রব, আমাকে ক্ষমা করুন"}', false, 2), ('b22b7ca2-47e0-5597-a760-b6d8a0b924aa', 'a325f043-37a5-5d53-b566-cd7ad97d93f5', '{"en": "My Lord, have mercy on them as they raised me when I was small", "bn": "হে আমার রব, তাঁদের প্রতি দয়া করুন, যেমন তাঁরা শৈশবে আমাকে লালন-পালন করেছেন"}', true, 3), ('96447a5f-26da-5f8b-a157-dd7d00ae8c0b', 'a325f043-37a5-5d53-b566-cd7ad97d93f5', '{"en": "My Lord, give them long life", "bn": "হে আমার রব, তাঁদের দীর্ঘ জীবন দিন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('70b3c00f-dbd4-5b78-b949-3141243ed432', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "\"Rabbana atina fid-dunya hasanah…\" asks Allah for good in…?", "bn": "\"রাব্বানা আতিনা ফিদ দুনিয়া হাসানাহ…\" দোয়ায় কী চাওয়া হয়?"}', '{"en": "\"Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.\"", "bn": "\"হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতে কল্যাণ দিন এবং আগুনের শাস্তি থেকে রক্ষা করুন।\""}', 'Quran 2:201', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('1dd3498d-87f4-5506-b000-278025d38c1d', '70b3c00f-dbd4-5b78-b949-3141243ed432', '{"en": "This world only", "bn": "শুধু দুনিয়ার কল্যাণ"}', false, 1), ('53b86c55-7a5b-54ad-b5e6-a3226660ecdc', '70b3c00f-dbd4-5b78-b949-3141243ed432', '{"en": "This world and the Hereafter, and safety from the Fire", "bn": "দুনিয়া ও আখিরাতের কল্যাণ এবং জাহান্নাম থেকে মুক্তি"}', true, 2), ('525ee896-c06f-5ad2-807a-f29f24a816e8', '70b3c00f-dbd4-5b78-b949-3141243ed432', '{"en": "Rain", "bn": "বৃষ্টি"}', false, 3), ('40ca4c08-019a-5062-b115-d9246a823ad5', '70b3c00f-dbd4-5b78-b949-3141243ed432', '{"en": "Victory in battle", "bn": "যুদ্ধে বিজয়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('62e689e1-f609-5b5c-82da-b6a8be510e50', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "What does \"Rabbi zidni ‘ilma\" mean?", "bn": "\"রাব্বি জিদনি ইলমা\" অর্থ কী?"}', '{"en": "\"…and say: My Lord, increase me in knowledge.\"", "bn": "\"…এবং বলুন: হে আমার রব, আমার জ্ঞান বৃদ্ধি করুন।\""}', 'Quran 20:114', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('196e425a-5b00-5445-9a9a-a0199013af6f', '62e689e1-f609-5b5c-82da-b6a8be510e50', '{"en": "My Lord, increase me in knowledge", "bn": "হে আমার রব, আমার জ্ঞান বৃদ্ধি করুন"}', true, 1), ('a224d75b-3d3e-5ced-8d4f-dac7e8365ffe', '62e689e1-f609-5b5c-82da-b6a8be510e50', '{"en": "My Lord, increase my wealth", "bn": "হে আমার রব, আমার সম্পদ বাড়িয়ে দিন"}', false, 2), ('1da22a0d-3be3-50ba-96c2-77f06eb6eac0', '62e689e1-f609-5b5c-82da-b6a8be510e50', '{"en": "My Lord, make me patient", "bn": "হে আমার রব, আমাকে ধৈর্যশীল করুন"}', false, 3), ('a779c115-17c4-59b7-b800-e72941510046', '62e689e1-f609-5b5c-82da-b6a8be510e50', '{"en": "My Lord, guide my children", "bn": "হে আমার রব, আমার সন্তানদের হেদায়াত দিন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c80f71f0-6ff9-59d2-9f4e-1e3d1e69015b', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "Which words did the Prophet ﷺ say when setting off on a journey on his mount?", "bn": "বাহনে চড়ে সফরে রওনা হওয়ার সময় নবী ﷺ কোন বাক্য পড়তেন?"}', '{"en": "\"Glory be to Him who has subjected this to us, and we could not have done it ourselves; and to our Lord we will return.\"", "bn": "\"পবিত্র তিনি, যিনি এটিকে আমাদের বশীভূত করেছেন, অথচ আমরা একে বশ করতে সক্ষম ছিলাম না; আর আমরা আমাদের রবের দিকেই ফিরে যাব।\""}', 'Quran 43:13–14; Sahih Muslim 1342', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9201c336-6bdc-53ad-b638-6b0aaa9e2a2c', 'c80f71f0-6ff9-59d2-9f4e-1e3d1e69015b', '{"en": "Inna lillahi wa inna ilayhi raji‘un", "bn": "ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন"}', false, 1), ('3e66d22c-23fc-5b57-aac0-f8ad2b10d12d', 'c80f71f0-6ff9-59d2-9f4e-1e3d1e69015b', '{"en": "Rabbighfir li", "bn": "রাব্বিগফিরলি"}', false, 2), ('96c9aa84-6484-51f5-8d28-23669c57d3e5', 'c80f71f0-6ff9-59d2-9f4e-1e3d1e69015b', '{"en": "Labbayk Allahumma labbayk", "bn": "লাব্বাইক আল্লাহুম্মা লাব্বাইক"}', false, 3), ('3c7b5e8b-79aa-5e09-b89a-5486c5380ec4', 'c80f71f0-6ff9-59d2-9f4e-1e3d1e69015b', '{"en": "Subhanalladhi sakhkhara lana hadha…", "bn": "সুবহানাল্লাযি সাখখারা লানা হাযা…"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('33d86adf-dedd-5df9-a3c6-40218b042094', '3d3f46e6-bbd9-52c1-bff7-a37ad6b8caf9', '{"en": "At iftar the Prophet ﷺ said \"Dhahabadh-dhama’ wabtallatil-‘uruq…\". What does it mean?", "bn": "ইফতারের সময় নবী ﷺ বলতেন \"যাহাবায যামাউ ওয়াবতাল্লাতিল উরুক…\"। এর অর্থ কী?"}', '{"en": "Ibn ‘Umar (RA) reported he said this when breaking his fast.", "bn": "ইবনে উমর (রা.) বর্ণনা করেন, নবী ﷺ ইফতারের সময় এটি বলতেন।"}', 'Sunan Abi Dawud 2357', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7414bfb0-f289-584e-8872-f1a906a122ab', '33d86adf-dedd-5df9-a3c6-40218b042094', '{"en": "I intend to fast tomorrow", "bn": "আমি আগামীকাল রোজার নিয়ত করছি"}', false, 1), ('74d1dce5-485d-5a0f-8a75-98d25a70cc2a', '33d86adf-dedd-5df9-a3c6-40218b042094', '{"en": "O Allah, accept my prayer", "bn": "হে আল্লাহ, আমার নামাজ কবুল করুন"}', false, 2), ('907971ad-9b64-5481-8e2c-9c1da3fcd873', '33d86adf-dedd-5df9-a3c6-40218b042094', '{"en": "The thirst has gone, the veins are moistened, and the reward is certain, if Allah wills", "bn": "পিপাসা দূর হলো, শিরাগুলো সিক্ত হলো, আর ইনশাআল্লাহ সওয়াব নিশ্চিত হলো"}', true, 3), ('f760b8a6-b084-5636-855e-5b7594331e2f', '33d86adf-dedd-5df9-a3c6-40218b042094', '{"en": "Glory be to Allah, the Great", "bn": "মহান আল্লাহ পবিত্র"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "Manners of a Muslim", "bn": "মুসলিমের আদব-আখলাক"}', 'general', 'easy', NULL, 10, 'in_review', 125) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f9f07696-b000-5abf-bc3a-9f509522d5d1', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "Who should give the salam first: the one riding or the one walking?", "bn": "কে আগে সালাম দেবে: আরোহী নাকি পথচারী?"}', '{"en": "\"The rider greets the walker, the walker greets the one sitting, and the few greet the many.\"", "bn": "\"আরোহী পথচারীকে, পথচারী বসা ব্যক্তিকে এবং অল্পসংখ্যক অধিকসংখ্যককে সালাম দেবে।\""}', 'Sahih al-Bukhari 6232', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('861e0954-4cdf-501b-8eb7-53c45e48db66', 'f9f07696-b000-5abf-bc3a-9f509522d5d1', '{"en": "The one walking", "bn": "পথচারী"}', false, 1), ('d94acbc8-b251-5e32-af71-261e5dafa725', 'f9f07696-b000-5abf-bc3a-9f509522d5d1', '{"en": "The one riding", "bn": "আরোহী"}', true, 2), ('7dafb59c-2948-50aa-9f3e-33d7598163bb', 'f9f07696-b000-5abf-bc3a-9f509522d5d1', '{"en": "Whoever is older", "bn": "যে বয়সে বড়"}', false, 3), ('6356105e-8a80-5947-8bfc-c231827a9b53', 'f9f07696-b000-5abf-bc3a-9f509522d5d1', '{"en": "Neither", "bn": "কেউ না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e3f75187-a8da-5e55-b16d-d82430a33f22', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "Between a young person and an older one, who greets first?", "bn": "ছোট ও বড়র মধ্যে কে আগে সালাম দেবে?"}', '{"en": "\"The young greet the old, the passer-by greets the one sitting, and the few greet the many.\"", "bn": "\"ছোট বড়কে, পথচারী বসা ব্যক্তিকে এবং অল্পসংখ্যক অধিকসংখ্যককে সালাম দেবে।\""}', 'Sahih al-Bukhari 6231', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3c1223fb-8b7f-5202-8e04-d632909fea47', 'e3f75187-a8da-5e55-b16d-d82430a33f22', '{"en": "The older one", "bn": "বড়জন"}', false, 1), ('3dc53f35-d876-5f5c-a149-5787e089796f', 'e3f75187-a8da-5e55-b16d-d82430a33f22', '{"en": "Whoever is richer", "bn": "যে বেশি ধনী"}', false, 2), ('9bd71194-e0eb-59e1-baec-aa80881b0702', 'e3f75187-a8da-5e55-b16d-d82430a33f22', '{"en": "The younger one", "bn": "ছোটজন"}', true, 3), ('2bbe2b26-c2c0-5242-abcd-04688dff6fce', 'e3f75187-a8da-5e55-b16d-d82430a33f22', '{"en": "Whoever is taller", "bn": "যে বেশি লম্বা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('56bb0acc-b4fe-5506-bf4d-203172459157', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "How many times should you ask permission to enter, before leaving if there is no answer?", "bn": "প্রবেশের অনুমতি কতবার চাইবেন, উত্তর না পেলে ফিরে যাওয়ার আগে?"}', '{"en": "\"If one of you asks permission three times and is not given it, let him go back.\"", "bn": "\"তোমাদের কেউ তিনবার অনুমতি চেয়ে অনুমতি না পেলে সে যেন ফিরে যায়।\""}', 'Sahih al-Bukhari 6245', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('261f3f38-adf0-533c-b7c5-6437dc0ff4be', '56bb0acc-b4fe-5506-bf4d-203172459157', '{"en": "Once", "bn": "একবার"}', false, 1), ('3bdeb23c-8e42-5770-97fd-ebcea8b27c62', '56bb0acc-b4fe-5506-bf4d-203172459157', '{"en": "Ten times", "bn": "দশবার"}', false, 2), ('6cc78381-4caf-54b7-ac9e-fb3a721cdf07', '56bb0acc-b4fe-5506-bf4d-203172459157', '{"en": "Until the door opens", "bn": "দরজা খোলা পর্যন্ত"}', false, 3), ('8e2b0cf3-1f84-54a3-b452-bd1f53ed1fe9', '56bb0acc-b4fe-5506-bf4d-203172459157', '{"en": "Three times", "bn": "তিনবার"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('94710152-5b23-5ae4-8cc7-876038df923a', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "\"Whoever believes in Allah and the Last Day, let him speak good or…\"", "bn": "\"যে আল্লাহ ও শেষ দিবসে বিশ্বাস করে, সে যেন ভালো কথা বলে অথবা…\""}', '{"en": "Speak good, or stay silent.", "bn": "ভালো কথা বলো, নয়তো চুপ থাকো।"}', 'Sahih al-Bukhari 6018', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('962022f5-0d31-54bc-917d-daf3dddf8f56', '94710152-5b23-5ae4-8cc7-876038df923a', '{"en": "…keep silent", "bn": "…চুপ থাকে"}', true, 1), ('3cf02045-b2b1-5ace-b229-13fb54289fe6', '94710152-5b23-5ae4-8cc7-876038df923a', '{"en": "…speak loudly", "bn": "…জোরে বলে"}', false, 2), ('45f09881-45a2-55e8-b1b3-47c4ee7c9ddd', '94710152-5b23-5ae4-8cc7-876038df923a', '{"en": "…leave the gathering", "bn": "…মজলিস ছেড়ে চলে যায়"}', false, 3), ('91b8694f-6506-5dcb-824b-715626250c4c', '94710152-5b23-5ae4-8cc7-876038df923a', '{"en": "…write it down", "bn": "…লিখে রাখে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fa05bdc0-6890-52ac-b69d-31747cc1185e', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "\"A Muslim is one from whose tongue and hand…\"", "bn": "\"প্রকৃত মুসলিম সে, যার জিহ্বা ও হাত থেকে…\""}', '{"en": "\"The Muslim is the one from whose tongue and hand the Muslims are safe.\"", "bn": "\"মুসলিম সে, যার জিহ্বা ও হাত থেকে অন্য মুসলিমরা নিরাপদ।\""}', 'Sahih al-Bukhari 10', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c923cfce-bd3b-5e26-8559-7736e4f711e6', 'fa05bdc0-6890-52ac-b69d-31747cc1185e', '{"en": "…charity flows", "bn": "…দান প্রবাহিত হয়"}', false, 1), ('cf86ffa3-7711-532d-94de-f2f084a52564', 'fa05bdc0-6890-52ac-b69d-31747cc1185e', '{"en": "…other Muslims are safe", "bn": "…অন্য মুসলিমরা নিরাপদ থাকে"}', true, 2), ('1546e643-b941-5c1d-b9f8-e002152f6cfc', 'fa05bdc0-6890-52ac-b69d-31747cc1185e', '{"en": "…no word comes out", "bn": "…কোনো কথা বের হয় না"}', false, 3), ('c5c4284b-4230-577c-8cd2-a4240dca98e8', 'fa05bdc0-6890-52ac-b69d-31747cc1185e', '{"en": "…the Quran is heard", "bn": "…কুরআন শোনা যায়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fbb64042-0790-590b-8ad3-f5a27944adec', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "A man asked the Prophet ﷺ for advice again and again. What did he keep saying?", "bn": "এক ব্যক্তি বারবার উপদেশ চাইলে নবী ﷺ বারবার কী বলেছিলেন?"}', '{"en": "He ﷺ repeated: \"Do not become angry.\"", "bn": "নবী ﷺ বারবার বললেন: \"রাগ কোরো না।\""}', 'Sahih al-Bukhari 6116', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fc01768f-5ecd-54a9-8751-55dc9647e187', 'fbb64042-0790-590b-8ad3-f5a27944adec', '{"en": "Pray more", "bn": "বেশি নামাজ পড়ো"}', false, 1), ('d0bc477e-84e3-526e-b521-99bd45e2471a', 'fbb64042-0790-590b-8ad3-f5a27944adec', '{"en": "Fast often", "bn": "বেশি রোজা রাখো"}', false, 2), ('f6eaab89-19fd-5143-b452-517712cf898b', 'fbb64042-0790-590b-8ad3-f5a27944adec', '{"en": "Do not become angry", "bn": "রাগ কোরো না"}', true, 3), ('db53e7a2-6938-548e-b567-eeb0391f9dc8', 'fbb64042-0790-590b-8ad3-f5a27944adec', '{"en": "Travel", "bn": "সফর করো"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7f7d3d35-6af8-5226-95cd-07fca28410f0', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "The Prophet ﷺ said: \"The religion is…\"", "bn": "নবী ﷺ বলেছেন: \"দ্বীন হলো…\""}', '{"en": "\"The religion is nasihah\" — to Allah, His Book, His Messenger, the leaders of the Muslims and their common people.", "bn": "\"দ্বীন হলো নসিহত (কল্যাণকামিতা)\" — আল্লাহ, তাঁর কিতাব, তাঁর রাসুল, মুসলিম নেতৃবৃন্দ ও সাধারণ মুসলিমদের জন্য।"}', 'Sahih Muslim 55', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a230a24e-71a8-58d9-9388-338ce7795604', '7f7d3d35-6af8-5226-95cd-07fca28410f0', '{"en": "…sincere good will (nasihah)", "bn": "…কল্যাণকামিতা (নসিহত)"}', true, 1), ('7977da0e-09df-53dd-bf45-4fceb28945ec', '7f7d3d35-6af8-5226-95cd-07fca28410f0', '{"en": "…hardship", "bn": "…কঠোরতা"}', false, 2), ('56e56a36-b143-5b8f-812b-c1914038af23', '7f7d3d35-6af8-5226-95cd-07fca28410f0', '{"en": "…for scholars only", "bn": "…শুধু আলেমদের জন্য"}', false, 3), ('b5fe16bc-2818-5ae3-bb24-20ff5a1951a2', '7f7d3d35-6af8-5226-95cd-07fca28410f0', '{"en": "…rituals only", "bn": "…শুধু আনুষ্ঠানিকতা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('25016eb6-e862-540e-be12-6dd4cc367c67', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "Signs of a hypocrite: when he speaks he lies, when he promises he breaks it, and when he is trusted he…?", "bn": "মুনাফিকের আলামত: কথা বললে মিথ্যা বলে, ওয়াদা করলে ভঙ্গ করে, আর আমানত রাখলে…?"}', '{"en": "\"The signs of a hypocrite are three: when he speaks he lies, when he promises he breaks it, and when he is trusted he betrays.\"", "bn": "\"মুনাফিকের আলামত তিনটি: কথা বললে মিথ্যা বলে, ওয়াদা করলে ভঙ্গ করে, আমানত রাখলে খেয়ানত করে।\""}', 'Sahih al-Bukhari 33', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('2cecf544-28de-583c-a716-42fd4938e44c', '25016eb6-e862-540e-be12-6dd4cc367c67', '{"en": "Returns it", "bn": "ফেরত দেয়"}', false, 1), ('cfac2205-441f-5605-9526-5d96dc2d4de2', '25016eb6-e862-540e-be12-6dd4cc367c67', '{"en": "Forgets", "bn": "ভুলে যায়"}', false, 2), ('91243704-ff7f-5870-b5ba-0550cb11a62a', '25016eb6-e862-540e-be12-6dd4cc367c67', '{"en": "Prays", "bn": "নামাজ পড়ে"}', false, 3), ('2f1c5c9b-c274-5c3a-85b0-69f4068116a1', '25016eb6-e862-540e-be12-6dd4cc367c67', '{"en": "Betrays the trust", "bn": "খেয়ানত করে"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1d4f0471-3164-53ce-9a5e-d9cf60434b03', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "What did the Prophet ﷺ forbid while drinking?", "bn": "পান করার সময় নবী ﷺ কী নিষেধ করেছেন?"}', '{"en": "\"When one of you drinks, let him not breathe into the vessel.\"", "bn": "\"তোমাদের কেউ পান করার সময় যেন পাত্রে নিঃশ্বাস না ফেলে।\""}', 'Sahih al-Bukhari 5630', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('534ab2d3-6b57-56f2-a09a-85d6340c2016', '1d4f0471-3164-53ce-9a5e-d9cf60434b03', '{"en": "Saying Bismillah", "bn": "বিসমিল্লাহ বলা"}', false, 1), ('f18df9ec-2af8-53de-9873-34be0d54389b', '1d4f0471-3164-53ce-9a5e-d9cf60434b03', '{"en": "Breathing into the vessel", "bn": "পাত্রের মধ্যে নিঃশ্বাস ফেলা"}', true, 2), ('babf996d-79be-5009-bf96-74bde8c4f8e5', '1d4f0471-3164-53ce-9a5e-d9cf60434b03', '{"en": "Using the right hand", "bn": "ডান হাত ব্যবহার করা"}', false, 3), ('ab7c481a-454d-59d6-b886-caf3ecc502c2', '1d4f0471-3164-53ce-9a5e-d9cf60434b03', '{"en": "Drinking water", "bn": "পানি পান করা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8e478395-174e-582d-98b1-99346d618f55', 'a10a53c1-6c79-5d1e-b2d4-df2df0c3eee4', '{"en": "Besides mocking others, Surah al-Hujurat 49:11 also forbids…?", "bn": "অন্যকে উপহাস করা ছাড়াও সূরা হুজুরাত ৪৯:১১ আর কী নিষেধ করে?"}', '{"en": "\"…and do not insult one another, and do not call each other by (offensive) nicknames.\"", "bn": "\"…তোমরা একে অপরের নিন্দা কোরো না এবং একে অপরকে মন্দ নামে ডেকো না।\""}', 'Quran 49:11', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('60ad7b04-07a1-5cb8-9afa-cb6d1d4ec35c', '8e478395-174e-582d-98b1-99346d618f55', '{"en": "Calling one another by offensive nicknames", "bn": "একে অপরকে মন্দ নামে ডাকা"}', true, 1), ('66d146b5-ae32-579f-8579-96ae160bf4c1', '8e478395-174e-582d-98b1-99346d618f55', '{"en": "Greeting strangers", "bn": "অপরিচিতকে সালাম দেওয়া"}', false, 2), ('1015a5f9-c25b-5b0f-8f51-fe9d9da6fd8e', '8e478395-174e-582d-98b1-99346d618f55', '{"en": "Visiting the sick", "bn": "রোগী দেখতে যাওয়া"}', false, 3), ('6f6950ba-1799-5c60-9bed-bc51720f939a', '8e478395-174e-582d-98b1-99346d618f55', '{"en": "Smiling", "bn": "হাসিমুখে থাকা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "Islamic months & special days", "bn": "ইসলামিক মাস ও বিশেষ দিন"}', 'general', 'medium', NULL, 10, 'in_review', 126) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6cf6feec-37ca-52b7-9d97-e7ce464641c9', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "Which of these is NOT one of the four sacred months?", "bn": "নিচের কোনটি চার সম্মানিত মাসের একটি নয়?"}', '{"en": "The sacred months: Dhul Qa‘dah, Dhul Hijjah, Muharram and Rajab. Ramadan is blessed, but not one of the four.", "bn": "সম্মানিত মাস: জিলকদ, জিলহজ, মহররম ও রজব। রমজান বরকতময়, তবে এই চারটির একটি নয়।"}', 'Sahih al-Bukhari 3197; Quran 9:36', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('83e04650-e096-5137-bfe2-aa075764fcf7', '6cf6feec-37ca-52b7-9d97-e7ce464641c9', '{"en": "Rajab", "bn": "রজব"}', false, 1), ('0f26391f-c76f-5ded-8b07-a244bacca2ff', '6cf6feec-37ca-52b7-9d97-e7ce464641c9', '{"en": "Muharram", "bn": "মহররম"}', false, 2), ('6eb62dd9-69f2-5ea9-ae51-584ea728e921', '6cf6feec-37ca-52b7-9d97-e7ce464641c9', '{"en": "Ramadan", "bn": "রমজান"}', true, 3), ('74d99940-3773-5789-acd0-87af39e0e988', '6cf6feec-37ca-52b7-9d97-e7ce464641c9', '{"en": "Dhul Qa‘dah", "bn": "জিলকদ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('91baabe7-0743-5e0c-8481-2490bd6dd6af', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "Which month comes right before Ramadan?", "bn": "রমজানের ঠিক আগের মাস কোনটি?"}', '{"en": "Rajab (7th), Sha‘ban (8th), then Ramadan (9th).", "bn": "রজব (৭ম), শাবান (৮ম), তারপর রমজান (৯ম)।"}', 'The Hijri calendar', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('bb5b6f3f-945a-5e3a-b5f9-d20e43688652', '91baabe7-0743-5e0c-8481-2490bd6dd6af', '{"en": "Shawwal", "bn": "শাওয়াল"}', false, 1), ('8fcd5c1b-9aa9-572c-91ec-9c0ef6b91880', '91baabe7-0743-5e0c-8481-2490bd6dd6af', '{"en": "Sha‘ban", "bn": "শাবান"}', true, 2), ('dc7ad876-29f0-5db6-9caf-3ecbbbd11b8a', '91baabe7-0743-5e0c-8481-2490bd6dd6af', '{"en": "Rajab", "bn": "রজব"}', false, 3), ('1ce725d7-5a2b-5746-bb20-76d09aca4595', '91baabe7-0743-5e0c-8481-2490bd6dd6af', '{"en": "Muharram", "bn": "মহররম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('3cc7b484-5aef-5b22-a049-13ead9d998c4', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "Which is the third month of the Hijri year?", "bn": "হিজরি বছরের তৃতীয় মাস কোনটি?"}', '{"en": "Muharram, Safar, Rabi‘ al-Awwal, Rabi‘ ath-Thani, Jumada al-Ula, Jumada al-Akhirah, Rajab, Sha‘ban, Ramadan, Shawwal, Dhul Qa‘dah, Dhul Hijjah.", "bn": "মহররম, সফর, রবিউল আউয়াল, রবিউস সানি, জমাদিউল আউয়াল, জমাদিউস সানি, রজব, শাবান, রমজান, শাওয়াল, জিলকদ, জিলহজ।"}', 'The Hijri calendar', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('28484c39-92b1-5b60-9b6c-fbd3ff7ca2a8', '3cc7b484-5aef-5b22-a049-13ead9d998c4', '{"en": "Safar", "bn": "সফর"}', false, 1), ('a32944b8-2859-5849-b3da-71ceebbab0f6', '3cc7b484-5aef-5b22-a049-13ead9d998c4', '{"en": "Jumada al-Ula", "bn": "জমাদিউল আউয়াল"}', false, 2), ('347a9bfa-54e0-5b66-baeb-758610739330', '3cc7b484-5aef-5b22-a049-13ead9d998c4', '{"en": "Rabi‘ ath-Thani", "bn": "রবিউস সানি"}', false, 3), ('555577ad-7c56-5d30-8d72-cee844da0ba6', '3cc7b484-5aef-5b22-a049-13ead9d998c4', '{"en": "Rabi‘ al-Awwal", "bn": "রবিউল আউয়াল"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9bccba6b-c948-5f1e-84a2-35794cbdb07e', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "Which is the twelfth and last month of the Hijri year?", "bn": "হিজরি বছরের দ্বাদশ ও শেষ মাস কোনটি?"}', '{"en": "Dhul Hijjah, the month of Hajj, ends the year; Muharram begins the next.", "bn": "হজের মাস জিলহজ দিয়ে বছর শেষ হয়; পরের বছর শুরু হয় মহররম দিয়ে।"}', 'The Hijri calendar', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cb6a0e1a-604a-53ec-a9a9-a88db655a49c', '9bccba6b-c948-5f1e-84a2-35794cbdb07e', '{"en": "Dhul Hijjah", "bn": "জিলহজ"}', true, 1), ('2387ddf5-1836-5739-92c5-e582ae58e883', '9bccba6b-c948-5f1e-84a2-35794cbdb07e', '{"en": "Dhul Qa‘dah", "bn": "জিলকদ"}', false, 2), ('ccb5a26a-7e26-5a5a-8b96-cfced57f08de', '9bccba6b-c948-5f1e-84a2-35794cbdb07e', '{"en": "Shawwal", "bn": "শাওয়াল"}', false, 3), ('34c9cb70-a53b-5008-900c-527a4d090642', '9bccba6b-c948-5f1e-84a2-35794cbdb07e', '{"en": "Muharram", "bn": "মহররম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7270f0b9-b90c-5dc2-b524-7870dfd29bef', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "Which month comes right after Shawwal?", "bn": "শাওয়ালের ঠিক পরের মাস কোনটি?"}', '{"en": "Shawwal (10th), Dhul Qa‘dah (11th), Dhul Hijjah (12th).", "bn": "শাওয়াল (১০ম), জিলকদ (১১তম), জিলহজ (১২তম)।"}', 'The Hijri calendar', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('50d9cc7b-886c-56a9-936b-f6d68f4e3e89', '7270f0b9-b90c-5dc2-b524-7870dfd29bef', '{"en": "Ramadan", "bn": "রমজান"}', false, 1), ('8c716098-5552-5142-a1c4-f26ae110ed4c', '7270f0b9-b90c-5dc2-b524-7870dfd29bef', '{"en": "Dhul Hijjah", "bn": "জিলহজ"}', false, 2), ('c4a492a1-8293-535e-a36c-8b89d99e4533', '7270f0b9-b90c-5dc2-b524-7870dfd29bef', '{"en": "Dhul Qa‘dah", "bn": "জিলকদ"}', true, 3), ('977a5c55-b78a-5b18-b0bb-ebe22b2a5b3a', '7270f0b9-b90c-5dc2-b524-7870dfd29bef', '{"en": "Safar", "bn": "সফর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b914102c-4e4a-5f4b-b771-5379f99535f4', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "The best days for good deeds, the Prophet ﷺ said, are the first ten days of which month?", "bn": "নবী ﷺ বলেছেন, নেক আমলের জন্য সর্বোত্তম দিন কোন মাসের প্রথম দশ দিন?"}', '{"en": "\"There are no days in which righteous deeds are more beloved to Allah than these ten days\" — the first ten of Dhul Hijjah.", "bn": "\"এই দশ দিনের চেয়ে বেশি প্রিয় নেক আমলের দিন আল্লাহর কাছে আর নেই\" — জিলহজের প্রথম দশ দিন।"}', 'Sahih al-Bukhari 969; Sunan Abi Dawud 2438', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8cfacdfc-28e2-55ea-98c9-147b7c510111', 'b914102c-4e4a-5f4b-b771-5379f99535f4', '{"en": "Ramadan", "bn": "রমজান"}', false, 1), ('c8ef3619-136e-5372-ac88-888daf9c6564', 'b914102c-4e4a-5f4b-b771-5379f99535f4', '{"en": "Muharram", "bn": "মহররম"}', false, 2), ('a5f9c1db-a188-538c-b074-f38abd0f0e54', 'b914102c-4e4a-5f4b-b771-5379f99535f4', '{"en": "Rajab", "bn": "রজব"}', false, 3), ('43cff8f7-bb51-5737-87a8-33b7e4f984ff', 'b914102c-4e4a-5f4b-b771-5379f99535f4', '{"en": "Dhul Hijjah", "bn": "জিলহজ"}', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('66174600-17d6-563c-8dd2-649fcb816a15', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "How many days can a Hijri month have?", "bn": "একটি হিজরি মাস কত দিনের হয়?"}', '{"en": "\"The month is like this and this\" — he ﷺ showed twenty-nine one time and thirty another.", "bn": "\"মাস এত এত দিনের\" — নবী ﷺ হাতের ইশারায় একবার উনত্রিশ আর একবার ত্রিশ দেখালেন।"}', 'Sahih al-Bukhari 1913', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ec62ce1b-8452-5061-b9d6-80ffe01ae8cb', '66174600-17d6-563c-8dd2-649fcb816a15', '{"en": "29 or 30", "bn": "২৯ বা ৩০"}', true, 1), ('21a15954-b1a2-5fa0-85ed-398aac89fe00', '66174600-17d6-563c-8dd2-649fcb816a15', '{"en": "Always 30", "bn": "সবসময় ৩০"}', false, 2), ('0400a529-1d54-5c90-9cca-d4c699e2c52b', '66174600-17d6-563c-8dd2-649fcb816a15', '{"en": "28 to 31", "bn": "২৮ থেকে ৩১"}', false, 3), ('a0d80f57-f4dd-535f-a8bc-c2bbb0496391', '66174600-17d6-563c-8dd2-649fcb816a15', '{"en": "Always 29", "bn": "সবসময় ২৯"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('931f2de9-7f06-56e4-b664-cb0b64d258ee', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "About how many days long is a Hijri (lunar) year?", "bn": "একটি হিজরি (চান্দ্র) বছর প্রায় কত দিনের?"}', '{"en": "Twelve lunar months make about 354 days, so Ramadan comes about 11 days earlier each solar year.", "bn": "বারোটি চান্দ্রমাসে প্রায় ৩৫৪ দিন, তাই প্রতি সৌরবছরে রমজান প্রায় ১১ দিন এগিয়ে আসে।"}', 'Quran 10:5; Quran 9:36', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('dd75c004-081e-585d-8373-01a00098d62e', '931f2de9-7f06-56e4-b664-cb0b64d258ee', '{"en": "365", "bn": "৩৬৫"}', false, 1), ('d2814514-8ed8-5aae-ac79-82fbc992f068', '931f2de9-7f06-56e4-b664-cb0b64d258ee', '{"en": "About 354", "bn": "প্রায় ৩৫৪"}', true, 2), ('759607da-da99-5a5b-8cdf-ae77d70c7184', '931f2de9-7f06-56e4-b664-cb0b64d258ee', '{"en": "300", "bn": "৩০০"}', false, 3), ('6b26023e-c5f0-5ce7-9822-bbe5271c554e', '931f2de9-7f06-56e4-b664-cb0b64d258ee', '{"en": "400", "bn": "৪০০"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5dbbd689-50e7-5bfc-9584-bdc6f6bd0407', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "Which sacred month stands alone, not next to the other three?", "bn": "কোন সম্মানিত মাসটি বাকি তিনটির সঙ্গে লাগোয়া নয়, আলাদা?"}', '{"en": "\"Three in a row — Dhul Qa‘dah, Dhul Hijjah and Muharram — and Rajab of Mudar, between Jumada and Sha‘ban.\"", "bn": "\"তিনটি পরপর — জিলকদ, জিলহজ ও মহররম — আর মুদার গোত্রের রজব, যা জমাদিউস সানি ও শাবানের মাঝে।\""}', 'Sahih al-Bukhari 3197', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('569572c5-e0b9-5c26-87c7-e0f6754cfa57', '5dbbd689-50e7-5bfc-9584-bdc6f6bd0407', '{"en": "Muharram", "bn": "মহররম"}', false, 1), ('d0e98fc2-eaa1-56aa-8c42-882d8489ef91', '5dbbd689-50e7-5bfc-9584-bdc6f6bd0407', '{"en": "Dhul Hijjah", "bn": "জিলহজ"}', false, 2), ('8ebc344a-2012-5d61-ac54-e7c7c1732d91', '5dbbd689-50e7-5bfc-9584-bdc6f6bd0407', '{"en": "Rajab", "bn": "রজব"}', true, 3), ('9ebf2a0e-1776-5dfa-9e4c-8f85b848f659', '5dbbd689-50e7-5bfc-9584-bdc6f6bd0407', '{"en": "Dhul Qa‘dah", "bn": "জিলকদ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('acf628ed-ad0d-5014-aaf9-0f60b939b7b9', 'cdfdd60a-7ce6-5d55-bba2-b0f798c6cc04', '{"en": "On which day of the week was Adam (AS) created, according to the hadith?", "bn": "হাদিস অনুযায়ী আদম (আ.)-কে সপ্তাহের কোন দিন সৃষ্টি করা হয়েছিল?"}', '{"en": "\"The best day on which the sun rises is Friday: on it Adam was created, on it he entered Paradise…\"", "bn": "\"সূর্য উদিত হওয়া দিনগুলোর মধ্যে সর্বোত্তম শুক্রবার: এদিন আদম (আ.)-কে সৃষ্টি করা হয়, এদিন তাঁকে জান্নাতে প্রবেশ করানো হয়…\""}', 'Sahih Muslim 854', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('311b0fc8-fb95-5bd4-8543-2cb6784b2eae', 'acf628ed-ad0d-5014-aaf9-0f60b939b7b9', '{"en": "Monday", "bn": "সোমবার"}', false, 1), ('a4c7860c-a23a-54b5-8ca6-8ce2964947a4', 'acf628ed-ad0d-5014-aaf9-0f60b939b7b9', '{"en": "Saturday", "bn": "শনিবার"}', false, 2), ('6eeba4d7-bccd-57d3-addc-9884567cc309', 'acf628ed-ad0d-5014-aaf9-0f60b939b7b9', '{"en": "Wednesday", "bn": "বুধবার"}', false, 3), ('bd0fa1e4-9f1a-57a4-8852-b3a73d90bd23', 'acf628ed-ad0d-5014-aaf9-0f60b939b7b9', '{"en": "Friday", "bn": "শুক্রবার"}', true, 4) ON CONFLICT (id) DO NOTHING;
